// --- פתק שבועי עדין במסך הבית - נכתב פעם (או כמה פעמים) בשבוע ונשאר מוצג
// עד שנערך שוב, בלי איפוס אוטומטי - "משהו שרוצים ללכת איתו כל השבוע", לפי
// בקשה מפורשת. אותו דפוס בדיוק כמו שאר טאבי-ההצצה: localStorage לתגובה
// מיידית + סנכרון ל-user_premium (null בעמודות = "עוד לא סונכרן") ---
// הטקסט נשמר גם במכשיר ומוצג מיד בפתיחה - כך שהפתק לא "נעלם" גם אם הטעינה מהשרת
// מתעכבת/נכשלת (דווח שהפתק נראה נמחק ביום חדש). הוא משתנה רק כשעורכים אותו
const WEEKLY_NOTE_CACHE_KEY = 'weekwise_weekly_note_text';
// --- 🍎 בחלון הפתקים (קיצור להוספת ארוחה שמורה) - דלוק כברירת מחדל, אפשר להסתיר
// בהגדרות. אותו דפוס בדיוק כמו שאר המתגים: localStorage מיידי + user_premium לסנכרון ---
function isQuickNoteAppleOn() { return localStorage.getItem('weekwise_quick_note_apple') !== 'false'; }
function applyQuickNoteAppleSetting() {
    const on = isQuickNoteAppleOn();
    const btn = document.getElementById('quick-note-apple-btn');
    if (btn) btn.classList.toggle('hidden', !on);
    const toggle = document.getElementById('quick-note-apple-toggle');
    if (toggle) toggle.checked = on;
}
async function loadQuickNoteAppleSetting() {
    if (!supabaseClient || !currentUserId) return;
    const { data } = await supabaseClient.from('user_premium').select('quick_note_apple_enabled').eq('user_id', currentUserId).maybeSingle();
    if (!data || data.quick_note_apple_enabled === null || data.quick_note_apple_enabled === undefined) return;
    localStorage.setItem('weekwise_quick_note_apple', String(data.quick_note_apple_enabled));
    applyQuickNoteAppleSetting();
}
async function toggleQuickNoteApple() {
    const enabled = document.getElementById('quick-note-apple-toggle').checked;
    localStorage.setItem('weekwise_quick_note_apple', String(enabled));
    applyQuickNoteAppleSetting();
    if (supabaseClient && currentUserId) {
        await supabaseClient.from('user_premium').upsert(
            { user_id: currentUserId, username: currentUsername, quick_note_apple_enabled: enabled },
            { onConflict: 'user_id' },
        );
    }
}

let currentWeeklyNoteText = (() => { try { return localStorage.getItem(WEEKLY_NOTE_CACHE_KEY) || ''; } catch { return ''; } })();
// רשימה לסימון בפתק (0-3 שורות) - כל שורה {text, done}; נשמרת כמו הטקסט: מטמון במכשיר + user_premium
let currentWeeklyNoteItems = (() => { try { return JSON.parse(localStorage.getItem('weekwise_weekly_note_items') || '[]'); } catch { return []; } })();
let currentWeeklyNoteItemCount = (() => { try { return parseInt(localStorage.getItem('weekwise_weekly_note_item_count'), 10) || 0; } catch { return 0; } })();
function cacheWeeklyNoteItems() {
    try {
        localStorage.setItem('weekwise_weekly_note_items', JSON.stringify(currentWeeklyNoteItems));
        localStorage.setItem('weekwise_weekly_note_item_count', String(currentWeeklyNoteItemCount));
    } catch {}
}
function isWeeklyNoteOn() { return localStorage.getItem('weekwise_weekly_note_enabled') !== 'false'; }
async function loadWeeklyNoteSetting() {
    if (!supabaseClient || !currentUserId) return;
    const { data, error } = await supabaseClient.from('user_premium').select('weekly_note_enabled, weekly_note_text, weekly_note_color, weekly_note_shape, weekly_note_items, weekly_note_item_count').eq('user_id', currentUserId).maybeSingle();
    if (data && data.weekly_note_enabled !== null && data.weekly_note_enabled !== undefined) {
        localStorage.setItem('weekwise_weekly_note_enabled', String(data.weekly_note_enabled));
    }
    // טעינה שנכשלה לא מוחקת את הפתק שכבר מוצג (מהמטמון) - רק תשובה אמיתית מהשרת מחליפה אותו
    if (!error && data) {
        currentWeeklyNoteText = data.weekly_note_text || '';
        try { localStorage.setItem(WEEKLY_NOTE_CACHE_KEY, currentWeeklyNoteText); } catch {}
        if (Array.isArray(data.weekly_note_items)) currentWeeklyNoteItems = data.weekly_note_items;
        if (data.weekly_note_item_count !== null && data.weekly_note_item_count !== undefined) currentWeeklyNoteItemCount = data.weekly_note_item_count;
        cacheWeeklyNoteItems();
    }
    currentWeeklyNoteColor = (data && data.weekly_note_color) || null;
    currentWeeklyNoteShape = (data && data.weekly_note_shape) || null;
    applyWeeklyNoteSetting();
    applyWeeklyNoteStyle();
    renderWeeklyNoteDisplay();
}
async function toggleWeeklyNote() {
    const enabled = document.getElementById('weekly-note-toggle').checked;
    localStorage.setItem('weekwise_weekly_note_enabled', String(enabled));
    applyWeeklyNoteSetting();
    if (supabaseClient && currentUserId) {
        await supabaseClient.from('user_premium').upsert(
            { user_id: currentUserId, username: currentUsername, weekly_note_enabled: enabled },
            { onConflict: 'user_id' },
        );
    }
}
function applyWeeklyNoteSetting() {
    const widget = document.getElementById('weekly-note-widget');
    const toggle = document.getElementById('weekly-note-toggle');
    const enabled = isWeeklyNoteOn();
    if (widget) widget.classList.toggle('hidden', !enabled);
    if (toggle) toggle.checked = enabled;
}

// --- התאמה אישית של הפתק (צבע + סגנון/צורה) - אופציונלי, לפי בקשה מפורשת
// ("4 צבעים וגם אפשרות לשנות צורה... חוץ מהברירת מחדל שזה הרגיל עם ערכת
// הנושא... שמי שרוצה להחליף שיחליף"). ברירת המחדל (null) היא בדיוק המראה
// הקיים (רקע ניטרלי לפי ערכת הנושא + נייר-דבק בפינה) - לא משתנה כלום למי
// שלא בוחר בפעם הראשונה. אותו דפוס בדיוק כמו applyGlobalTextColor/
// renderGlobalTextColorSwatches (default+presets, סנכרון ל-user_premium) -
// ממוקם מקונן בתוך הגדרות הפתק עצמו (לא טוגלים נפרדים ברשימה הראשית), לפי
// בקשה מפורשת ("שלא יהיה הרבה בלגן")
let currentWeeklyNoteColor = null;
let currentWeeklyNoteShape = null;
const WEEKLY_NOTE_COLOR_PRESETS = ['yellow', 'pink', 'mint', 'blue'];
const WEEKLY_NOTE_SHAPE_PRESETS = ['round', 'circle', 'ribbon', 'card'];
function applyWeeklyNoteStyle() {
    const widget = document.getElementById('weekly-note-widget');
    if (widget) {
        WEEKLY_NOTE_COLOR_PRESETS.forEach(c => widget.classList.remove(`weekly-note-color-${c}`));
        if (currentWeeklyNoteColor) widget.classList.add(`weekly-note-color-${currentWeeklyNoteColor}`);
        WEEKLY_NOTE_SHAPE_PRESETS.forEach(s => widget.classList.remove(`weekly-note-shape-${s}`));
        if (currentWeeklyNoteShape) widget.classList.add(`weekly-note-shape-${currentWeeklyNoteShape}`);
    }
    renderWeeklyNoteColorSwatches();
    renderWeeklyNoteShapeSwatches();
}
function renderWeeklyNoteColorSwatches() {
    const wrap = document.getElementById('weekly-note-color-swatches');
    if (!wrap) return;
    wrap.innerHTML = '';
    const defaultBtn = document.createElement('button');
    defaultBtn.type = 'button';
    defaultBtn.className = 'note-color-swatch note-color-swatch-default' + (!currentWeeklyNoteColor ? ' selected' : '');
    defaultBtn.title = t('note_text_color_default');
    defaultBtn.textContent = '↺';
    defaultBtn.onclick = () => selectWeeklyNoteColor(null);
    wrap.appendChild(defaultBtn);
    WEEKLY_NOTE_COLOR_PRESETS.forEach(colorKey => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `note-color-swatch weekly-note-color-swatch-${colorKey}` + (currentWeeklyNoteColor === colorKey ? ' selected' : '');
        btn.onclick = () => selectWeeklyNoteColor(colorKey);
        wrap.appendChild(btn);
    });
}
async function selectWeeklyNoteColor(colorKey) {
    currentWeeklyNoteColor = colorKey;
    applyWeeklyNoteStyle();
    localStorage.setItem('weekwise_weekly_note_color', colorKey || '');
    if (supabaseClient && currentUserId) {
        await supabaseClient.from('user_premium').upsert(
            { user_id: currentUserId, username: currentUsername, weekly_note_color: colorKey },
            { onConflict: 'user_id' },
        );
    }
}
function renderWeeklyNoteShapeSwatches() {
    const wrap = document.getElementById('weekly-note-shape-swatches');
    if (!wrap) return;
    wrap.innerHTML = '';
    const defaultBtn = document.createElement('button');
    defaultBtn.type = 'button';
    defaultBtn.className = 'note-color-swatch note-color-swatch-default' + (!currentWeeklyNoteShape ? ' selected' : '');
    defaultBtn.title = t('note_text_color_default');
    defaultBtn.textContent = '↺';
    defaultBtn.onclick = () => selectWeeklyNoteShape(null);
    wrap.appendChild(defaultBtn);
    WEEKLY_NOTE_SHAPE_PRESETS.forEach(shapeKey => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `note-shape-swatch note-shape-swatch-${shapeKey}` + (currentWeeklyNoteShape === shapeKey ? ' selected' : '');
        btn.onclick = () => selectWeeklyNoteShape(shapeKey);
        wrap.appendChild(btn);
    });
}
async function selectWeeklyNoteShape(shapeKey) {
    currentWeeklyNoteShape = shapeKey;
    applyWeeklyNoteStyle();
    localStorage.setItem('weekwise_weekly_note_shape', shapeKey || '');
    if (supabaseClient && currentUserId) {
        await supabaseClient.from('user_premium').upsert(
            { user_id: currentUserId, username: currentUsername, weekly_note_shape: shapeKey },
            { onConflict: 'user_id' },
        );
    }
}
// גודל הגופן יורד בהדרגה לפי אורך הטקסט כדי שהכל יכנס בפתק הקטן בלי להיחתך -
// לפי בקשה מפורשת ("כתבתי ולא הכל נכנס... גם אם ארוך פשוט להקטין את
// האותיות"). מוגבל ל-60 תווים גם בטקסטאזור עצמו (ר' index.html) כדי שגם
// בשלב-הגופן-הקטן-ביותר זה עדיין יישאר קריא בתוך פתק 104x104 פיקסלים
function renderWeeklyNoteDisplay() {
    const display = document.getElementById('weekly-note-display');
    if (!display) return;
    const text = currentWeeklyNoteText.trim();
    const items = currentWeeklyNoteItems.slice(0, currentWeeklyNoteItemCount).map((item, index) => ({ ...item, index })).filter(item => (item.text || '').trim());
    const widget = document.getElementById('weekly-note-widget');
    if (widget) widget.classList.toggle('weekly-note-has-items', items.length > 0);
    // פתק ריק מתקפל לסיכה קטנה "פתק לשבוע" במסך הבית (לפי בחירה מפורשת), לחיצה פותחת את העריכה
    const slot = document.getElementById('home-weekly-note-slot');
    if (slot) slot.classList.toggle('is-empty', !items.length && !text);
    if (items.length) {
        // שורות לסימון + טקסט חופשי מתחת (אם נכתב). ✓ מסמן ישר מהפתק בלי לפתוח את העריכה
        const totalLength = items.reduce((sum, item) => sum + item.text.length, 0) + text.length;
        display.innerHTML = `<ul class="weekly-note-items">${items.map(item => `
            <li class="${item.done ? 'done' : ''}"><button type="button" class="weekly-note-check" onclick="event.stopPropagation(); toggleWeeklyNoteItem(${item.index})" aria-pressed="${item.done ? 'true' : 'false'}">${item.done ? '✓' : ''}</button><span>${escapeHtmlForReport(item.text)}</span></li>`).join('')}
        </ul>${text ? `<div class="weekly-note-free">${escapeHtmlForReport(text)}</div>` : ''}`;
        display.classList.remove('weekly-note-display-empty');
        display.removeAttribute('aria-label');
        display.style.fontSize = (totalLength > 70 ? 0.6 : totalLength > 45 ? 0.66 : 0.72) + 'rem';
        fitWeeklyNoteText(display);
        return;
    }
    // פתק ריק: רק עיפרון קטן ועדין בפינה, בלי מילים (לפי בקשה מפורשת: "את העיפרון לשים בצד
    // ובקטן יותר") - ההסבר המלא נשאר לקוראי מסך
    if (!text) {
        display.innerHTML = `<span class="weekly-note-pencil" aria-hidden="true">${EDIT_ICON_SVG}</span>`;
        display.classList.add('weekly-note-display-empty');
        display.setAttribute('aria-label', t('weekly_note_empty_hint'));
        display.style.fontSize = '';
        return;
    }
    display.textContent = text;
    display.classList.remove('weekly-note-display-empty');
    display.removeAttribute('aria-label');
    // הוגדל לפי בקשה מפורשת ("תגדיל את הפונט בפתקים") - כל מדרגה גדלה
    // בהתאמה, עדיין יורדת בהדרגה לפי אורך הטקסט כדי שהכל יכנס בלי להיחתך
    let fontSize = 0.85;
    if (text.length > 45) fontSize = 0.6;
    else if (text.length > 32) fontSize = 0.68;
    else if (text.length > 20) fontSize = 0.76;
    display.style.fontSize = fontSize + 'rem';
    fitWeeklyNoteText(display);
}
// המדרגות למעלה הן רק נקודת התחלה: כאן מודדים בפועל ומקטינים עד שהכול נכנס בפתק. רוחב
// האותיות שונה בין דפדפנים ומכשירים - דווח שבדפדפן במחשב המילים יצאו מהפתק ובנייד לא
function fitWeeklyNoteText(display) {
    // מדידה מיידית (קריאת scrollHeight מכריחה פריסה) - לא requestAnimationFrame, שלא רץ
    // בטאב ברקע. פתק מוסתר לא נמדד; הוא מותאם שוב כשהגופן נטען או כשגודל החלון משתנה
    if (!display.isConnected || !display.offsetParent) return;
    let px = parseFloat(getComputedStyle(display).fontSize);
    for (let i = 0; i < 40 && px > 7 && (display.scrollHeight > display.clientHeight + 1 || display.scrollWidth > display.clientWidth + 1); i++) {
        px -= 0.5;
        display.style.fontSize = px + 'px';
    }
}
// אחרי שהגופן נטען (הוא רחב מהגופן הזמני) ובשינוי גודל חלון - מתאימים את הפתק מחדש
if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { if (typeof currentWeeklyNoteText === 'string') renderWeeklyNoteDisplay(); });
let weeklyNoteResizeTimer = null;
window.addEventListener('resize', () => {
    clearTimeout(weeklyNoteResizeTimer);
    weeklyNoteResizeTimer = setTimeout(() => { if (typeof currentWeeklyNoteText === 'string') renderWeeklyNoteDisplay(); }, 200);
});
// מודל רגיל (apple-modal) לעריכה - לא בלון-צף מותאם-אישית (position:absolute)
// כמו בגרסה הקודמת, אחרי שדווח שאי אפשר היה להקליד בתוכו בפועל. מודל רגיל
// הוא רכיב בדוק ואמין שכבר בשימוש בכל שאר האפליקציה, בלי הסיכונים של
// מיקום-מוחלט מותאם-אישית (z-index/עכבר-לכידה של רכיבים אחרים)
function startEditWeeklyNote() {
    const textarea = document.getElementById('weekly-note-textarea');
    if (!textarea) return;
    textarea.value = currentWeeklyNoteText;
    const panel = document.getElementById('weekly-note-customize');
    if (panel) panel.classList.add('hidden');
    const gear = document.getElementById('weekly-note-gear');
    if (gear) gear.classList.remove('active');
    renderWeeklyNoteItemsEditor(currentWeeklyNoteItems.map(item => item.text || ''));
    renderWeeklyNoteItemCountChips();
    renderWeeklyNoteColorSwatches();
    renderWeeklyNoteShapeSwatches();
    openModal('modal-weekly-note');
    const firstInput = document.querySelector('#weekly-note-items-edit input');
    (firstInput || textarea).focus();
}
function toggleWeeklyNoteSettingsPanel() {
    const panel = document.getElementById('weekly-note-customize');
    if (!panel) return;
    panel.classList.toggle('hidden');
    const gear = document.getElementById('weekly-note-gear');
    if (gear) gear.classList.toggle('active', !panel.classList.contains('hidden'));
}
// שורות העריכה של הרשימה לסימון - לפי הכמות שנבחרה בהגדרות (0-3)
function renderWeeklyNoteItemsEditor(values) {
    const wrap = document.getElementById('weekly-note-items-edit');
    if (!wrap) return;
    wrap.innerHTML = '';
    for (let i = 0; i < currentWeeklyNoteItemCount; i++) {
        const row = document.createElement('div');
        row.className = 'weekly-note-item-edit-row';
        const box = document.createElement('span');
        box.className = 'weekly-note-item-edit-box';
        box.setAttribute('aria-hidden', 'true');
        const input = document.createElement('input');
        input.type = 'text';
        input.maxLength = 28;
        input.value = values[i] || '';
        input.placeholder = t('weekly_note_item_placeholder').replace('{n}', i + 1);
        row.appendChild(box);
        row.appendChild(input);
        wrap.appendChild(row);
    }
    const textarea = document.getElementById('weekly-note-textarea');
    if (textarea) textarea.placeholder = t(currentWeeklyNoteItemCount ? 'weekly_note_free_placeholder' : 'weekly_note_placeholder');
}
function renderWeeklyNoteItemCountChips() {
    const wrap = document.getElementById('weekly-note-item-count-chips');
    if (!wrap) return;
    wrap.innerHTML = '';
    [0, 1, 2, 3].forEach(count => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'weekly-note-count-chip' + (currentWeeklyNoteItemCount === count ? ' selected' : '');
        chip.textContent = count === 0 ? t('weekly_note_items_none') : String(count);
        chip.onclick = () => selectWeeklyNoteItemCount(count);
        wrap.appendChild(chip);
    });
}
async function selectWeeklyNoteItemCount(count) {
    const values = Array.from(document.querySelectorAll('#weekly-note-items-edit input')).map(input => input.value);
    currentWeeklyNoteItemCount = count;
    cacheWeeklyNoteItems();
    renderWeeklyNoteItemCountChips();
    renderWeeklyNoteItemsEditor(values.length ? values : currentWeeklyNoteItems.map(item => item.text || ''));
    renderWeeklyNoteDisplay();
    if (supabaseClient && currentUserId) {
        await supabaseClient.from('user_premium').upsert(
            { user_id: currentUserId, username: currentUsername, weekly_note_item_count: count },
            { onConflict: 'user_id' },
        );
    }
}
async function saveWeeklyNoteItemsToServer() {
    cacheWeeklyNoteItems();
    if (!supabaseClient || !currentUserId) return null;
    const { error } = await supabaseClient.from('user_premium').upsert(
        { user_id: currentUserId, username: currentUsername, weekly_note_items: currentWeeklyNoteItems, weekly_note_item_count: currentWeeklyNoteItemCount },
        { onConflict: 'user_id' },
    );
    // ✓ בפתק נשמר גם בעותק של השבוע (השבועות הקודמים, ר' snapshotWeeklyNote ב-home.js)
    if (!error && typeof snapshotWeeklyNote === 'function') snapshotWeeklyNote();
    return error;
}
// ✓ ישר מהפתק במסך הבית
async function toggleWeeklyNoteItem(index) {
    const item = currentWeeklyNoteItems[index];
    if (!item) return;
    item.done = !item.done;
    renderWeeklyNoteDisplay();
    await saveWeeklyNoteItemsToServer();
}
async function saveWeeklyNote() {
    const textarea = document.getElementById('weekly-note-textarea');
    if (!textarea) return;
    currentWeeklyNoteText = textarea.value.trim();
    try { localStorage.setItem(WEEKLY_NOTE_CACHE_KEY, currentWeeklyNoteText); } catch {}
    // שורה שהטקסט שלה לא השתנה שומרת את הסימון שלה; שורה ששונתה מתחילה לא מסומנת
    const inputs = Array.from(document.querySelectorAll('#weekly-note-items-edit input'));
    if (inputs.length || currentWeeklyNoteItemCount === 0) {
        const previous = currentWeeklyNoteItems;
        const edited = inputs.map((input, i) => {
            const text = input.value.trim();
            const old = previous[i];
            return { text, done: !!(old && old.done && old.text === text && text) };
        });
        // שורות מעבר לכמות שנבחרה נשמרות (אם יחזרו לכמות גדולה יותר, הן יופיעו שוב)
        currentWeeklyNoteItems = edited.concat(previous.slice(edited.length));
    }
    renderWeeklyNoteDisplay();
    closeModal('modal-weekly-note');
    if (!supabaseClient || !currentUserId) { cacheWeeklyNoteItems(); return; }
    cacheWeeklyNoteItems();
    const { error } = await supabaseClient.from('user_premium').upsert(
        { user_id: currentUserId, username: currentUsername, weekly_note_text: currentWeeklyNoteText, weekly_note_items: currentWeeklyNoteItems, weekly_note_item_count: currentWeeklyNoteItemCount },
        { onConflict: 'user_id' },
    );
    if (error) showAppToast(t('error_adding_item') + error.message, 'error');
    // עותק של השבוע הזה, ל"השבועות שעברו" (פתק שנמחק לא מוחק אותו - ר' home.js)
    else if (typeof snapshotWeeklyNote === 'function') snapshotWeeklyNote();
}
function clearWeeklyNote() {
    const textarea = document.getElementById('weekly-note-textarea');
    if (textarea) textarea.value = '';
    document.querySelectorAll('#weekly-note-items-edit input').forEach(input => { input.value = ''; });
    saveWeeklyNote();
}

async function loadDailyNutrition(date) {
    if (!supabaseClient) return;
    const calorieGoalInput = document.getElementById('calorie-daily-goal-input');
    if (calorieGoalInput) calorieGoalInput.value = getCalorieDailyGoal();
    const proteinGoalInput = document.getElementById('protein-daily-goal-input');
    if (proteinGoalInput) proteinGoalInput.value = getProteinDailyGoal();
    document.querySelectorAll('.meal-row').forEach(row => {
        row.querySelector('.food-input').value = '';
        row.querySelector('.calories-input').value = '';
        row.querySelector('.protein-input').value = '';
        // מאפסים גם את סימון ה"נגעו בשורה" הישן - הוא שייך לתאריך/טעינה
        // הקודמים, לא לתאריך שנטען עכשיו (ר' ה-listener ב-DOMContentLoaded
        // וה-guard ב-saveNutrition)
        delete row.dataset.touched;
    });
    document.getElementById('calories-today').innerText = '0';
    const resetProteinTodayEl = document.getElementById('protein-today');
    if (resetProteinTodayEl) resetProteinTodayEl.innerText = '0';
    const { data } = await supabaseClient.from('calorie_tracker').select('*').eq('user_id', currentUserId).eq('date', date);
    if (!data) return;
    let total = 0, proteinTotal = 0;
    extraCaloriesToday = 0; extraProteinToday = 0;
    data.forEach(item => {
        const row = document.querySelector(`[data-meal="${item.meal_type}"]`);
        if (row) {
            row.querySelector('.food-input').value = item.food_description;
            row.querySelector('.calories-input').value = item.calories;
            row.querySelector('.protein-input').value = item.protein_grams || '';
        } else {
            // רישום בלי שורה במסך (שתייה של New Me, meal_type=nm_drink_N) - לא מוצג
            // בטופס אבל חייב להיספר, כדי שההצצה להיום ו-New Me יראו את אותו סכום
            extraCaloriesToday += Number(item.calories) || 0;
            extraProteinToday += Number(item.protein_grams) || 0;
        }
        total += Number(item.calories) || 0;
        proteinTotal += Number(item.protein_grams) || 0;
    });
    document.getElementById('calories-today').innerText = total;
    const proteinTodayEl = document.getElementById('protein-today');
    if (proteinTodayEl) proteinTodayEl.innerText = Math.round(proteinTotal * 10) / 10;
    todayCaloriesTotal = total;
    todayProteinTotal = proteinTotal;
    updateNutritionGoalProgress();
    updateHomeCalorieBadge();
    // 🏃 אימונים באותו יום מגדילים את התקציב
    refreshTrackerBurn(date);
}

// --- זיהוי ארוחה מתמונה (פרימיום בלבד): AI אמיתי בעל יכולת ראייה, דרך אותו
// דפוס פרוקסי בצד שרת כמו סריקת מתכונים - מזהה פריטי מזון וקלוריות ומכניס
// אותם ישירות לשורות הריקות הבאות במעקב הארוחות היומי, בלי הקלדה ידנית ---
async function saveNutrition() {
    const date = document.getElementById('selected-date').value;
    const mealRows = document.querySelectorAll('.meal-row');
    for (let row of mealRows) {
        const type = row.getAttribute('data-meal');
        const food = row.querySelector('.food-input').value;
        const cals = parseInt(row.querySelector('.calories-input').value) || 0;
        const protein = parseFloat(row.querySelector('.protein-input').value) || null;
        const { data: existing } = await supabaseClient.from('calorie_tracker').select('id').eq('user_id', currentUserId).eq('date', date).eq('meal_type', type).maybeSingle();
        // הגנה קריטית: אם השורה נראית ריקה בדף אבל *לא נגעו בה בכלל* בסשן
        // הזה (data-touched, ר' ה-listener ב-DOMContentLoaded), אין לדרוס
        // איתה נתון קיים במסד - זה כמעט תמיד סימן שהשורה פשוט לא נטענה
        // (למשל נוספה דרך ההוספה המהירה בזמן שהמסך הזה לא היה פתוח), לא
        // שהמשתמשת התכוונה למחוק אותה. דיווח אמיתי: נתונים שנוספו קודם
        // באותו יום נעלמו אחרי לחיצה על "שמור" בגלל בדיוק זה
        const isEmpty = !food.trim() && !cals;
        if (existing) {
            if (isEmpty) {
                // אם באמת נגעו בשורה (לא סתם נראית ריקה כי לא נטענה) וריקנו
                // אותה בכוונה - מוחקים את הרשומה לגמרי, לא משאירים "גדם" עם
                // 0 קלוריות. דיווח אמיתי: דוח ה-PDF הראה ימים עם "0" מוזר -
                // אלה היו בדיוק שורות-גדם כאלה שנשמרו ריקות במקום להימחק
                if (row.dataset.touched === 'true') await supabaseClient.from('calorie_tracker').delete().eq('id', existing.id);
                continue;
            }
            await supabaseClient.from('calorie_tracker').update({ food_description: food, calories: cals, protein_grams: protein }).eq('id', existing.id);
        } else if (!isEmpty) {
            await supabaseClient.from('calorie_tracker').insert({ username: currentUsername, user_id: currentUserId, date: date, meal_type: type, food_description: food, calories: cals, protein_grams: protein });
        }
    }
    await loadDailyNutrition(date);
    loadStats();
    loadCalorieMonthlyCalendar();
    showAppToast(t('nutrition_save_success'));
}

async function copyFromYesterday() {
    if (!supabaseClient) return;
    const currentDate = document.getElementById('selected-date').value;
    if (!currentDate) return;
    const prevDateObj = new Date(`${currentDate}T00:00:00`);
    prevDateObj.setDate(prevDateObj.getDate() - 1);
    const prevDate = getLocalDateString(prevDateObj);
    const { data } = await supabaseClient.from('calorie_tracker').select('*').eq('user_id', currentUserId).eq('date', prevDate);
    if (!data || data.length === 0) { showAppToast(t('nutrition_copy_not_found'), 'error'); return; }
    data.forEach(item => {
        const row = document.querySelector(`[data-meal="${item.meal_type}"]`);
        if (row) {
            row.querySelector('.food-input').value = item.food_description;
            row.querySelector('.calories-input').value = item.calories;
            row.querySelector('.protein-input').value = item.protein_grams || '';
        }
    });
    updateLiveCaloriesToday();
    showAppToast(t('nutrition_copy_success'));
}
async function loadStats() {
    if (!supabaseClient || !currentUserId) return;
    const { data } = await supabaseClient.from('calorie_tracker').select('date, calories, protein_grams').eq('user_id', currentUserId);
    if (!data) return;

    const now = new Date();
    const todayStr = getLocalDateString(now);
    const sunday = new Date(now); sunday.setDate(now.getDate() - now.getDay());
    const weekStartStr = getLocalDateString(sunday);
    const saturday = new Date(sunday); saturday.setDate(sunday.getDate() + 6);
    const weekEndStr = getLocalDateString(saturday);
    const monthPrefix = todayStr.slice(0, 7);

    // ממוצע-יומי לצד הסה"כ - לפי בקשה מפורשת ("יותר טוב לדעת אם אפשר לרדת
    // או לעלות"). מחושב רק על הימים שבאמת נרשם בהם משהו (לא חלקי 7/חלקי כל
    // ימי החודש) - יום שלא נרשם בו כלום פשוט לא נכנס למכנה, אותה עקרון
    // בדיוק כמו הסה"כ עצמו
    let weekly = 0, monthly = 0, weeklyProtein = 0, monthlyProtein = 0;
    const weekDates = new Set(), monthDates = new Set();
    data.forEach(item => {
        const cals = Number(item.calories) || 0;
        const protein = Number(item.protein_grams) || 0;
        if (item.date >= weekStartStr && item.date <= weekEndStr) { weekly += cals; weeklyProtein += protein; weekDates.add(item.date); }
        if (item.date && item.date.startsWith(monthPrefix)) { monthly += cals; monthlyProtein += protein; monthDates.add(item.date); }
    });
    document.getElementById('calories-weekly').innerText = weekly;
    document.getElementById('calories-monthly').innerText = monthly;
    const weeklyAvgEl = document.getElementById('calories-weekly-avg');
    if (weeklyAvgEl) weeklyAvgEl.innerText = weekDates.size > 0 ? t('calorie_stat_avg_label').replace('{amount}', Math.round(weekly / weekDates.size)) : '';
    const monthlyAvgEl = document.getElementById('calories-monthly-avg');
    if (monthlyAvgEl) monthlyAvgEl.innerText = monthDates.size > 0 ? t('calorie_stat_avg_label').replace('{amount}', Math.round(monthly / monthDates.size)) : '';

    const proteinWeeklyEl = document.getElementById('protein-weekly');
    if (proteinWeeklyEl) proteinWeeklyEl.innerText = Math.round(weeklyProtein * 10) / 10;
    const proteinMonthlyEl = document.getElementById('protein-monthly');
    if (proteinMonthlyEl) proteinMonthlyEl.innerText = Math.round(monthlyProtein * 10) / 10;
    const proteinWeeklyAvgEl = document.getElementById('protein-weekly-avg');
    if (proteinWeeklyAvgEl) proteinWeeklyAvgEl.innerText = weekDates.size > 0 ? t('protein_stat_avg_label').replace('{amount}', Math.round(weeklyProtein / weekDates.size)) : '';
    const proteinMonthlyAvgEl = document.getElementById('protein-monthly-avg');
    if (proteinMonthlyAvgEl) proteinMonthlyAvgEl.innerText = monthDates.size > 0 ? t('protein_stat_avg_label').replace('{amount}', Math.round(monthlyProtein / monthDates.size)) : '';
}
// מחיקה רכה (is_deleted=true) בשני הסוגים (פתקים ורשימת קניות) כדי שאפשר
// יהיה לשחזר מהארכיון, לפי בקשה מפורשת
// השורה מתעמעמת מיד ולא מגיבה ללחיצות עד שהרשימה מתרעננת: ככה רואים שהמחיקה נקלטה, לחיצה
// נוספת לא שולחת מחיקה שנייה, והשורה לא זזה מתחת לאצבע באמצע לחיצה כפולה
const deletedCenterItemIds = new Set();
async function deleteCenterItem(id, type) {
    if (deletedCenterItemIds.has(id)) return;
    deletedCenterItemIds.add(id);
    const row = document.querySelector(`#${type}-list li[data-item-id="${id}"]`);
    if (row) row.classList.add('is-removing');
    const { error } = await supabaseClient.from('my_center_tasks').update({ is_deleted: true, deleted_at: new Date().toISOString() }).eq('id', id);
    if (error) {
        deletedCenterItemIds.delete(id);
        showAppToast(t('error_adding_item') + error.message, 'error');
    }
    loadCenterItems(type);
}

// --- ארכיון פריטים מחוקים: קישור מעומעם ומתקפל בתחתית כל רשימה (פתקים
// ורשימת קניות, כל אחת עם הארכיון שלה) - לא קוביה שתמיד מוצגת, "אלפי
// פתקים" בארכיון לא אמורים להכביד על הרשימה הרגילה. שחזור מחזיר is_deleted
// ל-false, מחיקה-לצמיתות היא delete() אמיתי. כל האלמנטים/הפונקציות
// מזוהים לפי type ('weekly'/'general') כדי שלשתי הרשימות יהיה ארכיון נפרד ---
// currentArchiveType - איזה ארכיון (פתקים/רשימת קניות) פתוח כרגע במודל
// המשותף (ר' modal-notes-archive) - נקרא גם ישירות מתוך onclick ב-HTML
// (כפתור "רוקן ארכיון" בתוך המודל), אז זו לא קבועה מקומית לפונקציה
let currentArchiveType = null;

async function refreshNotesArchiveCount(type) {
    if (!supabaseClient || !currentUserId) return;
    const countEl = document.getElementById(`archive-count-${type}`);
    if (!countEl) return;
    const { count } = await supabaseClient.from('my_center_tasks').select('id', { count: 'exact', head: true }).eq('user_id', currentUserId).eq('task_type', type).eq('is_deleted', true);
    countEl.textContent = count || '';
    document.getElementById(`archive-toggle-${type}`).classList.toggle('hidden', !count);
}

// לא מתקפל בתוך הרשימה (בלי חץ, בלי אנימציית-הרחבה) - נכנס כמודל נפרד
// לגמרי, לפי בקשה מפורשת ("כמו לעולם חדש כזה")
async function openNotesArchiveModal(type) {
    currentArchiveType = type;
    await loadNotesArchiveList(type);
    openModal('modal-notes-archive');
}

async function loadNotesArchiveList(type) {
    if (!supabaseClient || !currentUserId) return;
    const listEl = document.getElementById('notes-archive-modal-list');
    const { data } = await supabaseClient.from('my_center_tasks').select('*').eq('user_id', currentUserId).eq('task_type', type).eq('is_deleted', true).order('deleted_at', { ascending: false });
    listEl.innerHTML = '';
    if (!data || !data.length) {
        listEl.innerHTML = `<p class="today-tasks-empty">${t('notes_archive_empty_hint')}</p>`;
        return;
    }
    data.forEach(item => {
        const li = document.createElement('li');
        li.className = 'archive-item';
        const textSpan = document.createElement('span');
        textSpan.className = 'center-list-item-text';
        textSpan.textContent = item.content;
        const restoreBtn = document.createElement('button');
        restoreBtn.type = 'button';
        restoreBtn.className = 'btn-edit-item';
        restoreBtn.title = t('notes_archive_restore_btn');
        restoreBtn.textContent = '↩️';
        restoreBtn.onclick = () => restoreArchivedNote(item.id, type);
        const deleteBtn = document.createElement('button');
        deleteBtn.type = 'button';
        deleteBtn.className = 'btn-delete-item';
        deleteBtn.textContent = '❌';
        deleteBtn.onclick = () => permanentlyDeleteArchivedNote(item.id, type);
        li.appendChild(textSpan);
        li.appendChild(restoreBtn);
        li.appendChild(deleteBtn);
        listEl.appendChild(li);
    });
}

async function restoreArchivedNote(id, type) {
    await supabaseClient.from('my_center_tasks').update({ is_deleted: false, deleted_at: null }).eq('id', id);
    deletedCenterItemIds.delete(id);
    await loadNotesArchiveList(type);
    await refreshNotesArchiveCount(type);
    await loadCenterItems(type);
    showAppToast(t('notes_archive_restored'));
}

async function permanentlyDeleteArchivedNote(id, type) {
    await supabaseClient.from('my_center_tasks').delete().eq('id', id);
    await loadNotesArchiveList(type);
    await refreshNotesArchiveCount(type);
}

async function emptyNotesArchive(type) {
    if (!confirm(t('notes_archive_empty_confirm'))) return;
    await supabaseClient.from('my_center_tasks').delete().eq('user_id', currentUserId).eq('task_type', type).eq('is_deleted', true);
    await loadNotesArchiveList(type);
    await refreshNotesArchiveCount(type);
}

// --- וי יומי על פריטי "השגרה שלי": כל שורת-שעה מלאה בכל טאב מקבלת ריבוע וי
// קטן ל"עשיתי היום" - וזה המעקב של המטרות וההרגלים, בלי סקציה נפרדת ובלי
// הוספה נוספת, לפי בקשה מפורשת ("בבוקר ערב וכו' בכל שעה פשוט וי ליד... וככה
// לא צריך להוסיף וזה יהיה המטרות וההרגלים"). הסימונים ב-routine_item_checkins
// (פריט+תאריך). הפעלה/כיבוי כללי (לא פר-טאב) מתוך פאנל השעות (⚙️), ברירת
// מחדל דלוק - אותו דפוס בדיוק כמו isDailyBoardPeekTabOn
function isRoutineGoalsOn() { return localStorage.getItem('weekwise_routine_goals_enabled') !== 'false'; }
async function loadRoutineGoalsSetting() {
    if (!supabaseClient || !currentUserId) return;
    const { data } = await supabaseClient.from('user_premium').select('routine_goals_enabled').eq('user_id', currentUserId).maybeSingle();
    if (!data || data.routine_goals_enabled === null || data.routine_goals_enabled === undefined) return;
    localStorage.setItem('weekwise_routine_goals_enabled', String(data.routine_goals_enabled));
    applyRoutineGoalsSetting();
}
async function toggleRoutineGoals() {
    const enabled = document.getElementById('routine-goals-toggle').checked;
    localStorage.setItem('weekwise_routine_goals_enabled', String(enabled));
    applyRoutineGoalsSetting();
    if (supabaseClient && currentUserId) {
        await supabaseClient.from('user_premium').upsert(
            { user_id: currentUserId, username: currentUsername, routine_goals_enabled: enabled },
            { onConflict: 'user_id' },
        );
    }
}
function applyRoutineGoalsSetting() {
    const overviewBtn = document.getElementById('daily-board-overview-btn');
    const toggle = document.getElementById('routine-goals-toggle');
    const enabled = isRoutineGoalsOn();
    if (overviewBtn) overviewBtn.classList.toggle('hidden', !enabled);
    if (toggle) toggle.checked = enabled;
    const modal = document.getElementById('modal-daily-board');
    if (modal && modal.classList.contains('open')) {
        renderDailyBoard();
        refreshRoutineNudge();
    }
}

// עדכון אופטימי (הוי מתחלף מיד, לפני שהשרת עונה) - ואם הכתיבה נכשלה, מחזירים
// את המצב הקודם כדי שהמסך לא "ישקר" על מה שבאמת נשמר
async function toggleRoutineItemCheckin(itemId, btn) {
    const todayStr = getLocalDateString();
    const checked = !btn.classList.contains('checked');
    btn.classList.toggle('checked', checked);
    btn.textContent = checked ? '✓' : '';
    const { error } = checked
        ? await supabaseClient.from('routine_item_checkins').insert({ item_id: itemId, user_id: currentUserId, checkin_date: todayStr })
        : await supabaseClient.from('routine_item_checkins').delete().eq('item_id', itemId).eq('checkin_date', todayStr);
    if (error) {
        console.error('routine checkin failed', error);
        btn.classList.toggle('checked', !checked);
        btn.textContent = !checked ? '✓' : '';
        showAppToast(t('error_not_connected'), 'error');
        return;
    }
    const milestoneId = routineItemGoalLinks.get(itemId);
    if (milestoneId) syncGoalFromRoutineCheck(milestoneId, todayStr, checked);
    const smallStepGoalId = routineItemSmallStepLinks.get(itemId);
    if (smallStepGoalId) syncGoalSmallStepFromRoutine(smallStepGoalId, todayStr, checked);
    // ✓ על הפריט שהכרטיס 🌱 שואל עליו - הכרטיס נעלם (סימן שזה כן קורה)
    if (checked && routineNudge && routineNudge.itemIds.includes(itemId)) {
        routineNudge = null;
        renderRoutineNudge();
    }
    // ✓ כאן = ✓ גם ב"היום שלי" (ציר הזמן במסך הבית) ובפינה שגדלה
    loadTodayTasks();
}

// --- לוח "הרגלים" חודשי של הטאב הפעיל *בלבד* (לא כל הטאבים ביחד), לפי בקשה
// מפורשת ("כמה טאבים כל טאב עם מטרות שונות"). לוח חודשי רגיל: רק ימים שסומן
// בהם וי מסומנים, ולחיצה על יום מציגה מה סומן בו ("רק מה שסומן וי יראו אותו").
// נפתח/נסגר ישירות (לא openModal/closeModal) כדי ש-#modal-daily-board
// יישאר פתוח מתחתיו ---
let viewedRoutineGoalsOverviewMonthKey = null;

function openRoutineGoalsOverviewModal() {
    if (!activeDailyBoardTabId) return;
    viewedRoutineGoalsOverviewMonthKey = currentMonthKey();
    document.getElementById('modal-routine-goals-overview').classList.add('open');
    renderRoutineGoalsOverview();
}
function closeRoutineGoalsOverviewModal() {
    document.getElementById('modal-routine-goals-overview').classList.remove('open');
}

async function navigateRoutineGoalsOverview(delta) {
    if (!viewedRoutineGoalsOverviewMonthKey) return;
    viewedRoutineGoalsOverviewMonthKey = shiftMonthKey(viewedRoutineGoalsOverviewMonthKey, delta);
    await renderRoutineGoalsOverview();
}

async function renderRoutineGoalsOverview() {
    if (!viewedRoutineGoalsOverviewMonthKey || !supabaseClient || !currentUserId || !activeDailyBoardTabId) return;
    const monthKey = viewedRoutineGoalsOverviewMonthKey;
    document.getElementById('routine-goals-overview-month-label').textContent = formatMonthLabel(monthKey);
    const [y, m] = monthKey.split('-').map(Number);
    const daysInMonth = new Date(y, m, 0).getDate();
    const firstStr = `${monthKey}-01`;
    const lastStr = `${monthKey}-${String(daysInMonth).padStart(2, '0')}`;
    const grid = document.getElementById('routine-goals-overview-grid');
    const detail = document.getElementById('routine-goals-overview-day-detail');
    const emptyHint = document.getElementById('routine-goals-overview-empty');
    const { data: items } = await supabaseClient.from('routine_items').select('id, title, time').eq('tab_id', activeDailyBoardTabId).eq('user_id', currentUserId).eq('kind', 'scheduled').order('time', { ascending: true });
    const itemById = new Map((items || []).map(it => [it.id, it]));
    let checkins = [];
    if (itemById.size) {
        const { data } = await supabaseClient.from('routine_item_checkins').select('item_id, checkin_date').in('item_id', [...itemById.keys()]).gte('checkin_date', firstStr).lte('checkin_date', lastStr);
        checkins = data || [];
    }
    // יום -> הפריטים שסומנו בו, ממוינים לפי שעה (items כבר ממוינים לפי time)
    const checkedByDate = {};
    checkins.forEach(c => {
        if (!itemById.has(c.item_id)) return;
        (checkedByDate[c.checkin_date] = checkedByDate[c.checkin_date] || new Set()).add(c.item_id);
    });
    emptyHint.classList.toggle('hidden', Object.keys(checkedByDate).length > 0);
    detail.innerHTML = '';

    const todayStr = getLocalDateString();
    const startWeekday = new Date(y, m - 1, 1).getDay();
    grid.innerHTML = '';
    for (let i = 0; i < startWeekday; i++) {
        const empty = document.createElement('div');
        empty.className = 'monthly-calendar-cell empty';
        grid.appendChild(empty);
    }
    const showDay = (dateStr, cell) => {
        grid.querySelectorAll('.monthly-calendar-cell.selected').forEach(el => el.classList.remove('selected'));
        cell.classList.add('selected');
        const [yy, mm, dd] = dateStr.split('-').map(Number);
        const dayLabel = new Date(yy, mm - 1, dd).toLocaleDateString(currentLang, { weekday: 'long', day: 'numeric', month: 'long' });
        detail.innerHTML = `<div class="monthly-calendar-day-title">${escapeHtmlForReport(dayLabel)}</div>`;
        (items || []).filter(it => checkedByDate[dateStr].has(it.id)).forEach(it => {
            const row = document.createElement('div');
            row.className = 'routine-overview-done-row';
            row.textContent = `✓ ${(it.time || '').slice(0, 5)} ${it.title}`;
            detail.appendChild(row);
        });
    };
    let todayCell = null;
    for (let day = 1; day <= daysInMonth; day++) {
        const dateStr = `${monthKey}-${String(day).padStart(2, '0')}`;
        const count = checkedByDate[dateStr] ? checkedByDate[dateStr].size : 0;
        const cell = document.createElement('div');
        cell.className = 'monthly-calendar-cell' + (dateStr === todayStr ? ' today' : '') + (count ? ' routine-overview-has-checks' : ' routine-overview-no-checks');
        cell.innerHTML = `<span class="monthly-calendar-day-num">${day}</span>${count ? `<span class="routine-overview-count">✓${count}</span>` : ''}`;
        if (count) {
            cell.onclick = () => showDay(dateStr, cell);
            if (dateStr === todayStr) todayCell = cell;
        }
        grid.appendChild(cell);
    }
    if (todayCell) showDay(todayStr, todayCell);
}

// --- "לוח היום" (🧭): טאבים מותאמים-אישית (routine_tabs, ברירת מחדל 2 -
// "שגרה יומית"/"לימודים", ניתנות לשינוי שם/מחיקה/הוספה) שכל אחד מציג שורות-שעה
// קבועות (getDailyBoardCustomHours - ברירת מחדל DAILY_BOARD_DEFAULT_HOURS,
// אבל ניתנות להוספה/הסרה חופשית מהגדרות > התאמה ויומן, ר' toggleDailyBoardHour
// למטה - לפי בקשה מפורשת "לסדר את השעות, למחוק ולהוסיף"), מקובצות לפי בלוק
// (בוקר/צהריים/אחה"צ/ערב). כל שורה קיימת תמיד (גם ריקה, לחיצה עליה פותחת
// הוספה) - זו שגרה שחוזרת על עצמה בדיוק אותו הדבר כל יום, בלי בחירת ימים
// (הוסרה לפי בקשה מפורשת: "כל הקטע של הלו״ז היומי שזה שגרה שחוזרת על
// עצמה"). עוגן ויזואלי נפרד לגמרי מהלו"ז הרגיל (weekly_schedule/
// calendar_events) - לא נשלף משם, לפי בקשה מפורשת ---
let dailyBoardTabs = [];
// פריט בשגרה שמקושר לצעד/משימה יומית ביעד (routine_items.vision_milestone_id) - ✓ כאן מסמן גם שם
let routineItemGoalLinks = new Map();
// פריט שהוא הצעד הקטן היומי של יעד (routine_items.vision_goal_id) - ✓ כאן = "✓ עשיתי היום" ביעד
let routineItemSmallStepLinks = new Map();
let activeDailyBoardTabId = null;
let editingRoutineItemId = null;
let pendingRoutineItemTime = null;

// טווח-השעות הטבעי שכל בלוק מציע לבחירה בהגדרות (לא כל 24 השעות בכל בלוק -
// זה היה הופך לרשימה ארוכה ובלתי-שימושית) - השעות שמחוץ לטווח הזה (00:00-
// 04:00) פשוט לא רלוונטיות ל"סדר יום" ולכן לא מוצעות כלל
// "אחר הצהריים" מסתיימת ב-16:00 (רק השעה הזו), 17 ומעלה עוברות ל"ערב" - לפי
// בקשה מפורשת ("19 זה אחר הצהריים ולא ערב? תעשה שאחר הצהריים יהיה עד השעה
// 16:00"), אחרי שדווח שהשעה 19:00 הופיעה תחת "אחר הצהריים" בטעות
const DAILY_BOARD_BUCKET_RANGES = {
    morning: [5, 6, 7, 8, 9, 10, 11],
    noon: [12, 13, 14, 15],
    afternoon: [16],
    evening: [17, 18, 19, 20, 21, 22, 23],
};
const DAILY_BOARD_DEFAULT_HOURS = {
    morning: [7, 8, 10, 11],
    noon: [12, 14, 15],
    afternoon: [16],
    evening: [17, 19, 20, 21, 22],
};

// לכל טאב יש שעות בלוקים משלו (לא גלובלי לכל הטאבים) - לפי בקשה מפורשת
// ("כל פעם שמוסיפים טאב יהיה אפשר לשחק עם השעות ולשנות לכל טאב שונה").
// נשמר בעמודת routine_tabs.custom_hours (Supabase, לא localStorage) - לפי
// בקשה מפורשת ("סדר היום לא מסתנכרן במובייל ובמחשב") - לפני זה זה היה
// localStorage בלבד, אז התאמת-שעות שנעשתה במחשב לא הייתה מגיעה לנייד
// (ולהפך) בכלל, רק סדר-הטאבים/המשימות עצמן (routine_tabs/routine_items)
// היו מסונכרנות. dailyBoardTabs כבר נטען מ-Supabase עם select('*') ב-
// loadRoutineTabs, אז custom_hours מגיע יחד עם שאר שדות הטאב אוטומטית.
// קריטי להחזיר עותק טרי בכל קריאה (לא רפרנס משותף ל-DAILY_BOARD_DEFAULT_HOURS
// הקבוע) - toggleDailyBoardHour עושה hours[bucket] = list על מה שמוחזר כאן
// ישירות; אם היה מוחזר הרפרנס המשותף עצמו, מוטציה כזו הייתה משנה את הקבוע
// הגלובלי לצמיתות עבור *כל* הטאבים שעדיין אין להם התאמה אישית משלהם - בדיוק
// הבאג שדווח בעבר ("הוספתי שעה בלימודים וזה התווסף גם לשגרה היומית")
function getDailyBoardCustomHours(tabId) {
    const tab = tabId ? dailyBoardTabs.find(t => t.id === tabId) : null;
    const saved = tab && tab.custom_hours && typeof tab.custom_hours === 'object' ? tab.custom_hours : null;
    if (!saved) return { morning: [...DAILY_BOARD_DEFAULT_HOURS.morning], noon: [...DAILY_BOARD_DEFAULT_HOURS.noon], afternoon: [...DAILY_BOARD_DEFAULT_HOURS.afternoon], evening: [...DAILY_BOARD_DEFAULT_HOURS.evening] };
    return {
        morning: Array.isArray(saved.morning) ? saved.morning : [...DAILY_BOARD_DEFAULT_HOURS.morning],
        noon: Array.isArray(saved.noon) ? saved.noon : [...DAILY_BOARD_DEFAULT_HOURS.noon],
        afternoon: Array.isArray(saved.afternoon) ? saved.afternoon : [...DAILY_BOARD_DEFAULT_HOURS.afternoon],
        evening: Array.isArray(saved.evening) ? saved.evening : [...DAILY_BOARD_DEFAULT_HOURS.evening],
    };
}

async function toggleDailyBoardHour(bucket, hour) {
    if (!activeDailyBoardTabId) return;
    const hours = getDailyBoardCustomHours(activeDailyBoardTabId);
    const previousHours = { morning: [...hours.morning], noon: [...hours.noon], afternoon: [...hours.afternoon], evening: [...hours.evening] };
    const list = (hours[bucket] || []).slice();
    const idx = list.indexOf(hour);
    if (idx === -1) list.push(hour); else list.splice(idx, 1);
    list.sort((a, b) => a - b);
    hours[bucket] = list;
    // עדכון-מקומי אופטימי (רינדור מיידי, בלי לחכות לרשת) + כתיבה ל-Supabase -
    // אותה תחושת-מיידיות שהייתה עם localStorage, אבל עכשיו גם מסונכרן. אם
    // הכתיבה נכשלת בפועל (למשל ניתוק רשת) מחזירים את המצב המקומי אחורה
    // ומודיעים - בלי זה כישלון היה נשאר שקט לגמרי ומתאפס בטעינה הבאה, בדיוק
    // התסמין שדווח ("כל יום מחדש אני מוחקת... וזה חוזר")
    const tab = dailyBoardTabs.find(t => t.id === activeDailyBoardTabId);
    if (tab) tab.custom_hours = hours;
    renderDailyBoardHourSettings();
    renderDailyBoard();
    if (!supabaseClient) return;
    const { error } = await supabaseClient.from('routine_tabs').update({ custom_hours: hours }).eq('id', activeDailyBoardTabId);
    if (error) {
        if (tab) tab.custom_hours = previousHours;
        renderDailyBoardHourSettings();
        renderDailyBoard();
        showAppToast(t('daily_board_hours_save_failed'), 'error');
    }
}

// פאנל השעות פתוח/סגור בתוך מודל "סדר היום" עצמו (לא בהגדרות הכלליות -
// שם לא היה ברור לאיזה טאב הן מתייחסות), ליד כפתור הוספת הטאב
function toggleDailyBoardHoursPanel() {
    const panel = document.getElementById('daily-board-hours-panel');
    if (!panel) return;
    const willShow = panel.classList.contains('hidden');
    panel.classList.toggle('hidden', !willShow);
    if (willShow) renderDailyBoardHourSettings();
}

function renderDailyBoardHourSettings() {
    const panel = document.getElementById('daily-board-hours-panel');
    if (!panel || panel.classList.contains('hidden')) return;
    renderRoutineTabDaysChips();
    const hours = getDailyBoardCustomHours(activeDailyBoardTabId);
    Object.keys(DAILY_BOARD_BUCKET_RANGES).forEach(bucket => {
        const wrap = document.getElementById(`board-hours-${bucket}`);
        if (!wrap) return;
        wrap.innerHTML = '';
        DAILY_BOARD_BUCKET_RANGES[bucket].forEach(hour => {
            const active = (hours[bucket] || []).includes(hour);
            const chip = document.createElement('button');
            chip.type = 'button';
            chip.className = 'board-hour-chip' + (active ? ' active' : '');
            chip.textContent = `${String(hour).padStart(2, '0')}:00`;
            chip.onclick = () => toggleDailyBoardHour(bucket, hour);
            wrap.appendChild(chip);
        });
    });
}

async function openDailyBoardModal() {
    if (!supabaseClient || !currentUserId) return;
    const hoursPanel = document.getElementById('daily-board-hours-panel');
    if (hoursPanel) hoursPanel.classList.add('hidden');
    routineNudge = null;
    renderRoutineNudge();
    openModal('modal-daily-board');
    dailyBoardOpenOnToday = true;
    await loadRoutineTabs();
    await refreshRoutineNudge();
}

// בפתיחה - ישר לטאב של היום (טאב שמשויך ליום הזה), לפי בקשה מפורשת ("לפתוח ישר את הטאב של היום")
let dailyBoardOpenOnToday = false;

async function loadRoutineTabs() {
    const { data } = await supabaseClient.from('routine_tabs').select('*').eq('user_id', currentUserId).order('sort_order', { ascending: true }).order('created_at', { ascending: true });
    dailyBoardTabs = data || [];
    if (!dailyBoardTabs.length) {
        const seeded = [
            { user_id: currentUserId, username: currentUsername, name: t('daily_board_default_tab_daily'), sort_order: 0 },
            { user_id: currentUserId, username: currentUsername, name: t('daily_board_default_tab_study'), sort_order: 1 },
        ];
        const { data: inserted } = await supabaseClient.from('routine_tabs').insert(seeded).select('*');
        dailyBoardTabs = inserted || [];
    }
    if (dailyBoardOpenOnToday) {
        dailyBoardOpenOnToday = false;
        const todayTab = findTodayRoutineTab();
        if (todayTab) activeDailyBoardTabId = todayTab.id;
    }
    if (!activeDailyBoardTabId || !dailyBoardTabs.some(tb => tb.id === activeDailyBoardTabId)) {
        activeDailyBoardTabId = dailyBoardTabs[0] ? dailyBoardTabs[0].id : null;
    }
    renderRoutineTabsBar();
    await renderDailyBoard();
}

function renderRoutineTabsBar() {
    const wrap = document.getElementById('daily-board-tabs-list');
    if (!wrap) return;
    wrap.innerHTML = '';
    const todayIdx = new Date().getDay();
    dailyBoardTabs.forEach(tab => {
        const btn = document.createElement('button');
        btn.type = 'button';
        // נקודה קטנה על הטאב של היום
        const isToday = routineTabWeekdays(tab).includes(todayIdx);
        btn.className = 'daily-board-tab-pill' + (tab.id === activeDailyBoardTabId ? ' active' : '') + (isToday ? ' today' : '');
        if (isToday) btn.title = t('routine_tab_today_title');
        btn.textContent = tab.name;
        btn.onclick = () => switchRoutineTab(tab.id);
        wrap.appendChild(btn);
    });
    const deleteBtn = document.getElementById('daily-board-delete-tab-btn');
    if (deleteBtn) deleteBtn.classList.toggle('hidden', dailyBoardTabs.length <= 1);
}

// לחיצה על טאב שכבר פעיל פותחת שינוי-שם (במקום כפתור "✏️ שינוי שם" נפרד
// שהוסר) - לפי בקשה מפורשת "שלוחצים על השגרה היומית תהיה אפשרות לשנות
// את השם". לחיצה על טאב לא-פעיל ממשיכה להחליף טאב כרגיל
async function switchRoutineTab(tabId) {
    if (tabId === activeDailyBoardTabId) {
        openRenameRoutineTabModal(tabId);
        return;
    }
    activeDailyBoardTabId = tabId;
    renderRoutineTabsBar();
    renderDailyBoardHourSettings();
    await renderDailyBoard();
}

// מודל מעוצב במקום prompt()/window.prompt הנייטיבי של הדפדפן (הראה "האתר
// ... אומר" מכוער ולא תואם את עיצוב האפליקציה) - לפי בקשה מפורשת. אותו
// מודל לשני המצבים (הוספה/שינוי שם), routineTabNameMode קובע מה saveRoutineTabName עושה
let routineTabNameMode = 'add';
function openAddRoutineTabPrompt() {
    routineTabNameMode = 'add';
    document.getElementById('routine-tab-name-modal-title').textContent = t('daily_board_add_tab_title');
    document.getElementById('routine-tab-name-input').value = '';
    openModalOverDailyBoard('modal-routine-tab-name');
}

function openRenameRoutineTabModal(tabId) {
    const tab = dailyBoardTabs.find(tb => tb.id === tabId);
    if (!tab) return;
    routineTabNameMode = 'rename';
    document.getElementById('routine-tab-name-modal-title').textContent = t('daily_board_rename_tab_btn');
    document.getElementById('routine-tab-name-input').value = tab.name;
    openModalOverDailyBoard('modal-routine-tab-name');
}

async function saveRoutineTabName() {
    const name = document.getElementById('routine-tab-name-input').value.trim();
    if (!name) return;
    closeModal('modal-routine-tab-name');
    if (routineTabNameMode === 'add') {
        await addRoutineTab(name);
    } else if (routineTabNameMode === 'duplicate') {
        await duplicateRoutineTab(name);
    } else {
        await renameRoutineTab(activeDailyBoardTabId, name);
    }
}

async function addRoutineTab(name) {
    const sortOrder = nextRoutineTabSortOrder();
    const { data } = await supabaseClient.from('routine_tabs').insert({ user_id: currentUserId, username: currentUsername, name, sort_order: sortOrder }).select('*').single();
    if (data) {
        dailyBoardTabs.push(data);
        activeDailyBoardTabId = data.id;
        renderRoutineTabsBar();
        renderDailyBoardHourSettings();
        await renderDailyBoard();
    }
}

async function renameRoutineTab(tabId, name) {
    await supabaseClient.from('routine_tabs').update({ name }).eq('id', tabId);
    const tab = dailyBoardTabs.find(tb => tb.id === tabId);
    if (tab) tab.name = name;
    renderRoutineTabsBar();
}

function nextRoutineTabSortOrder() {
    return dailyBoardTabs.reduce((max, tb) => Math.max(max, Number(tb.sort_order) || 0), -1) + 1;
}

// --- ימים לטאב (routine_tabs.weekdays, 0 = ראשון): ביום הזה "השגרה שלי" נפתחת ישר על הטאב,
// ושאלת "3 ימים בלי ✓" סופרת רק את הימים שבהם הפריט באמת קיים. טאב שלא נבחרו לו ימים אבל
// ששמו הוא שם של יום ("ראשון", "יום שני", "Monday") נחשב לטאב של אותו יום - כך טאבים
// שנוצרו ידנית לפי ימים עובדים מעצמם. מערך ריק = נבחר במפורש "בלי ימים" ---
function routineWeekdayName(d, style = 'long') {
    // 4 בינואר 2026 = יום ראשון
    let name = new Date(2026, 0, 4 + d).toLocaleDateString(currentLang, { weekday: style });
    if (currentLang === 'he') name = name.replace(/^יום\s+/, '');
    return name;
}

function weekdayFromRoutineTabName(name) {
    const clean = String(name || '').trim().toLowerCase().replace(/^יום\s+/, '');
    if (!clean) return null;
    for (let d = 0; d < 7; d++) {
        if (routineWeekdayName(d).toLowerCase() === clean) return d;
    }
    return null;
}

function routineTabWeekdays(tab) {
    if (!tab) return [];
    if (Array.isArray(tab.weekdays)) return tab.weekdays.map(Number);
    const d = weekdayFromRoutineTabName(tab.name);
    return d === null ? [] : [d];
}

function findTodayRoutineTab() {
    const todayIdx = new Date().getDay();
    return dailyBoardTabs.find(tb => routineTabWeekdays(tb).includes(todayIdx)) || null;
}

function routineSingleDayTabFor(d) {
    return dailyBoardTabs.find(tb => { const days = routineTabWeekdays(tb); return days.length === 1 && days[0] === d; }) || null;
}

function renderRoutineTabDaysChips() {
    const wrap = document.getElementById('board-tab-days');
    if (!wrap) return;
    const tab = dailyBoardTabs.find(tb => tb.id === activeDailyBoardTabId);
    const days = new Set(routineTabWeekdays(tab));
    wrap.innerHTML = '';
    for (let d = 0; d < 7; d++) {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'board-hour-chip' + (days.has(d) ? ' active' : '');
        chip.setAttribute('aria-pressed', days.has(d) ? 'true' : 'false');
        chip.textContent = routineWeekdayName(d, 'short');
        chip.onclick = () => toggleRoutineTabWeekday(d);
        wrap.appendChild(chip);
    }
}

async function toggleRoutineTabWeekday(d) {
    const tab = dailyBoardTabs.find(tb => tb.id === activeDailyBoardTabId);
    if (!tab) return;
    const previous = tab.weekdays;
    const days = new Set(routineTabWeekdays(tab));
    if (days.has(d)) days.delete(d); else days.add(d);
    tab.weekdays = [...days].sort((a, b) => a - b);
    renderRoutineTabDaysChips();
    renderRoutineTabsBar();
    if (!supabaseClient) return;
    const { error } = await supabaseClient.from('routine_tabs').update({ weekdays: tab.weekdays }).eq('id', tab.id);
    if (error) {
        tab.weekdays = previous;
        renderRoutineTabDaysChips();
        renderRoutineTabsBar();
        showAppToast(t('daily_board_hours_save_failed'), 'error');
        return;
    }
    refreshRoutineNudge();
}

// --- ➕ ב"השגרה שלי": טאב ריק / שכפול הטאב הנוכחי (שעות + פריטים) / תבניות מוכנות - רק
// בפרימיום, לפי בקשה מפורשת. תבניות ימים: טאב לכל יום (ריק או כהעתק של הטאב הנוכחי);
// שגרות מוכנות: טאב אחד עם שעות ופריטים (הטקסטים ב-i18n, שורה "HH:00 פריט" לכל שעה) ---
const ROUTINE_DAY_TEMPLATES = [
    { id: 'sun_thu', days: [0, 1, 2, 3, 4] },
    { id: 'mon_fri', days: [1, 2, 3, 4, 5] },
    { id: 'sun_fri', days: [0, 1, 2, 3, 4, 5] },
    { id: 'week', days: [0, 1, 2, 3, 4, 5, 6] },
];
const ROUTINE_READY_TEMPLATES = [
    { id: 'morning', icon: '🌅' },
    { id: 'evening', icon: '🌙' },
    { id: 'workday', icon: '💼' },
    { id: 'home_office', icon: '🏠' },
    { id: 'study', icon: '📚' },
    { id: 'workout', icon: '💪' },
    { id: 'eating', icon: '🥗' },
    { id: 'calm', icon: '🧘' },
    { id: 'kids', icon: '🧸' },
    { id: 'weekend', icon: '🌿' },
];
let routineDaysFillMode = 'copy';
// כמה פריטים יש בטאב הפעיל (מתעדכן ב-renderDailyBoard) - "העתק של הטאב" מוצע רק כשיש מה להעתיק
let dailyBoardActiveItemCount = 0;

function openRoutineAddChoice() {
    const src = dailyBoardTabs.find(tb => tb.id === activeDailyBoardTabId);
    const dupBtn = document.getElementById('routine-add-duplicate-btn');
    if (dupBtn) dupBtn.classList.toggle('hidden', !src);
    const dupLabel = document.getElementById('routine-add-duplicate-label');
    if (dupLabel && src) dupLabel.textContent = t('routine_add_duplicate').replace('{name}', src.name);
    routineDaysFillMode = src && dailyBoardActiveItemCount > 0 ? 'copy' : 'empty';
    renderRoutineTemplates();
    openModalOverDailyBoard('modal-routine-add-choice');
}

function routineAddEmptyTab() {
    closeModal('modal-routine-add-choice');
    openAddRoutineTabPrompt();
}

function setRoutineDaysFillMode(mode) {
    routineDaysFillMode = mode === 'copy' ? 'copy' : 'empty';
    renderRoutineTemplates();
}

function routineDayTemplateLabel(tpl) {
    if (tpl.days.length === 7) return t('routine_tpl_week');
    return `${routineWeekdayName(tpl.days[0], 'short')}–${routineWeekdayName(tpl.days[tpl.days.length - 1], 'short')}`;
}

function parseRoutineTemplateItems(text) {
    const seenHours = new Set();
    return String(text || '').split('\n').map(line => {
        const m = line.match(/^\s*(\d{1,2})(?:[:.]\d{2})?\s*[-–—]?\s*(.+?)\s*$/);
        if (!m) return null;
        const hour = Number(m[1]);
        if (!(hour >= 0 && hour <= 23) || seenHours.has(hour)) return null;
        seenHours.add(hour);
        return { hour, title: m[2] };
    }).filter(Boolean);
}

function routineBucketOfHour(hour) {
    return Object.keys(DAILY_BOARD_BUCKET_RANGES).find(b => DAILY_BOARD_BUCKET_RANGES[b].includes(hour)) || null;
}

function renderRoutineTemplates() {
    const locked = !isPremiumUser;
    const badge = document.getElementById('routine-templates-premium-badge');
    if (badge) badge.textContent = `${locked ? '🔒' : '⭐'} ${t('routine_premium_badge')}`;
    const src = dailyBoardTabs.find(tb => tb.id === activeDailyBoardTabId);
    const canCopy = !!src && dailyBoardActiveItemCount > 0;
    if (!canCopy) routineDaysFillMode = 'empty';
    const fill = document.getElementById('routine-days-fill');
    if (fill) {
        const chip = (mode, label) => `<button type="button" class="calendar-kind-chip${routineDaysFillMode === mode ? ' on' : ''}" role="radio" aria-checked="${routineDaysFillMode === mode}" onclick="setRoutineDaysFillMode('${mode}')">${escapeHtmlForReport(label)}</button>`;
        fill.innerHTML = chip('empty', t('routine_fill_empty')) + (canCopy ? chip('copy', t('routine_fill_copy').replace('{name}', src.name)) : '');
    }
    const tile = (icon, title, sub, onclick) => `
        <button type="button" class="routine-template-tile${locked ? ' locked' : ''}" onclick="${onclick}">
            <span class="routine-template-icon">${icon}</span>
            <span class="routine-template-title">${escapeHtmlForReport(title)}</span>
            <span class="routine-template-sub">${escapeHtmlForReport(sub)}</span>
            ${locked ? '<span class="routine-template-lock">🔒</span>' : ''}
        </button>`;
    const daysGrid = document.getElementById('routine-template-days');
    if (daysGrid) {
        daysGrid.innerHTML = ROUTINE_DAY_TEMPLATES.map(tpl => tile('📅', routineDayTemplateLabel(tpl),
            t('routine_tpl_tabs_count').replace('{n}', tpl.days.length), `applyRoutineDaysTemplate('${tpl.id}')`)).join('');
    }
    const readyGrid = document.getElementById('routine-template-ready');
    if (readyGrid) {
        readyGrid.innerHTML = ROUTINE_READY_TEMPLATES.map(tpl => tile(tpl.icon, t(`routine_tpl_${tpl.id}`),
            t('routine_tpl_items_count').replace('{n}', parseRoutineTemplateItems(t(`routine_tpl_${tpl.id}_items`)).length),
            `applyRoutineReadyTemplate('${tpl.id}')`)).join('');
    }
}

async function fetchRoutineTabItems(tabId) {
    const { data } = await supabaseClient.from('routine_items').select('title, time, vision_milestone_id, vision_goal_id').eq('tab_id', tabId).eq('user_id', currentUserId).eq('kind', 'scheduled');
    return data || [];
}

async function copyRoutineItemsToTab(items, tabId) {
    if (!items.length) return;
    const rows = items.map(it => ({ tab_id: tabId, user_id: currentUserId, title: it.title, time: it.time, kind: 'scheduled', vision_milestone_id: it.vision_milestone_id || null, vision_goal_id: it.vision_goal_id || null }));
    const { error } = await supabaseClient.from('routine_items').insert(rows);
    if (error) throw error;
}

// איחוד שעות (לכל בלוק) - טאב קיים שמתמלא בהעתק מקבל גם את השעות של המקור, כדי שהפריטים יופיעו
function mergeRoutineHours(a, b) {
    const out = {};
    ['morning', 'noon', 'afternoon', 'evening'].forEach(bucket => {
        out[bucket] = [...new Set([...(a[bucket] || []), ...(b[bucket] || [])])].sort((x, y) => x - y);
    });
    return out;
}

function uniqueRoutineTabName(base) {
    const names = new Set(dailyBoardTabs.map(tb => tb.name));
    if (!names.has(base)) return base;
    for (let i = 2; i < 100; i++) { if (!names.has(`${base} ${i}`)) return `${base} ${i}`; }
    return base;
}

async function finishRoutineTabsChange(activeId) {
    if (activeId) activeDailyBoardTabId = activeId;
    renderRoutineTabsBar();
    renderDailyBoardHourSettings();
    await renderDailyBoard();
    refreshRoutineNudge();
}

async function applyRoutineDaysTemplate(templateId) {
    const tpl = ROUTINE_DAY_TEMPLATES.find(x => x.id === templateId);
    if (!tpl || !supabaseClient || !currentUserId) return;
    if (!isPremiumUser) { closeModal('modal-routine-add-choice'); openPremiumUpgradeModal(); return; }
    const src = routineDaysFillMode === 'copy' ? dailyBoardTabs.find(tb => tb.id === activeDailyBoardTabId) : null;
    const srcItems = src ? await fetchRoutineTabItems(src.id) : [];
    const srcHours = src ? getDailyBoardCustomHours(src.id) : null;
    let ready = 0, kept = 0, firstNewId = null;
    try {
        for (const d of tpl.days) {
            const existing = routineSingleDayTabFor(d);
            if (existing) {
                // יום שכבר יש לו טאב: ריק + בחרו העתק → ממלאים אותו; אחרת לא נוגעים בו
                if (src && existing.id !== src.id && srcItems.length) {
                    const { data: existingItems } = await supabaseClient.from('routine_items').select('id').eq('tab_id', existing.id).eq('kind', 'scheduled').limit(1);
                    if (!existingItems || !existingItems.length) {
                        await copyRoutineItemsToTab(srcItems, existing.id);
                        const hours = mergeRoutineHours(getDailyBoardCustomHours(existing.id), srcHours);
                        await supabaseClient.from('routine_tabs').update({ custom_hours: hours }).eq('id', existing.id);
                        existing.custom_hours = hours;
                        ready++;
                        continue;
                    }
                }
                kept++;
                continue;
            }
            const { data, error } = await supabaseClient.from('routine_tabs').insert({
                user_id: currentUserId, username: currentUsername, name: routineWeekdayName(d), sort_order: nextRoutineTabSortOrder(),
                weekdays: [d], custom_hours: src ? srcHours : null,
            }).select('*').single();
            if (error || !data) throw error || new Error('insert failed');
            dailyBoardTabs.push(data);
            if (srcItems.length) await copyRoutineItemsToTab(srcItems, data.id);
            if (!firstNewId) firstNewId = data.id;
            ready++;
        }
    } catch (e) {
        console.error('routine days template failed', e);
        showAppToast(t('error_adding_item') + (e && e.message ? e.message : ''), 'error');
    }
    closeModal('modal-routine-add-choice');
    const todayTab = findTodayRoutineTab();
    await finishRoutineTabsChange((todayTab && todayTab.id) || firstNewId);
    let msg = t('routine_tpl_days_done').replace('{n}', ready);
    if (kept) msg += ' ' + t('routine_tpl_days_kept').replace('{n}', kept);
    showAppToast(msg);
}

async function applyRoutineReadyTemplate(templateId) {
    const tpl = ROUTINE_READY_TEMPLATES.find(x => x.id === templateId);
    if (!tpl || !supabaseClient || !currentUserId) return;
    if (!isPremiumUser) { closeModal('modal-routine-add-choice'); openPremiumUpgradeModal(); return; }
    const items = parseRoutineTemplateItems(t(`routine_tpl_${tpl.id}_items`)).filter(it => routineBucketOfHour(it.hour));
    if (!items.length) return;
    const hours = { morning: [], noon: [], afternoon: [], evening: [] };
    items.forEach(it => hours[routineBucketOfHour(it.hour)].push(it.hour));
    Object.keys(hours).forEach(b => hours[b].sort((x, y) => x - y));
    const name = uniqueRoutineTabName(`${tpl.icon} ${t('routine_tpl_' + tpl.id)}`);
    const { data, error } = await supabaseClient.from('routine_tabs').insert({
        user_id: currentUserId, username: currentUsername, name, sort_order: nextRoutineTabSortOrder(), custom_hours: hours,
    }).select('*').single();
    if (error || !data) { showAppToast(t('error_adding_item') + (error ? error.message : ''), 'error'); return; }
    dailyBoardTabs.push(data);
    const rows = items.map(it => ({ tab_id: data.id, user_id: currentUserId, title: it.title, time: `${String(it.hour).padStart(2, '0')}:00`, kind: 'scheduled' }));
    const { error: itemsError } = await supabaseClient.from('routine_items').insert(rows);
    if (itemsError) showAppToast(t('error_adding_item') + itemsError.message, 'error');
    closeModal('modal-routine-add-choice');
    await finishRoutineTabsChange(data.id);
    showAppToast(t('routine_tpl_ready_done').replace('{name}', name));
}

// שכפול: טאב חדש עם אותן שעות ואותם פריטים (בלי הסימונים). טאב של יום אחד ("ראשון") מציע
// אוטומטית את היום הפנוי הבא ("שני") - כך בונים שגרה לכל יום הכי מהר, לפי בקשה מפורשת
let routineDuplicatePending = null;
function routineStartDuplicateTab() {
    const src = dailyBoardTabs.find(tb => tb.id === activeDailyBoardTabId);
    if (!src) return;
    closeModal('modal-routine-add-choice');
    let name = t('routine_copy_name').replace('{name}', src.name);
    let weekdays = null;
    const srcDays = routineTabWeekdays(src);
    if (srcDays.length === 1) {
        for (let k = 1; k < 7; k++) {
            const d = (srcDays[0] + k) % 7;
            if (!routineSingleDayTabFor(d)) { name = routineWeekdayName(d); weekdays = [d]; break; }
        }
    }
    routineDuplicatePending = { srcTabId: src.id, suggestedName: name, weekdays };
    routineTabNameMode = 'duplicate';
    document.getElementById('routine-tab-name-modal-title').textContent = t('routine_duplicate_title').replace('{name}', src.name);
    document.getElementById('routine-tab-name-input').value = name;
    openModalOverDailyBoard('modal-routine-tab-name');
}

async function duplicateRoutineTab(name) {
    const pending = routineDuplicatePending;
    routineDuplicatePending = null;
    const src = pending && dailyBoardTabs.find(tb => tb.id === pending.srcTabId);
    if (!src || !supabaseClient || !currentUserId) return;
    let weekdays = null;
    if (pending.weekdays && name === pending.suggestedName) weekdays = pending.weekdays;
    const srcItems = await fetchRoutineTabItems(src.id);
    const { data, error } = await supabaseClient.from('routine_tabs').insert({
        user_id: currentUserId, username: currentUsername, name: uniqueRoutineTabName(name), sort_order: nextRoutineTabSortOrder(),
        custom_hours: src.custom_hours || null, weekdays,
    }).select('*').single();
    if (error || !data) { showAppToast(t('error_adding_item') + (error ? error.message : ''), 'error'); return; }
    dailyBoardTabs.push(data);
    try {
        await copyRoutineItemsToTab(srcItems, data.id);
    } catch (e) {
        showAppToast(t('error_adding_item') + (e && e.message ? e.message : ''), 'error');
    }
    await finishRoutineTabsChange(data.id);
    showAppToast(t('routine_duplicate_done').replace('{name}', data.name));
}

// --- 🌱 פריט שלא סומן ✓ יותר מ-3 ימים: כרטיס עדין בראש "השגרה שלי" ששואל אם זה עדיין חלק
// מהשגרה, אם זה עובד ואם כדאי לשנות משהו כדי להתקדם - לפי בקשה מפורשת. נספרים רק הימים
// שבהם הפריט קיים (ימי הטאב; טאב בלי ימים = כל יום), ואותו שם בכמה טאבים (אותו הרגל שהועתק
// לכל יום) נחשב פריט אחד. רק למי שמשתמש/ת ב-✓ בפועל (סימון אחד לפחות ב-14 הימים האחרונים).
// "כן, ממשיכים" = לא שואלים שבוע; "לשנות"/"להקטין" = עוד 3 ימים להתחיל מחדש; ✕ = מחר ---
const ROUTINE_NUDGE_MISSES = 3;
let routineNudge = null;
let routineNudgeEditing = null;

function normalizeRoutineTitle(title) { return String(title || '').trim().toLowerCase().replace(/\s+/g, ' '); }
function daysBetweenDateStrs(a, b) {
    const [ay, am, ad] = a.split('-').map(Number);
    const [by, bm, bd] = b.split('-').map(Number);
    return Math.round((Date.UTC(by, bm - 1, bd) - Date.UTC(ay, am - 1, ad)) / 86400000);
}

async function refreshRoutineNudge() {
    routineNudge = null;
    if (!isRoutineGoalsOn() || !supabaseClient || !currentUserId || !isDailyBoardOpen()) { renderRoutineNudge(); return; }
    const todayStr = getLocalDateString();
    const [{ data: items }, { data: checks }] = await Promise.all([
        supabaseClient.from('routine_items').select('id, tab_id, title, time, created_at, nudge_snoozed_until').eq('user_id', currentUserId).eq('kind', 'scheduled'),
        supabaseClient.from('routine_item_checkins').select('item_id, checkin_date').eq('user_id', currentUserId).gte('checkin_date', addDaysToDateStr(todayStr, -35)),
    ]);
    const recentFrom = addDaysToDateStr(todayStr, -14);
    if (!items || !items.length || !(checks || []).some(c => c.checkin_date >= recentFrom)) { renderRoutineNudge(); return; }
    const checksByItem = new Map();
    (checks || []).forEach(c => {
        if (!checksByItem.has(c.item_id)) checksByItem.set(c.item_id, new Set());
        checksByItem.get(c.item_id).add(c.checkin_date);
    });
    const tabById = new Map(dailyBoardTabs.map(tb => [tb.id, tb]));
    const groups = new Map();
    items.forEach(it => {
        const tab = tabById.get(it.tab_id);
        const key = normalizeRoutineTitle(it.title);
        if (!tab || !key) return;
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push({ ...it, tab });
    });
    const candidates = [];
    groups.forEach((list, key) => {
        if (list.some(it => it.nudge_snoozed_until && it.nudge_snoozed_until > todayStr)) return;
        let everyDay = false;
        const days = new Set();
        list.forEach(it => {
            const tabDays = routineTabWeekdays(it.tab);
            if (!tabDays.length) everyDay = true;
            tabDays.forEach(d => days.add(d));
        });
        const isDue = dateStr => everyDay || days.has(new Date(`${dateStr}T12:00:00`).getDay());
        const createdStr = list.map(it => getLocalDateString(new Date(it.created_at))).sort()[0];
        const checked = new Set();
        list.forEach(it => (checksByItem.get(it.id) || new Set()).forEach(d => checked.add(d)));
        if (checked.has(todayStr)) return;
        // אחורה מאתמול, רק בימים שבהם הפריט קיים: 3 פספוסים רצופים (בלי ✓ באמצע)
        let misses = 0;
        let dateStr = addDaysToDateStr(todayStr, -1);
        for (let step = 0; step < 35 && dateStr >= createdStr; step++) {
            if (isDue(dateStr)) {
                if (checked.has(dateStr)) break;
                misses++;
                if (misses >= ROUTINE_NUDGE_MISSES) break;
            }
            dateStr = addDaysToDateStr(dateStr, -1);
        }
        if (misses < ROUTINE_NUDGE_MISSES) return;
        const lastCheck = [...checked].sort().pop() || null;
        candidates.push({ key, list, sinceDays: daysBetweenDateStrs(lastCheck || createdStr, todayStr) });
    });
    if (candidates.length) {
        candidates.sort((a, b) => b.sinceDays - a.sinceDays);
        const pick = candidates[0];
        const first = pick.list.find(it => it.tab_id === activeDailyBoardTabId) || pick.list[0];
        routineNudge = {
            title: first.title, time: (first.time || '').slice(0, 5), tabId: first.tab_id, tabName: first.tab.name,
            itemIds: pick.list.map(it => it.id), tabCount: new Set(pick.list.map(it => it.tab_id)).size,
            sinceDays: pick.sinceDays, item: first,
        };
    }
    renderRoutineNudge();
}

function renderRoutineNudge() {
    const slot = document.getElementById('routine-nudge-slot');
    if (!slot) return;
    const n = routineNudge;
    if (!n || !isRoutineGoalsOn()) { slot.innerHTML = ''; return; }
    const where = n.tabCount > 1 ? t('routine_nudge_where_tabs').replace('{n}', n.tabCount) : n.tabName;
    slot.innerHTML = `
        <div class="routine-nudge-card" role="status">
            <button type="button" class="routine-nudge-later" onclick="routineNudgeLater()" title="${escapeHtmlForReport(t('routine_nudge_later'))}" aria-label="${escapeHtmlForReport(t('routine_nudge_later'))}">✕</button>
            <div class="routine-nudge-head">🌱 <strong>${escapeHtmlForReport(n.title)}</strong></div>
            <div class="routine-nudge-meta">${n.time ? `${escapeHtmlForReport(n.time)} · ` : ''}${escapeHtmlForReport(where)}</div>
            <p class="routine-nudge-text">${escapeHtmlForReport(t('routine_nudge_days').replace('{n}', n.sinceDays))} ${escapeHtmlForReport(t('routine_nudge_question'))}</p>
            <div class="routine-nudge-actions">
                <button type="button" class="routine-nudge-btn primary" onclick="routineNudgeKeep()">✓ ${escapeHtmlForReport(t('routine_nudge_keep'))}</button>
                <button type="button" class="routine-nudge-btn" onclick="routineNudgeChange()">✏️ ${escapeHtmlForReport(t('routine_nudge_change'))}</button>
                <button type="button" class="routine-nudge-btn" onclick="routineNudgeRemove()">🗑️ ${escapeHtmlForReport(t('routine_nudge_remove'))}</button>
            </div>
        </div>`;
}

async function snoozeRoutineNudgeItems(itemIds, days) {
    if (!itemIds || !itemIds.length || !supabaseClient) return;
    await supabaseClient.from('routine_items').update({ nudge_snoozed_until: addDaysToDateStr(getLocalDateString(), days) }).in('id', itemIds);
}

async function routineNudgeKeep() {
    const n = routineNudge;
    if (!n) return;
    routineNudge = null;
    renderRoutineNudge();
    showAppToast(t('routine_nudge_keep_toast'));
    await snoozeRoutineNudgeItems(n.itemIds, 7);
    refreshRoutineNudge();
}

async function routineNudgeLater() {
    const n = routineNudge;
    if (!n) return;
    routineNudge = null;
    renderRoutineNudge();
    await snoozeRoutineNudgeItems(n.itemIds, 1);
    refreshRoutineNudge();
}

// ✏️ לשנות - פותח את הפריט לעריכה (היה גם "🌱 להקטין" שעשה בדיוק אותו דבר - הוסר לפי בקשה מפורשת)
async function routineNudgeChange() {
    const n = routineNudge;
    if (!n) return;
    if (n.tabId !== activeDailyBoardTabId) {
        activeDailyBoardTabId = n.tabId;
        renderRoutineTabsBar();
        renderDailyBoardHourSettings();
        await renderDailyBoard();
    }
    openEditRoutineItemModal(n.item, { fromNudge: true });
}

function routineNudgeRemove() {
    const n = routineNudge;
    if (!n) return;
    const message = n.tabCount > 1
        ? t('routine_nudge_remove_confirm_all').replace('{name}', n.title).replace('{n}', n.tabCount)
        : t('routine_nudge_remove_confirm').replace('{name}', n.title);
    showDangerConfirm(t('routine_nudge_remove_title'), message, async () => {
        await supabaseClient.from('routine_items').delete().in('id', n.itemIds);
        routineNudge = null;
        await renderDailyBoard();
        showAppToast(t('routine_nudge_removed_toast'));
        refreshRoutineNudge();
    });
}

function showDangerConfirm(titleText, messageText, onConfirm) {
    document.getElementById('danger-confirm-title').textContent = titleText;
    document.getElementById('danger-confirm-message').textContent = messageText;
    const btn = document.getElementById('btn-danger-confirm-proceed');
    const freshBtn = btn.cloneNode(true);
    btn.parentNode.replaceChild(freshBtn, btn);
    freshBtn.addEventListener('click', () => { closeModal('modal-danger-confirm'); onConfirm(); });
    // מתוך "השגרה שלי" (למשל מחיקת טאב) - האישור נפתח מעליה ולא סוגר אותה
    openModalOverDailyBoard('modal-danger-confirm');
}

// --- לוח החזון (Vision Board) - מגירה שנייה מהצד (אותה תבנית בדיוק כמו
// hamburger-drawer-overlay) עם כרטיסי-יעד שמתהפכים (CSS 3D flip) לרשימת
// תחנות-ביניים. אחוז ההתקדמות *נגזר* ממספר התחנות שסומנו כבוצעו (done/total),
// לא ערך נפרד שנשמר - כדי שלא יהיה מקור-אמת כפול שיכול לסטות מרשימת התחנות ---
const VISION_GOAL_CATEGORY_PRESETS = [
    { key: 'career', icon: '💼' },
    { key: 'health', icon: '💪' },
    { key: 'finance', icon: '💰' },
    { key: 'relationships', icon: '❤️' },
    { key: 'learning', icon: '📚' },
    { key: 'travel', icon: '✈️' },
    { key: 'personal', icon: '🌱' },
    { key: 'other', icon: '🎯' },
];

let visionGoalsCache = [];
let visionMilestonesCache = [];

// מסך "היעדים שלי" (מסך מלא, ר' renderVisionGoalsList). goalId - לפתוח ישר על השביל של יעד מסוים
function openGoalsVisionDrawer(goalId) {
    const view = document.getElementById('vision-drawer-overlay');
    if (view) { view.classList.add('open'); view.setAttribute('aria-hidden', 'false'); }
    const wrapper = document.querySelector('.phone-wrapper');
    if (wrapper) wrapper.classList.add('vision-open');
    if (goalId) visionSelectedGoalId = goalId;
    else {
        // הישג שנבחר בפעם הקודמת - פותחים שוב על היעדים הפעילים
        const sel = visionGoalsCache.find(g => g.id === visionSelectedGoalId);
        if (sel && sel.is_achieved) visionSelectedGoalId = null;
    }
    visionAnimatePath = true;
    const scroll = document.getElementById('goals-view-scroll');
    if (scroll) scroll.scrollTop = 0;
    // מהמטמון מיד, ואחרי הטעינה שוב (בפעם הראשונה - השביל מצטייר אחרי הטעינה)
    renderVisionGoalsList();
    if (!visionGoalsCache.length) visionAnimatePath = true;
    loadVisionGoals();
}
function closeGoalsVisionDrawer() {
    const view = document.getElementById('vision-drawer-overlay');
    if (view) { view.classList.remove('open'); view.setAttribute('aria-hidden', 'true'); }
    // ספריית היעדים נפתחת מעל המסך הזה - נסגרת איתו
    if (typeof closeGoalsLibrary === 'function') closeGoalsLibrary();
    const wrapper = document.querySelector('.phone-wrapper');
    if (wrapper) wrapper.classList.remove('vision-open');
}
function isGoalsViewOpen() {
    const view = document.getElementById('vision-drawer-overlay');
    return !!(view && view.classList.contains('open'));
}

// --- מחברת "📝 משימות" (שיעורי הבית של פעם) - המחברת הקבועה על המדף העליון ב"המחברות שלי"
// (ר' openTasksNotebook). טבלה נפרדת (study_tasks) ולא my_center_tasks, כי כאן אין צבעים/"להגיע
// לזה"/גרירה - רק כותרת + וי, וקישור אופציונלי לצעד ביעד ---
let studyTasksCache = [];
let editingStudyItemId = null;

async function loadStudyTasks() {
    if (!supabaseClient || !currentUserId) return;
    const { data, error } = await supabaseClient.from('study_tasks').select('*').eq('user_id', currentUserId).order('created_at', { ascending: false });
    if (error) return;
    studyTasksCache = data || [];
    renderStudyTasksList();
    // מספר המשימות הפתוחות על הכריכה ובסיכום של הארון
    if (isNotebooksSectionOpen()) renderNotebookShelves();
}

// לחיצה על הטקסט (לא הצ'קבוקס/עריכה/מחיקה) מרחיבה את השורה במקום, במקום
// חיתוך בשלוש נקודות - "hover" לא רלוונטי באפליקציית מובייל, לפי בקשה מפורשת
function toggleStudyItemExpand(el) {
    const row = el.closest('.study-task-item');
    if (row) row.classList.toggle('expanded');
}

function renderStudyTasksList() {
    const listEl = document.getElementById('study-tasks-list');
    const emptyEl = document.getElementById('study-tasks-empty');
    if (!listEl) return;
    listEl.innerHTML = '';
    if (emptyEl) emptyEl.classList.toggle('hidden', studyTasksCache.length > 0);
    studyTasksCache.forEach(item => {
        const li = document.createElement('li');
        li.className = 'study-task-item';
        // משימה ששייכת לכיס ב"התיק שלי" - תווית קטנה בצבע הכיס
        const pocket = isPremiumUser && item.project_id ? projectsCache.find(p => p.id === item.project_id) : null;
        li.innerHTML = `
            <button type="button" class="btn-complete-item${item.is_completed ? ' checked' : ''}" onclick="toggleStudyTaskStatus('${item.id}', ${item.is_completed})">${item.is_completed ? '✓' : ''}</button>
            <span class="center-list-item-text${item.is_completed ? ' completed' : ''}" onclick="toggleStudyItemExpand(this)">${escapeHtmlForReport(item.title)}</span>
            ${pocket ? `<span class="study-task-pocket" style="--pocket:${escapeHtmlForReport(bagPocketColor(pocket))}">${escapeHtmlForReport(bagPocketLabel(pocket))}</span>` : ''}
            <button type="button" class="btn-edit-item" onclick="openEditStudyItemModal('${item.id}')">${EDIT_ICON_SVG}</button>
            <button type="button" class="btn-delete-item" onclick="deleteStudyTask('${item.id}')">❌</button>
        `;
        listEl.appendChild(li);
    });
}

// אם יש תחנת-ביניים מקושרת ("קישור אופציונלי ללוח החזון"), מסמנים אותה
// באותה פעולה, ואז בודקים אם זה משלים את כל היעד - לפי בקשה מפורשת
async function toggleStudyTaskStatus(id, currentStatus) {
    if (!supabaseClient) return;
    const newStatus = !currentStatus;
    await supabaseClient.from('study_tasks').update({ is_completed: newStatus }).eq('id', id);
    const item = studyTasksCache.find(x => x.id === id);
    if (item && item.linked_milestone_id) {
        const { data: milestoneRow } = await supabaseClient.from('vision_goal_milestones').update({ is_done: newStatus }).eq('id', item.linked_milestone_id).select('goal_id').maybeSingle();
        if (milestoneRow) await checkAndMarkGoalAchieved(milestoneRow.goal_id);
    }
    loadStudyTasks();
}

// בונה את אפשרויות בורר "קישור לתחנת-ביניים" מ-visionMilestonesCache - רק
// תחנות שעוד לא בוצעו (אין טעם לקשר למשהו שכבר מסומן). אם המגירה של לוח
// החזון עוד לא נפתחה בסשן הזה, ה-cache ריק - טוענים אותו כאן במפורש כדי
// שהבורר לא יהיה ריק סתם
// שני שלבים - קודם בוחרים יעד, ואז רק התחנות של אותו יעד - לא רשימה שטוחה
// אחת עם כל התחנות מכל היעדים מעורבבות יחד, לפי בקשה מפורשת ("אם יהיו כמה
// חזונים... שתבדוק קודם על איזה חזון מדובר")
async function renderStudyMilestoneOptions(selectedMilestoneId) {
    if (!visionGoalsCache.length && !visionMilestonesCache.length) await loadVisionGoals();
    let selectedGoalId = '';
    if (selectedMilestoneId) {
        const m = visionMilestonesCache.find(x => x.id === selectedMilestoneId);
        if (m) selectedGoalId = m.goal_id;
    }
    renderStudyGoalOptions(selectedGoalId);
    renderStudyMilestoneOptionsForGoal(selectedGoalId, selectedMilestoneId);
}

function renderStudyGoalOptions(selectedGoalId) {
    const select = document.getElementById('study-item-goal');
    if (!select) return;
    select.innerHTML = `<option value="" data-i18n="study_milestone_none_option">${t('study_milestone_none_option')}</option>`;
    // רק יעדים עם לפחות תחנה אחת שעוד לא בוצעה - אין טעם להציע יעד שאין לו
    // אליו מה לקשר (או שכבר הושג לגמרי)
    visionGoalsCache.filter(g => visionMilestonesCache.some(m => m.goal_id === g.id && !m.is_done)).forEach(g => {
        const opt = document.createElement('option');
        opt.value = g.id;
        opt.textContent = g.title;
        select.appendChild(opt);
    });
    select.value = selectedGoalId || '';
    updateCustomSelectDisplay('study-item-goal');
}

function renderStudyMilestoneOptionsForGoal(goalId, selectedMilestoneId) {
    const select = document.getElementById('study-item-milestone');
    const trigger = document.getElementById('study-item-milestone-trigger');
    if (!select) return;
    select.innerHTML = `<option value="" data-i18n="study_milestone_none_option">${t('study_milestone_none_option')}</option>`;
    if (goalId) {
        visionMilestonesCache.filter(m => m.goal_id === goalId && !m.is_done).forEach(m => {
            const opt = document.createElement('option');
            opt.value = m.id;
            opt.textContent = m.title;
            select.appendChild(opt);
        });
    }
    select.value = selectedMilestoneId || '';
    updateCustomSelectDisplay('study-item-milestone');
    if (trigger) trigger.classList.toggle('hidden', !goalId);
}

async function openAddStudyItemModal() {
    editingStudyItemId = null;
    document.getElementById('study-item-modal-title').textContent = t('study_add_item_title');
    document.getElementById('study-item-input').value = '';
    // הכיס שממנו נפתחה ההוספה (בתיק), אחרת "משימות כלליות"
    bagPrepareTaskPocketField(bagPendingPocketId);
    await renderStudyMilestoneOptions(null);
    openModal('modal-add-study-item');
    setTimeout(() => document.getElementById('study-item-input').focus(), 150);
}

async function openEditStudyItemModal(id) {
    const item = studyTasksCache.find(x => x.id === id);
    if (!item) return;
    editingStudyItemId = id;
    document.getElementById('study-item-modal-title').textContent = t('edit_item_title');
    document.getElementById('study-item-input').value = item.title;
    bagPrepareTaskPocketField(item.project_id);
    await renderStudyMilestoneOptions(item.linked_milestone_id);
    openModal('modal-add-study-item');
    setTimeout(() => document.getElementById('study-item-input').focus(), 150);
}

async function submitStudyItem() {
    const input = document.getElementById('study-item-input');
    const title = input.value.trim();
    const milestoneSelect = document.getElementById('study-item-milestone');
    const linkedMilestoneId = milestoneSelect && milestoneSelect.value ? milestoneSelect.value : null;
    const editId = editingStudyItemId;
    if (!title) { closeModal('modal-add-study-item'); editingStudyItemId = null; return; }
    if (!supabaseClient || !currentUserId) return;
    // הכיס נקבע רק אצל מנויי פרימיום (בלי פרימיום השדה מוסתר והמשימה נשארת כמו שהיא)
    const fields = { title, linked_milestone_id: linkedMilestoneId };
    if (isPremiumUser) {
        const projectId = await bagResolvePocketSelect('study-item-pocket', 'study-item-new-pocket');
        if (projectId === false) return;
        fields.project_id = projectId;
    }
    closeModal('modal-add-study-item');
    editingStudyItemId = null;
    bagPendingPocketId = null;
    if (editId) {
        await supabaseClient.from('study_tasks').update(fields).eq('id', editId);
    } else {
        await supabaseClient.from('study_tasks').insert({ user_id: currentUserId, username: currentUsername, ...fields });
    }
    await loadStudyTasks();
    showAppToast(t(editId ? 'item_updated_success' : 'item_added_success'));
}

async function deleteStudyTask(id) {
    if (!supabaseClient) return;
    await supabaseClient.from('study_tasks').delete().eq('id', id);
    loadStudyTasks();
}

// מקטינה תמונה מהמצלמה (לרוב 4000+ פיקסלים) ל-1600 בצד הארוך ומקודדת JPEG - כדי
// שהבקשה לשרת תהיה קטנה ומהירה, בלי לפגוע בקריאות של כתב-יד/לוח בתמונה
async function downscaleImageToBase64(file, maxDim = 1600, quality = 0.85) {
    // createImageBitmap קודם (מפענח גם תמונות גדולות מהמצלמה בלי לחנוק את הזיכרון
    // בנייד, ומכבד את כיוון הצילום), ואם לא נתמך - <img> רגיל כגיבוי
    let source = null, width = 0, height = 0, url = null;
    try {
        if (typeof createImageBitmap === 'function') {
            try {
                source = await Promise.race([
                    createImageBitmap(file, { imageOrientation: 'from-image' }),
                    new Promise((_, reject) => setTimeout(() => reject(new Error('bitmap timeout')), 8000)),
                ]);
                width = source.width; height = source.height;
            } catch { source = null; }
        }
        if (!source) {
            url = URL.createObjectURL(file);
            source = await new Promise((resolve, reject) => {
                const el = new Image();
                // קובץ פגום/לא נתמך לא אמור להשאיר את הכפתור תקוע על ⏳ לנצח
                const timer = setTimeout(() => reject(new Error('decode timeout')), 15000);
                el.onload = () => { clearTimeout(timer); resolve(el); };
                el.onerror = () => { clearTimeout(timer); reject(new Error('decode failed')); };
                el.src = url;
            });
            width = source.naturalWidth || source.width; height = source.naturalHeight || source.height;
        }
        if (!width || !height) throw new Error('empty image');
        const scale = Math.min(1, maxDim / Math.max(width, height));
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(width * scale));
        canvas.height = Math.max(1, Math.round(height * scale));
        canvas.getContext('2d').drawImage(source, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg', quality);
        const base64 = dataUrl.split(',')[1];
        if (!base64 || base64.length < 100) throw new Error('encode failed');
        return { mediaType: 'image/jpeg', base64 };
    } finally {
        if (url) URL.revokeObjectURL(url);
        if (source && typeof source.close === 'function') source.close();
    }
}

// --- "הפרויקטים שלי" - תכונה נפרדת ועוצמתית יותר מ"לימודים" (פרויקטים >
// מחברות > שורות, כל מחברת נראית בדיוק כמו לימודים), נגישה רק דרך כפתור
// בתחתית מגירת לימודים - לפי בקשה מפורשת ("אני רוצה שהלימודים עצמם ישארו
// ככה"). פרימיום בלבד, אותו דפוס נעילה בדיוק כמו openSmartSplitModal ---
let projectsCache = [];

let notebookItemsCache = [];
let currentOpenProjectId = null;
let currentOpenNotebookId = null;
let editingProjectId = null;
let editingNotebookId = null;
let editingNotebookItemId = null;

// --- מחברת רב-דפים (notebook_pages, בין project_notebooks ל-notebook_items) -
// כל דף מכיל גם רשימת שורות-טקסט (notebook_items, כמו קודם, רק page_id
// במקום notebook_id) וגם ציור-יד חופשי (canvas_data, ר' שכבת הקנבס למטה) -
// לפי בקשה מפורשת ("גם ידנית אם זה באייפד וגם בתור טקסט... דף אינסופי...
// אפשרות לעבור בין הדפים ולכל דף לקרוא בשם... לחפש בדפים")
let notebookPagesCache = [];
let currentOpenPageId = null;
let editingPageId = null;
let notebookAllItemsCache = []; // כל הפריטים מכל דפי המחברה הפתוחה - לחיפוש בלבד
let notebookPagesSearchFilterIds = null; // null = בלי סינון פעיל בפאנל הדפים

// --- שכבת הציור החופשי על כל דף - ללא תקדים בקוד הזה, נבנה מאפס. כל קו
// נשמר כמערך נקודות מנורמל 0-1 (יחסי לגודל הקנבס בפועל), כך שדף שצויר
// באייפד (קנבס רחב) ישוחזר נכון גם בטלפון (קנבס צר) בלי מידע נוסף על גודל
// המכשיר. ר' redrawCanvasFromStrokes/saveCanvasData למטה ---
let canvasStrokes = [];
let currentStroke = null;
let penColor = '#2b2b2b';
// currentDrawTool מחליף את isEraserMode הישן (בוליאני יחיד, לא הספיק כשנוספו
// עוד כלים) - 'pen'/'marker'/'marker_square'/'eraser'. penWidth רלוונטי רק
// לעט (עוד עטים/עוביים לפי בקשה מפורשת) - למרקר יש עובי קבוע משלו, בכוונה
// לא מושפע מבורר-העובי, כדי לא להסתבך עם ציפייה למרקר-דק/עבה שלא התבקשה
let currentDrawTool = 'pen';
let penWidth = 3;
let notebookCanvasPointerBound = false;
const NOTEBOOK_EMOJI_PRESETS = ['😀','😂','🥰','😎','🤩','😭','😡','🥳','🤔','😴','👍','👎','👏','🙌','🤝','💪','🙏','✌️','🤞','👋','❤️','🧡','💛','💚','💙','💜','🖤','🤍','💯','🔥','⭐','✨','🎉','🎈','🎁','🏆','✅','❌','❓','❗','📌','📍','📎','🔔','💡','📝','📚','🎯','🚀','🌈'];

// אייקון וצבע לכל כיס (פרויקט) ב"התיק שלי" - כדי להבחין במבט חטוף בין כיסים (בית, משפחה, עבודה, טיולים...).
// האמוג'י עצמו הוא גם המזהה וגם התצוגה (ר' renderProjectIconPicker); הצבעים - BAG_POCKET_COLORS ב-bag.js
const PROJECT_ICON_PRESETS = ['🏠', '👨‍👩‍👧', '💡', '🧳', '💼', '🎨', '🍳', '🎉', '🌱', '⚽', '🎵', '📚', '💰', '🐾', '❤️', '📁'];
let selectedProjectIcon = '🏠';
let selectedProjectColor = null;

// --- טבלאות מותאמות אישית (Tables) - מסך top-level נפרד לגמרי, לא מקונן
// בתוך תחום קיים (לימודים/משימות/לוח חזון) - לפי בקשה מפורשת. משתמשת יוצרת
// כמה טבלאות שהיא רוצה, לכל טבלה עמודות מותאמות אישית (טקסט/מספר/בחירה/
// תאריך/וי) ושורות חופשיות - בדומה למסד-נתונים של Notion. נעול לפרימיום,
// באותו דפוס בדיוק כמו openMyProjectsEntry למטה
let customTablesCache = [];
let customTableColumnsCache = [];
let customTableRowsCache = [];
let currentOpenTableId = null;
let editingCustomTableId = null;
// פתקים צבעוניים ('note:<צבע>') מצוירים כ-SVG (אין אימוג'י של פתק ורוד/סגול) -
// ר' tableIconHtml; כל השאר אימוג'ים רגילים
const TABLE_NOTE_ICON_COLORS = { pink: '#f9a8d4', yellow: '#fde047', purple: '#c4b5fd', blue: '#93c5fd', green: '#86efac', orange: '#fdba74' };
const TABLE_ICON_PRESETS = [
    '📋', '📊', '📈', '🗂️', '📦', '🎬', '🎮', '🛠️', '🏠', '🚗', '🐾', '🎓',
    'note:pink', 'note:yellow', 'note:purple', 'note:blue', 'note:green', 'note:orange',
    '📝', '🗒️', '📒', '📌', '📍', '💡', '🎁', '🎉', '🎂', '❤️', '⭐', '✅',
    '🛒', '💰', '🧾', '💳', '📅', '⏰', '✈️', '🧳', '🍽️', '🍳', '💊', '🏥',
    '🏋️', '⚽', '👶', '👨‍👩‍👧', '🐶', '🌱', '🌸', '📚', '💼', '💻', '📷', '🎵',
    '🎨', '👗', '💄', '🧹', '🔑', '📞', '🎯', '🏆',
];
function tableIconHtml(icon) {
    const match = /^note:(\w+)$/.exec(icon || '');
    const color = match && TABLE_NOTE_ICON_COLORS[match[1]];
    if (color) {
        return `<svg class="table-note-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3h16v12l-6 6H4z" fill="${color}"/><path d="M14 21v-6h6z" fill="rgba(0,0,0,.18)"/><path d="M7.5 8h9M7.5 11.5h9M7.5 15h4.5" stroke="rgba(0,0,0,.35)" stroke-width="1.4" stroke-linecap="round"/></svg>`;
    }
    return escapeHtmlForReport(icon || '📋');
}
let selectedTableIcon = TABLE_ICON_PRESETS[0];

// הטבלאות גרות בכיסים של "התיק שלי" (bag.js: טעינה ב-loadNotebooksHome, מסך מלא ב-openTableView) - כאן
// החלונות (שם, אייקון, כיס, עמודות) והגריד

function renderTableIconPicker() {
    const container = document.getElementById('table-icon-picker');
    if (!container) return;
    container.innerHTML = '';
    // אייקון שלא ברשימה (הוקלד ידנית או הוצע ע"י ה-AI) מוצג ראשון, מסומן
    const icons = TABLE_ICON_PRESETS.includes(selectedTableIcon) ? TABLE_ICON_PRESETS : [selectedTableIcon, ...TABLE_ICON_PRESETS];
    icons.forEach(icon => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'icon-picker-chip' + (selectedTableIcon === icon ? ' selected' : '');
        chip.innerHTML = tableIconHtml(icon);
        chip.onclick = () => selectTableIcon(icon);
        container.appendChild(chip);
    });
}
function selectTableIcon(icon) {
    selectedTableIcon = icon;
    renderTableIconPicker();
}
function openAddTableModal() {
    // איפוס חד-משמעי - כדי שטבלה שנוצרת ידנית אחרי ניסיון AI שננטש לא "תירש"
    // עמודות/שורות ממתינות מהניסיון הקודם (ר' resetAiTableBuilderState)
    resetAiTableBuilderState();
    if (!isPremiumUser) { openPremiumUpgradeModal(); return; }
    editingCustomTableId = null;
    document.getElementById('table-modal-title').textContent = t('table_add_modal_title');
    document.getElementById('btn-save-table').textContent = t('add_btn');
    document.getElementById('table-name-input').value = '';
    selectedTableIcon = TABLE_ICON_PRESETS[0];
    renderTableIconPicker();
    // טבלה חדשה נכנסת לכיס שממנו נפתחה ההוספה (bagPendingPocketId), אחרת לכיס הראשון
    bagPrepareTablePocketField(bagPendingPocketId, false);
    document.getElementById('table-delete-btn').classList.add('hidden');
    openModal('modal-add-table');
    setTimeout(() => document.getElementById('table-name-input').focus(), 150);
}

function openEditTableModal(tableId) {
    const table = customTablesCache.find(tbl => tbl.id === tableId);
    if (!table) return;
    editingCustomTableId = tableId;
    document.getElementById('table-modal-title').textContent = t('table_edit_modal_title');
    document.getElementById('btn-save-table').textContent = t('save_generic');
    document.getElementById('table-name-input').value = table.name;
    selectedTableIcon = table.icon || TABLE_ICON_PRESETS[0];
    renderTableIconPicker();
    // טבלה מלפני התיק (בלי כיס) נשארת כך עד שבוחרים לה כיס
    bagPrepareTablePocketField(table.project_id || null, !table.project_id || !projectsCache.some(p => p.id === table.project_id));
    document.getElementById('table-delete-btn').classList.remove('hidden');
    openModal('modal-add-table');
}

// דגל חד-פעמי נגד הגשה כפולה, אותו דפוס בדיוק כמו centerItemSubmitInFlight/
// addCalendarEventInFlight - בלי זה, טאפ כפול מהיר על "הוספה" היה יכול
// ליצור שתי שורות custom_tables זהות
let saveCustomTableInFlight = false;
async function saveCustomTable() {
    if (saveCustomTableInFlight) return;
    saveCustomTableInFlight = true;
    try {
        await saveCustomTableImpl();
    } finally {
        saveCustomTableInFlight = false;
    }
}
async function saveCustomTableImpl() {
    const input = document.getElementById('table-name-input');
    const name = input.value.trim();
    if (!name) { showAppToast(t('calendar_event_missing_fields'), 'error'); return; }
    const icon = selectedTableIcon;
    const editId = editingCustomTableId;
    // הכיס (או "➕ כיס חדש…" - נוצר כאן); false = יצירת הכיס נכשלה והטעות כבר הוצגה
    const projectId = await bagResolvePocketSelect('table-pocket', 'table-new-pocket');
    if (projectId === false) return;
    if (editId) {
        const { error } = await supabaseClient.from('custom_tables').update({ name, icon, project_id: projectId }).eq('id', editId);
        if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
        const table = customTablesCache.find(tbl => tbl.id === editId);
        if (table) Object.assign(table, { name, icon, project_id: projectId });
        closeModal('modal-add-table');
        editingCustomTableId = null;
        renderNotebookShelves();
        showAppToast(t('item_updated_success'));
        return;
    }
    // .select().single() (לא bare insert) - צריך את ה-id האמיתי של הטבלה
    // החדשה מיד כדי להמשיך אוטומטית לעורך העמודות בזרימת ה-AI
    // (aiTableBuilderReviewActive), ר' openColumnManagerForAiReview למטה
    const { data, error } = await supabaseClient.from('custom_tables').insert({ user_id: currentUserId, username: currentUsername, name, icon, project_id: projectId, sort_order: Date.now() }).select().single();
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    customTablesCache.push(data);
    bagPendingPocketId = null;
    closeModal('modal-add-table');
    editingCustomTableId = null;
    currentOpenTableId = data.id;
    if (aiTableBuilderReviewActive) { openColumnManagerForAiReview(); return; }
    // טבלה חדשה נפתחת מיד, ישר עם חלון העמודות - טבלה בלי עמודות היא עוד לא טבלה
    renderNotebookShelves();
    showAppToast(t('item_added_success'));
    await openTableView(data.id);
    openColumnManager();
}

function deleteCustomTableFromModal() {
    const id = editingCustomTableId;
    if (!id) return;
    closeModal('modal-add-table');
    editingCustomTableId = null;
    deleteCustomTable(id);
}
function deleteCustomTable(tableId) {
    showDangerConfirm(t('table_delete_title'), t('table_delete_confirm'), async () => {
        const { error } = await supabaseClient.from('custom_tables').delete().eq('id', tableId);
        if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
        customTablesCache = customTablesCache.filter(tbl => tbl.id !== tableId);
        if (currentOpenTableId === tableId) closeTableView();
        else renderNotebookShelves();
    });
}

async function loadTableColumnsAndRows(tableId) {
    if (!supabaseClient || !currentUserId) return;
    const [colsRes, rowsRes] = await Promise.all([
        supabaseClient.from('custom_table_columns').select('*').eq('table_id', tableId).order('sort_order', { ascending: true }),
        supabaseClient.from('custom_table_rows').select('*').eq('table_id', tableId).order('sort_order', { ascending: true }),
    ]);
    // בינתיים נסגרה הטבלה או נפתחה אחרת - לא מציירים נתונים ישנים
    if (tableId !== currentOpenTableId) return;
    customTableColumnsCache = colsRes.data || [];
    customTableRowsCache = rowsRes.data || [];
    bagRowCounts[tableId] = customTableRowsCache.length;
    // מה מהשורות כבר ברשימת הקניות (עמודת ✓ מחוברת - ר' tblLoadShopItems ב-tables.js)
    await tblLoadShopItems();
    if (tableId !== currentOpenTableId) return;
    renderTableViewHead();
    renderTableGrid();
}

// --- ניהול עמודות - בדיוק כמו saveVisionGoal (יעד+תחנות): רשימה זמנית
// בזיכרון (pendingTableColumns) שמתעדכנת חופשי בזמן שהמודל פתוח, ומתיישבת
// מול ה-DB רק בלחיצה על שמירה (diff מול originalTableColumnIds - מה שהיה
// ונעלם נמחק, מה שנשאר מתעדכן, מה שחדש נוסף) - לא כתיבה מיידית לכל שינוי
let pendingTableColumns = [];
let originalTableColumnIds = [];
let editingCustomColumnId = null; // אינדקס בתוך pendingTableColumns, null = חדשה
const TABLE_COLUMN_TYPES = ['text', 'number', 'select', 'date', 'checkbox'];
// אפשרויות-הבחירה של עמודת select שכרגע פתוחה במודל-המשני - לכל אפשרות id
// מקומי (crypto.randomUUID, לא תלוי-DB), label וצבע. תא שבוחר ערך שומר את
// ה-id, לא את הטקסט - כך ששינוי שם/צבע מאוחר יותר משפיע אוטומטית על כל
// התאים שכבר משתמשים באפשרות הזו (ר' buildSelectCell)
let pendingSelectOptions = [];
const TABLE_SELECT_OPTION_COLOR_PRESETS = ['#ff453a', '#f5c518', '#34d399', '#22d3ee', '#3b82f6', '#a855f7', '#ff2d95'];
// שם-צבע -> הקסדצימלי, אותו סדר בדיוק כמו TABLE_SELECT_OPTION_COLOR_PRESETS -
// ה-AI (parse-table-request) מחזיר שם-צבע מתוך enum קבוע, לא הקס, כדי שלא
// יצטרך "לנחש" גוונים ותמיד ייצא בדיוק אחד מהצבעים שכבר קיימים בבורר הידני
const TABLE_AI_COLOR_NAME_MAP = { red: '#ff453a', yellow: '#f5c518', green: '#34d399', cyan: '#22d3ee', blue: '#3b82f6', purple: '#a855f7', pink: '#ff2d95' };

function openColumnManager() {
    pendingTableColumns = customTableColumnsCache.map(col => ({ ...col }));
    originalTableColumnIds = pendingTableColumns.filter(c => c.id).map(c => c.id);
    renderPendingTableColumns();
    initTableColumnDragReorder();
    const hint = document.getElementById('ai-review-columns-hint');
    if (hint) hint.classList.add('hidden');
    openModal('modal-manage-columns');
}

// --- בניית טבלה עם AI - "טאב" בתוך ה-AI Brain הכללי (modal-ai-brain, לא
// מודל נפרד) לפי בקשה מפורשת ("שיהיה קשור לרובוט/מוח"), אותו דפוס בדיוק
// כמו טאב הלו"ז (parseScheduleWithAI/attemptScheduleParse) - ללא נפילה
// מקומית (אין תחליף הגיוני ל-AI כאן, בניגוד ללו"ז/טקסט-אוכל). תוצאת ה-AI
// אף פעם לא נכתבת ישירות ל-DB - נטענת לתוך אותה זרימת עריכה ידנית בדיוק
// (modal-add-table -> modal-manage-columns) כדי שטעות של ה-AI תהיה זולה
// לתקן בדיוק כמו טעות ידנית (ר' scan-recipe-image, שאותו עיקרון
// בדיוק - "הטופס נשאר ניתן לעריכה כי אף מודל לא מושלם")
let aiTableBuilderReviewActive = false;

function resetAiTableBuilderState() {
    aiTableBuilderReviewActive = false;
}

function cancelAddTableModal() {
    closeModal('modal-add-table');
    resetAiTableBuilderState();
}
function cancelColumnManager() {
    closeModal('modal-manage-columns');
    // בזרימת ה-AI, saveCustomTable כבר יצרה את שורת custom_tables בפועל לפני
    // שהגענו לכאן (כדי לקבל id אמיתי ולהמשיך אוטומטית לעורך העמודות) - אם
    // מבטלים כאן בלי לשמור אף עמודה, הטבלה הזו נשארת "רפאים" ריקה ב-DB
    // לצמיתות בלי שום דרך לדעת למה היא שם. במסלול הידני אין בעיה מקבילה -
    // saveCustomTable לא פותחת את עורך העמודות אוטומטית שם בכלל
    if (aiTableBuilderReviewActive && currentOpenTableId) {
        const orphanTableId = currentOpenTableId;
        currentOpenTableId = null;
        supabaseClient.from('custom_tables').delete().eq('id', orphanTableId).then(({ error }) => {
            if (error) return;
            customTablesCache = customTablesCache.filter(tbl => tbl.id !== orphanTableId);
            renderNotebookShelves();
        });
    }
    resetAiTableBuilderState();
}

// כמו openColumnManager, אבל לא מאפסת pendingTableColumns מ-customTableColumnsCache
// (אין עדיין שום דבר ב-DB - הטבלה הזו נוצרה הרגע) - פשוט מציגה את מה ש-
// applyAiTableBuilderResult כבר הכין, באותו עורך-עמודות בדיוק (גרירה/עריכה/
// מחיקה/הוספה, הכל זהה לחלוטין לזרימה הידנית)
function openColumnManagerForAiReview() {
    originalTableColumnIds = [];
    renderPendingTableColumns();
    initTableColumnDragReorder();
    const hint = document.getElementById('ai-review-columns-hint');
    if (hint) hint.classList.remove('hidden');
    openModal('modal-manage-columns');
}

async function attemptTableAiRequest(token, description) {
    try {
        const res = await fetch(`${SUPABASE_URL}/functions/v1/parse-table-request`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
            body: JSON.stringify({ description })
        });
        const result = await res.json();
        if (res.status === 402 || result.error === 'limit_reached') return { status: 'limit', scope: result.scope };
        if (res.ok && !result.error && result.table) return { status: 'ok', table: result.table };
        return { status: 'retry' };
    } catch {
        return { status: 'retry' };
    }
}

// ממפה את מבנה-הטבלה שה-AI הציע לתוך pendingTableColumns - אותה צורה
// בדיוק ש-openColumnManager כבר יודעת להציג, כדי לא לבנות שום UI חדש.
// בכוונה לא ממלא שום שורה - דווח בפועל שמשתמשת לא רצתה שה-AI "ימלא לה
// הכל בסתם דברים", רק שייצור את המבנה והיא תמלא בעצמה את הנתונים האמיתיים
function applyAiTableBuilderResult(table) {
    pendingTableColumns = (table.columns || []).map((col, index) => {
        let selectOptions = null;
        if (col.type === 'select' && Array.isArray(col.select_options)) {
            selectOptions = col.select_options
                .filter(opt => opt && opt.label && opt.label.trim())
                .map(opt => ({ id: crypto.randomUUID(), label: opt.label.trim(), color: TABLE_AI_COLOR_NAME_MAP[opt.color] || TABLE_SELECT_OPTION_COLOR_PRESETS[0] }));
        }
        return { id: null, name: (col.name || '').trim() || t('table_column_type_text'), type: TABLE_COLUMN_TYPES.includes(col.type) ? col.type : 'text', select_options: selectOptions, sort_order: (index + 1) * 10 };
    });

    aiTableBuilderReviewActive = true;
    editingCustomTableId = null;
    selectedTableIcon = /\p{Emoji}/u.test(table.table_icon || '') ? table.table_icon : TABLE_ICON_PRESETS[0];
    // כותרת ייעודית (לא הכותרת הגנרית "טבלה חדשה") - דווח בפועל שמשתמשת ראתה
    // רק את ה-toast "מוכן" והניחה שהטבלה כבר נשמרה, בלי לשים לב שנפתח מסך
    // שדורש בעצמו לחיצה על "הוספה" (ואז "שמירה" במסך העמודות) כדי שזה
    // באמת יישמר - הכותרת הגנרית לא רמזה בכלל שזו תוצאת ה-AI שממתינה לאישור
    document.getElementById('table-modal-title').textContent = t('table_ai_review_title');
    document.getElementById('btn-save-table').textContent = t('add_btn');
    document.getElementById('table-name-input').value = (table.table_name || '').trim();
    renderTableIconPicker();
    // כמו טבלה ידנית: לכיס שממנו נפתח ה-AI (מתוך התיק), אחרת לכיס הראשון
    bagPrepareTablePocketField(bagPendingPocketId, false);
    document.getElementById('table-delete-btn').classList.add('hidden');
    closeModal('modal-ai-brain');
    openModal('modal-add-table');
    showAppToast(t('ai_table_builder_ready'));
}

async function buildTableWithAI() {
    // הטאב הזה חי בתוך modal-ai-brain הכללי, שנגיש גם *מחוץ* למסך הטבלאות
    // (למשל הבועה הגלובלית) - שם אין נעילת-פרימיום כלל ברמת הפתיחה (ר'
    // openAiBrainModal), אז חייבים לבדוק כאן במפורש, לא לסמוך על
    // openTablesSection לשמור על השער היחיד
    if (!isPremiumUser) { closeModal('modal-ai-brain'); openPremiumUpgradeModal(); return; }
    if (!isPremiumUser && cachedTableAiLifetimeUsed >= TABLE_AI_FREE_LIFETIME_LIMIT) {
        showAppToast(t('ai_free_lifetime_limit_toast').replace('{feature}', t('feature_name_table_ai')), 'error');
        openPremiumUpgradeModal();
        return;
    }
    const input = document.getElementById('ai-table-input');
    const description = input.value.trim();
    if (!description) { showAppToast(t('ai_table_builder_empty'), 'error'); return; }
    if (!supabaseClient || !currentUserId) { showAppToast(t('error_not_connected'), 'error'); return; }

    const submitBtn = document.getElementById('btn-table-ai-build');
    if (submitBtn && submitBtn.disabled) return;
    if (submitBtn) submitBtn.disabled = true;
    const loadingEl = document.getElementById('table-ai-loading');
    const loadingTimer = setTimeout(() => { if (loadingEl) loadingEl.classList.remove('hidden'); }, 5000);
    try {
        const { data: sessionData } = await supabaseClient.auth.getSession();
        const token = sessionData && sessionData.session ? sessionData.session.access_token : null;
        if (!token) { showAppToast(t('error_not_connected'), 'error'); return; }

        let attempt = await attemptTableAiRequest(token, description);
        if (attempt.status === 'retry') attempt = await attemptTableAiRequest(token, description);

        if (attempt.status === 'limit') {
            if (attempt.scope === 'free_lifetime') {
                showAppToast(t('ai_free_lifetime_limit_toast').replace('{feature}', t('feature_name_table_ai')), 'error');
                openPremiumUpgradeModal();
            } else {
                showAppToast(t('ai_monthly_limit_reached'), 'error');
            }
            return;
        }
        if (attempt.status !== 'ok') { showAppToast(t('ai_table_builder_failed'), 'error'); return; }

        await loadAiUsage();
        applyAiTableBuilderResult(attempt.table);
    } finally {
        clearTimeout(loadingTimer);
        if (loadingEl) loadingEl.classList.add('hidden');
        if (submitBtn) submitBtn.disabled = false;
    }
}

function renderPendingTableColumns() {
    const list = document.getElementById('pending-columns-list');
    if (!list) return;
    list.innerHTML = '';
    pendingTableColumns.forEach((col, index) => {
        const row = document.createElement('div');
        row.className = 'pending-column-row';
        row.setAttribute('data-pending-index', index);
        row.innerHTML = `
            <span class="column-drag-handle">⠿</span>
            <span class="pending-column-name">${escapeHtmlForReport(col.name)}</span>
            <span class="pending-column-type-badge">${t('table_column_type_' + col.type)}</span>
            <button type="button" class="btn-edit-item" onclick="openEditColumnSubModal(${index})">${EDIT_ICON_SVG}</button>
            <button type="button" class="btn-delete-item" onclick="removePendingTableColumn(${index})">❌</button>
        `;
        list.appendChild(row);
    });
}

// גרירה-לסידור-מחדש רק בתוך pendingTableColumns (בזיכרון) - לא כותבת ל-DB
// באופן מיידי כמו initFinanceCategoryDragReorder, כי כאן יש שלב "שמירה" נפרד
// (ר' ההערה על pendingTableColumns למעלה) - הסדר האמיתי נכתב רק ב-
// saveTableColumns. אחרי גרירה מרנדרים מחדש כדי שה-onclick המקודדים לפי
// אינדקס (openEditColumnSubModal(index) וכו') יתאימו לסדר החדש
let tableColumnsSortableInitialized = false;
function initTableColumnDragReorder() {
    if (typeof Sortable === 'undefined' || tableColumnsSortableInitialized) return;
    const list = document.getElementById('pending-columns-list');
    if (!list) return;
    tableColumnsSortableInitialized = true;
    new Sortable(list, {
        handle: '.column-drag-handle',
        animation: 150,
        forceFallback: true,
        fallbackOnBody: false,
        dragoverBubble: false,
        ghostClass: 'sortable-ghost',
        chosenClass: 'sortable-chosen',
        onEnd: () => {
            const newOrder = Array.from(list.children).map(el => parseInt(el.getAttribute('data-pending-index'), 10));
            pendingTableColumns = newOrder.map(i => pendingTableColumns[i]);
            renderPendingTableColumns();
        },
    });
}

function openAddColumnSubModal() {
    editingCustomColumnId = null;
    document.getElementById('column-name-input').value = '';
    pendingSelectOptions = [];
    document.getElementById('column-shop-link-toggle').checked = false;
    selectColumnType('text');
    renderPendingSelectOptionsList();
    openModal('modal-add-column');
    setTimeout(() => document.getElementById('column-name-input').focus(), 150);
}

function openEditColumnSubModal(index) {
    const col = pendingTableColumns[index];
    if (!col) return;
    editingCustomColumnId = index;
    document.getElementById('column-name-input').value = col.name;
    // עותק עמוק-מספיק - כדי שעריכת האפשרויות במודל לא תשנה את pendingTableColumns
    // עד שממש לוחצים "שמירה" (ואם לוחצים "ביטול", pendingTableColumns נשאר נקי)
    pendingSelectOptions = (col.select_options || []).map(opt => ({ ...opt }));
    document.getElementById('column-shop-link-toggle').checked = tblIsShopCol(col);
    selectColumnType(col.type);
    renderPendingSelectOptionsList();
    openModal('modal-add-column');
}

function selectColumnType(type) {
    document.querySelectorAll('#column-type-picker .table-column-type-chip').forEach(chip => {
        chip.classList.toggle('selected', chip.getAttribute('data-type') === type);
    });
    document.getElementById('column-type-picker').setAttribute('data-selected-type', type);
    const optionsEditor = document.getElementById('column-select-options-editor');
    if (optionsEditor) optionsEditor.classList.toggle('hidden', type !== 'select');
    const shopRow = document.getElementById('column-shop-link-row');
    if (shopRow) shopRow.classList.toggle('hidden', type !== 'checkbox');
}

function addPendingSelectOption() {
    const color = TABLE_SELECT_OPTION_COLOR_PRESETS[pendingSelectOptions.length % TABLE_SELECT_OPTION_COLOR_PRESETS.length];
    pendingSelectOptions.push({ id: crypto.randomUUID(), label: '', color });
    renderPendingSelectOptionsList();
}
function removePendingSelectOption(index) {
    pendingSelectOptions.splice(index, 1);
    renderPendingSelectOptionsList();
}
function selectPendingOptionColor(index, color) {
    if (pendingSelectOptions[index]) pendingSelectOptions[index].color = color;
    renderPendingSelectOptionsList();
}
function updatePendingOptionLabel(index, label) {
    if (pendingSelectOptions[index]) pendingSelectOptions[index].label = label;
}

function renderPendingSelectOptionsList() {
    const list = document.getElementById('pending-select-options-list');
    if (!list) return;
    list.innerHTML = '';
    pendingSelectOptions.forEach((opt, index) => {
        const row = document.createElement('div');
        row.className = 'pending-select-option-row';
        const input = document.createElement('input');
        input.type = 'text';
        input.value = opt.label;
        input.placeholder = t('table_column_option_placeholder');
        input.oninput = () => updatePendingOptionLabel(index, input.value);
        row.appendChild(input);
        const swatchRow = document.createElement('div');
        swatchRow.className = 'pending-select-option-swatches';
        TABLE_SELECT_OPTION_COLOR_PRESETS.forEach(color => {
            const swatch = document.createElement('button');
            swatch.type = 'button';
            swatch.className = 'note-color-swatch' + (opt.color === color ? ' selected' : '');
            swatch.style.backgroundColor = color;
            swatch.onclick = () => selectPendingOptionColor(index, color);
            swatchRow.appendChild(swatch);
        });
        row.appendChild(swatchRow);
        const removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'btn-delete-item';
        removeBtn.textContent = '❌';
        removeBtn.onclick = () => removePendingSelectOption(index);
        row.appendChild(removeBtn);
        list.appendChild(row);
    });
}

// שמירת עמודה בודדת בתוך המודל-המשני - כותבת רק לתוך pendingTableColumns
// (לא ל-DB), סוגרת את המודל-המשני וחוזרת למודל הראשי (openModal סוגרת אוטומטית
// כל .apple-modal.open אחר, אז חוזרים אליו ידנית) - השמירה בפועל ל-DB קורית
// רק ב-saveTableColumns כשלוחצים "שמירה" על כל רשימת העמודות ביחד
function saveColumnSubModal() {
    const name = document.getElementById('column-name-input').value.trim();
    if (!name) { showAppToast(t('calendar_event_missing_fields'), 'error'); return; }
    const type = document.getElementById('column-type-picker').getAttribute('data-selected-type') || 'text';
    let selectOptions = null;
    if (type === 'select') {
        selectOptions = pendingSelectOptions.filter(opt => opt.label.trim()).map(opt => ({ ...opt, label: opt.label.trim() }));
        if (selectOptions.length === 0) { showAppToast(t('table_column_needs_option_error'), 'error'); return; }
    }
    const shopLink = type === 'checkbox' ? document.getElementById('column-shop-link-toggle').checked : null;
    if (editingCustomColumnId !== null) {
        const existing = pendingTableColumns[editingCustomColumnId];
        pendingTableColumns[editingCustomColumnId] = { ...existing, name, type, select_options: selectOptions, shop_link: shopLink };
    } else {
        pendingTableColumns.push({ id: null, name, type, select_options: selectOptions, shop_link: shopLink, sort_order: (pendingTableColumns.length + 1) * 10 });
    }
    closeModal('modal-add-column');
    editingCustomColumnId = null;
    // "+ עמודה" מתוך הטבלה (tables.js): נשמר מיד, בלי לחזור לרשימת העמודות
    if (tblQuickColumn) { tblQuickColumn = false; saveTableColumns(); return; }
    renderPendingTableColumns();
    openModal('modal-manage-columns');
}

// מחיקה עם אזהרה רק אם לעמודה כבר יש id אמיתי (כלומר כבר קיימת ב-DB ועלולה
// להחזיק נתוני-תא אמיתיים בשורות) - עמודה חדשה שעוד לא נשמרה (id===null)
// נמחקת מיד בלי אזהרה, אין לה שום נתון לאבד
function removePendingTableColumn(index) {
    const col = pendingTableColumns[index];
    if (col && col.id) {
        showDangerConfirm(t('table_column_delete_title'), t('table_column_delete_confirm'), () => {
            pendingTableColumns.splice(index, 1);
            renderPendingTableColumns();
        });
    } else {
        pendingTableColumns.splice(index, 1);
        renderPendingTableColumns();
    }
}

let saveTableColumnsInFlight = false;
async function saveTableColumns() {
    if (saveTableColumnsInFlight) return;
    saveTableColumnsInFlight = true;
    try {
        await saveTableColumnsImpl();
    } finally {
        saveTableColumnsInFlight = false;
    }
}
async function saveTableColumnsImpl() {
    if (!supabaseClient || !currentUserId || !currentOpenTableId) return;
    const keptIds = pendingTableColumns.filter(c => c.id).map(c => c.id);
    const toDelete = originalTableColumnIds.filter(id => !keptIds.includes(id));
    if (toDelete.length) await supabaseClient.from('custom_table_columns').delete().in('id', toDelete);
    for (let i = 0; i < pendingTableColumns.length; i++) {
        const col = pendingTableColumns[i];
        const sortOrder = (i + 1) * 10;
        // shop_link: רק לעמודת ✓; עמודה שלא נגעו בה נשארת ריקה (= לפי השם, ר' tblIsShopCol)
        const shopLink = col.type === 'checkbox' && typeof col.shop_link === 'boolean' ? col.shop_link : null;
        if (col.id) {
            await supabaseClient.from('custom_table_columns').update({ name: col.name, type: col.type, select_options: col.select_options || null, shop_link: shopLink, sort_order: sortOrder }).eq('id', col.id);
        } else {
            await supabaseClient.from('custom_table_columns').insert({ table_id: currentOpenTableId, user_id: currentUserId, name: col.name, type: col.type, select_options: col.select_options || null, shop_link: shopLink, sort_order: sortOrder });
        }
    }
    aiTableBuilderReviewActive = false;
    closeModal('modal-manage-columns');
    // טבלה שה-AI בנה (אפשר גם מחוץ לתיק) נפתחת עכשיו במסך מלא; טבלה פתוחה רק מתרעננת
    if (isTableViewOpen()) await loadTableColumnsAndRows(currentOpenTableId);
    else await openTableView(currentOpenTableId);
    showAppToast(t('item_added_success'));
}

// התצוגות של טבלה פתוחה (טבלה / כרטיסים / לוח), כרטיס השורה, המיון והסינון - ב-tables.js. כאן רק
// התווית של תאריך ושמירת ערך של תא
// בודקת בעצמה שהערך הוא באמת מחרוזת YYYY-MM-DD תקנית לפני שמנסים לפרסר - עמודה יכולה להתחלף בדיעבד
// לסוג date אחרי ששורות כבר החזיקו ערך מסוג אחר תחת אותו column.id (למשל מספר/בוליאני)
function formatTableDateCellLabel(dateStr) {
    if (typeof dateStr !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return '—';
    const [y, m, d] = dateStr.split('-').map(Number);
    return new Date(y, m - 1, d).toLocaleDateString(currentLang, { day: 'numeric', month: 'short', year: 'numeric' });
}

// קריאה-מיזוג-כתיבה על כל אובייקט ה-data של השורה - אין טבלה רביעית פר-תא (ר' ההערה בסכימה), כל עדכון
// תא שולח מחדש את כל האובייקט עם המפתח הבודד שהשתנה. ה-cache מתעדכן מקומית בלי טעינה מחדש
async function updateCellValue(rowId, columnId, value) {
    const row = customTableRowsCache.find(r => r.id === rowId);
    if (!row) return;
    const newData = { ...(row.data || {}), [columnId]: value };
    const { error } = await supabaseClient.from('custom_table_rows').update({ data: newData, updated_at: new Date().toISOString() }).eq('id', rowId);
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    row.data = newData;
}

// --- 📓 המחברות שלי (לפי בקשה מפורשת, במקום "לימודים" ו"הפרויקטים שלי"): ארון עם מדפים - כל מדף הוא
// פרויקט (projects) ועליו המחברות שלו (project_notebooks) בכריכות שבוחרים: צבע, דוגמה ומדבקה. על המדף
// העליון קבועה מחברת "📝 משימות" (study_tasks - שיעורי הבית של פעם, חינם לכולם). מחברות משלך -
// פרימיום, כמו "הפרויקטים שלי" קודם. מחברת נפתחת במסך מלא (#nb-view) כמחברת אמיתית: דף אחד בכל פעם
// שמתהפך (חצים או החלקה), סוגי דף (שורות / משבצות / חלק / רשימה), סימנייה (bookmark_page_id - המחברת
// נפתחת שם) ותוכן עניינים עם חיפוש ---
const NB_COVER_COLORS = ['#ef8a80', '#f6b26b', '#f3d36b', '#9ccc9c', '#7fd1c1', '#8ab4f8', '#b39ddb', '#f48fb1'];
const NB_COVER_PATTERNS = ['plain', 'dots', 'stripes', 'grid', 'gingham'];
const NB_COVER_EMOJIS = ['📓', '📚', '✏️', '🧮', '🔬', '🎨', '🎵', '💼', '🌍', '💡', '🌸', '⭐', '❤️', '📈'];
const NB_PAGE_TYPES = ['write', 'grid', 'draw', 'list'];
const NB_PAGE_TYPE_ICONS = { write: '📝', grid: '▦', draw: '✏️', list: '☑️' };
const NB_NEW_SHELF = '__new__';
const NB_TURN_MS = 420;
let allNotebooksCache = [];
let nbViewMode = null;      // 'notebook' | 'tasks' | null (סגור)
let nbCoverDraft = null;    // הכריכה שנערכת בחלון הכריכה

function nbSortByOrder(a, b) {
    const ao = a.sort_order == null ? Infinity : a.sort_order;
    const bo = b.sort_order == null ? Infinity : b.sort_order;
    if (ao !== bo) return ao - bo;
    return String(a.created_at || '').localeCompare(String(b.created_at || ''));
}
// מחברת בלי צבע שמור (נוצרה לפני הכריכות) מקבלת צבע קבוע לפי המיקום שלה בארון
function nbCoverColor(nb) {
    if (nb && nb.cover_color) return nb.cover_color;
    const idx = Math.max(0, allNotebooksCache.indexOf(nb));
    return NB_COVER_COLORS[idx % NB_COVER_COLORS.length];
}
function nbCoverPattern(nb) {
    return nb && NB_COVER_PATTERNS.includes(nb.cover_pattern) ? nb.cover_pattern : 'plain';
}

function isNotebooksSectionOpen() {
    const section = document.getElementById('notebooks-section');
    return !!(section && section.classList.contains('active-tab'));
}
// המסך עצמו (התיק, הכיסים, הקלסר והטעינה) ב-bag.js: openNotebooksSection / loadNotebooksHome / renderBag.
// שמות ישנים (מגירת "לימודים" ו"הפרויקטים שלי" שהוחלפו) - מובילים לתיק
function openStudyDrawer() { openNotebooksSection(); }
function openMyProjectsEntry() { openNotebooksSection(); }
function loadProjects() { return loadNotebooksHome(); }

function nbCoverInnerHtml(emoji, title) {
    return `<span class="nb-cover-emoji">${escapeHtmlForReport(emoji)}</span><span class="nb-cover-label">${escapeHtmlForReport(title)}</span>`;
}
function buildNotebookCover(nb) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = `nb-cover nb-pat-${nbCoverPattern(nb)}`;
    btn.dataset.notebookId = nb.id;
    btn.style.setProperty('--nb-color', nbCoverColor(nb));
    btn.innerHTML = nbCoverInnerHtml(nb.cover_emoji || '📓', nb.title) + (nb.bookmark_page_id ? '<span class="nb-cover-ribbon" aria-hidden="true"></span>' : '');
    btn.title = nb.title;
    btn.onclick = () => openNotebookView(nb.id);
    return btn;
}

// --- המחברת הפתוחה (#nb-view) ---
function setNotebookViewOpen(open) {
    const view = document.getElementById('nb-view');
    if (!view) return;
    view.classList.toggle('open', open);
    view.setAttribute('aria-hidden', open ? 'false' : 'true');
    const wrapper = document.querySelector('.phone-wrapper');
    if (wrapper) wrapper.classList.toggle('projects-open', open);
}
function isNotebookViewOpen() {
    const view = document.getElementById('nb-view');
    return !!(view && view.classList.contains('open'));
}

function openTasksNotebook() {
    const view = document.getElementById('nb-view');
    if (!view) return;
    // משימה שמוסיפים מכאן היא "משימה כללית" - לא נכנסת לכיס שנפתח קודם
    bagPendingPocketId = null;
    nbViewMode = 'tasks';
    view.classList.add('is-tasks');
    view.classList.remove('is-notebook');
    document.getElementById('nb-view-emoji').textContent = '📝';
    document.getElementById('nb-view-name').textContent = t('nb_tasks_notebook_title');
    document.getElementById('nb-view-crumb').textContent = t('study_title');
    const sheet = document.getElementById('nb-sheet');
    sheet.dataset.paper = 'list';
    sheet.style.removeProperty('--nb-color');
    document.getElementById('nb-page-ribbon').classList.add('hidden');
    setNotebookViewOpen(true);
    renderStudyTasksList();
    loadStudyTasks();
}

async function openNotebookView(notebookId) {
    if (!isPremiumUser) { openPremiumUpgradeModal(); return; }
    const nb = allNotebooksCache.find(n => n.id === notebookId);
    const view = document.getElementById('nb-view');
    if (!nb || !view) return;
    nbViewMode = 'notebook';
    currentOpenNotebookId = notebookId;
    currentOpenProjectId = nb.project_id;
    currentOpenPageId = null;
    view.classList.add('is-notebook');
    view.classList.remove('is-tasks');
    renderNotebookViewTitle();
    notebookPagesCache = [];
    notebookItemsCache = [];
    notebookAllItemsCache = [];
    renderPageNavHeader();
    setNotebookViewOpen(true);
    initNotebookSwipe();
    await loadNotebookPages(notebookId);
    if (currentOpenNotebookId !== notebookId || !isNotebookViewOpen()) return;
    const startId = nb.bookmark_page_id && notebookPagesCache.some(p => p.id === nb.bookmark_page_id) ? nb.bookmark_page_id : (notebookPagesCache[0] && notebookPagesCache[0].id);
    if (startId) openNotebookPage(startId);
}
function openNotebookDetail(notebookId) { openNotebookView(notebookId); }

// הכותרת: האימוג'י והשם של המחברת, ומעליהם הדרך אליה ("התיק שלי › 👨‍👩‍👧 המשפחה"); צבע הכריכה צובע
// את קו השוליים של הנייר
function renderNotebookViewTitle() {
    const nb = allNotebooksCache.find(n => n.id === currentOpenNotebookId);
    document.getElementById('nb-view-emoji').textContent = nb ? (nb.cover_emoji || '📓') : '';
    document.getElementById('nb-view-name').textContent = nb ? nb.title : '';
    const pocket = nb ? bagPocket(nb.project_id) : null;
    document.getElementById('nb-view-crumb').textContent = pocket ? `${t('study_title')} › ${bagPocketLabel(pocket)}` : t('study_title');
    const sheet = document.getElementById('nb-sheet');
    if (sheet && nb) sheet.style.setProperty('--nb-color', nbCoverColor(nb));
}

function closeNotebookView() {
    closeNbPops();
    if (nbViewMode === 'notebook') {
        flushNotebookTextSave();
        // מספר הדפים שמוצג בתיק ובקלסר
        if (currentOpenNotebookId) bagPageCounts[currentOpenNotebookId] = notebookPagesCache.length;
    }
    setNotebookViewOpen(false);
    nbViewMode = null;
    renderNotebookShelves();
}
function closeNotebookDetailDrawer() { closeNotebookView(); }

// טקסט שעוד לא נשמר (השמירה מחכה 800ms אחרי ההקלדה) נשמר מיד כשעוברים דף או סוגרים את המחברת
function flushNotebookTextSave() {
    if (!notebookTextSaveDebounceTimer) return;
    clearTimeout(notebookTextSaveDebounceTimer);
    notebookTextSaveDebounceTimer = null;
    saveNotebookTextContent();
}

// טוענת את כל הדפים של המחברת + (לחיפוש בתוכן העניינים) את כל השורות מכל הדפים - שאילתה אחת, לא
// פר-דף. מחברת בלי אף דף (לא אמור לקרות - מחברת חדשה נוצרת עם דף ראשון) מקבלת "דף 1" ריק עם שורות
async function loadNotebookPages(notebookId) {
    if (!supabaseClient || !currentUserId || !notebookId) return;
    const { data, error } = await supabaseClient.from('notebook_pages').select('*').eq('notebook_id', notebookId).eq('user_id', currentUserId).order('sort_order', { ascending: true });
    if (error) return;
    notebookPagesCache = data || [];
    if (!notebookPagesCache.length) {
        const { data: created } = await supabaseClient.from('notebook_pages').insert({ notebook_id: notebookId, user_id: currentUserId, username: currentUsername, title: `${t('notebook_page_default_title')} 1`, sort_order: 0, canvas_data: [], page_type: 'write', text_content: '' }).select().maybeSingle();
        if (created) notebookPagesCache = [created];
    }
    if (notebookPagesCache.length) {
        const { data: itemsData } = await supabaseClient.from('notebook_items').select('*').eq('user_id', currentUserId).in('page_id', notebookPagesCache.map(p => p.id));
        notebookAllItemsCache = itemsData || [];
    } else {
        notebookAllItemsCache = [];
    }
}

// פותחת דף: סוג הדף קובע את הנייר ומה מוצג - שורות = טקסט חופשי, רשימה = שורות לסימון ✓,
// חלק / משבצות = קנבס ציור (שקוף, הנייר נראה דרכו). שורות ישנות שנכתבו בדף מסוג אחר (לפני סוגי
// הדפים) עדיין מוצגות בו, כדי ששום דבר לא ייעלם
function openNotebookPage(pageId) {
    const page = notebookPagesCache.find(p => p.id === pageId);
    if (!page) return;
    if (currentOpenPageId && currentOpenPageId !== pageId) flushNotebookTextSave();
    currentOpenPageId = pageId;
    canvasStrokes = Array.isArray(page.canvas_data) ? page.canvas_data.slice() : [];
    const type = NB_PAGE_TYPES.includes(page.page_type) ? page.page_type : 'draw';
    document.getElementById('nb-sheet').dataset.paper = type;
    const textEl = document.getElementById('notebook-page-text-content');
    textEl.classList.toggle('hidden', type !== 'write');
    if (type === 'write') textEl.value = page.text_content || '';
    document.getElementById('nb-list-add').classList.toggle('hidden', type !== 'list');
    const isCanvas = type === 'draw' || type === 'grid';
    document.getElementById('notebook-canvas-section-body').classList.toggle('hidden', !isCanvas);
    closeNbPops();
    const dot = document.getElementById('nb-tools-dot');
    if (dot) dot.style.background = penColor;
    const dateEl = document.getElementById('nb-page-date');
    if (dateEl) dateEl.textContent = nbPageDateLabel(page);
    notebookItemsCache = notebookAllItemsCache.filter(i => i.page_id === pageId).sort((a, b) => String(a.created_at || '').localeCompare(String(b.created_at || '')));
    renderNotebookItemsList();
    loadNotebookItems(pageId);
    if (isCanvas) initNotebookCanvas();
    renderPageNavHeader();
    renderPageTabsList();
    renderNotebookBookmarkState();
    const body = document.querySelector('#nb-sheet .nb-page-body');
    if (body) body.scrollTop = 0;
}

function renderPageNavHeader() {
    const idx = notebookPagesCache.findIndex(p => p.id === currentOpenPageId);
    const page = notebookPagesCache[idx];
    const titleEl = document.getElementById('notebook-page-title-text');
    if (titleEl) titleEl.textContent = page ? page.title : '';
    const counterEl = document.getElementById('notebook-page-counter');
    if (counterEl) counterEl.textContent = idx === -1 ? '' : nbPageCounterLabel(idx);
    nbRenderStrip();
}
function nbPageCounterLabel(idx) {
    return t('notebook_page_counter_label').replace('{current}', (idx + 1).toLocaleString(currentLang)).replace('{total}', notebookPagesCache.length.toLocaleString(currentLang));
}

// התאריך שבו הדף נפתח, ליד הכותרת שלו ("יום ב׳ · 5 באוק׳"); שנה רק כשזו לא השנה הנוכחית
function nbPageDateLabel(page) {
    const d = page && page.created_at ? new Date(page.created_at) : null;
    if (!d || isNaN(d.getTime())) return '';
    try {
        const sameYear = d.getFullYear() === new Date().getFullYear();
        const day = d.toLocaleDateString(currentLang, sameYear ? { day: 'numeric', month: 'short' } : { day: 'numeric', month: 'short', year: 'numeric' });
        return `${d.toLocaleDateString(currentLang, { weekday: 'short' })} · ${day}`;
    } catch (e) { return ''; }
}

// --- פס הדפים בתחתית: דף קטן לכל דף - הנייר לפי הסוג, ועליו מה שבאמת יש בדף (שורות הטקסט, שורות הרשימה
// עם ✓, או הציור עצמו בקטן). נבנה מחדש רק כשרשימת הדפים משתנה; במעבר דף רק הדף הנוכחי מתחלף ---
let nbStripSig = '';
function nbRenderStrip(force) {
    const strip = document.getElementById('nb-strip');
    if (!strip) return;
    const nb = allNotebooksCache.find(n => n.id === currentOpenNotebookId);
    const mark = nb ? nb.bookmark_page_id || '' : '';
    const sig = (currentOpenNotebookId || '') + '#' + mark + '#' + currentLang + '#' + notebookPagesCache.map(p => `${p.id}:${p.page_type}:${p.title}`).join('|');
    if (force || sig !== nbStripSig) {
        nbStripSig = sig;
        strip.innerHTML = '';
        notebookPagesCache.forEach((page, idx) => strip.appendChild(nbBuildThumb(page, idx, page.id === mark)));
    }
    strip.querySelectorAll('.nb-thumb').forEach(b => {
        const on = b.dataset.pageId === currentOpenPageId;
        b.classList.toggle('is-current', on);
        if (on) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current');
    });
    nbScrollStripToCurrent();
}
function nbBuildThumb(page, idx, marked) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'nb-thumb';
    btn.dataset.pageId = page.id;
    btn.dataset.paper = NB_PAGE_TYPES.includes(page.page_type) ? page.page_type : 'draw';
    const label = `${nbPageCounterLabel(idx)} – ${page.title}`;
    btn.title = page.title;
    btn.setAttribute('aria-label', label);
    const canvas = document.createElement('canvas');
    canvas.className = 'nb-thumb-ink';
    canvas.setAttribute('aria-hidden', 'true');
    btn.appendChild(canvas);
    if (marked) {
        const ribbon = document.createElement('span');
        ribbon.className = 'nb-thumb-mark';
        ribbon.setAttribute('aria-hidden', 'true');
        btn.appendChild(ribbon);
    }
    btn.onclick = () => nbGoToPage(page.id);
    nbDrawThumb(canvas, page);
    return btn;
}
// מצייר את מה שבדף על קנבס קטן (34×46): קו כותרת קצר למעלה, ואז לפי הסוג - פסי "דיו" לשורות הטקסט,
// קופסה + פס לכל שורה ברשימה (ירוקה כשסומנה), או הקווים והמדבקות של הציור
const NB_THUMB_W = 34, NB_THUMB_H = 46;
function nbDrawThumb(canvas, page) {
    const dpr = Math.min(3, window.devicePixelRatio || 1);
    canvas.width = NB_THUMB_W * dpr;
    canvas.height = NB_THUMB_H * dpr;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, NB_THUMB_W, NB_THUMB_H);
    const ink = 'rgba(34, 32, 28, .55)';
    const type = NB_PAGE_TYPES.includes(page.page_type) ? page.page_type : 'draw';
    const startX = document.documentElement.dir === 'rtl' ? null : 5;
    const bar = (y, w, color) => {
        const width = Math.max(3, Math.min(NB_THUMB_W - 10, w));
        const x = startX === null ? NB_THUMB_W - 5 - width : startX;
        ctx.fillStyle = color || ink;
        ctx.fillRect(x, y, width, 1.4);
    };
    bar(4.5, Math.min(18, 6 + String(page.title || '').length * 1.2), 'rgba(34, 32, 28, .8)');
    const isCurrent = page.id === currentOpenPageId;
    if (type === 'write') {
        const textarea = isCurrent ? document.getElementById('notebook-page-text-content') : null;
        const text = String(textarea ? textarea.value : page.text_content || '');
        const perLine = 22;
        const rows = [];
        text.split('\n').forEach(line => {
            const l = line.trim().length;
            if (!l) { rows.push(0); return; }
            for (let i = 0; i < l; i += perLine) rows.push(Math.min(perLine, l - i));
        });
        rows.slice(0, 7).forEach((len, i) => { if (len) bar(11 + i * 5, len * (24 / perLine)); });
        return;
    }
    if (type === 'list') {
        const items = isCurrent ? notebookItemsCache : notebookAllItemsCache.filter(i => i.page_id === page.id).sort((a, b) => String(a.created_at || '').localeCompare(String(b.created_at || '')));
        items.slice(0, 6).forEach((item, i) => {
            const y = 10 + i * 6;
            const boxX = startX === null ? NB_THUMB_W - 8 : 5;
            if (item.is_completed) { ctx.fillStyle = '#10b981'; ctx.fillRect(boxX, y, 3.4, 3.4); }
            else { ctx.strokeStyle = 'rgba(34, 32, 28, .5)'; ctx.lineWidth = 0.7; ctx.strokeRect(boxX + 0.35, y + 0.35, 2.7, 2.7); }
            const w = Math.min(18, 5 + String(item.title || '').length * 0.9);
            const x = startX === null ? NB_THUMB_W - 10 - w : 10;
            ctx.fillStyle = item.is_completed ? 'rgba(34, 32, 28, .3)' : ink;
            ctx.fillRect(x, y + 1.1, w, 1.3);
        });
        return;
    }
    const saved = isCurrent ? canvasStrokes : page.canvas_data;
    const strokes = Array.isArray(saved) ? saved : [];
    const area = { x: 3, y: 9, w: NB_THUMB_W - 6, h: NB_THUMB_H - 12 };
    const scale = area.w / 320;
    strokes.forEach(entry => {
        if (entry.t === 'emoji') {
            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = 'source-over';
            ctx.font = `${Math.max(5, (entry.size || 32) * scale * 1.3)}px system-ui, "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(entry.ch || '', area.x + entry.x * area.w, area.y + entry.y * area.h);
            return;
        }
        if (!entry.pts || entry.pts.length < 2) return;
        const rp = strokeRenderParams(entry.t);
        ctx.globalCompositeOperation = rp.composite;
        ctx.globalAlpha = rp.alpha;
        ctx.strokeStyle = entry.c || '#000';
        ctx.lineWidth = Math.max(0.5, (entry.w || 3) * scale);
        ctx.lineCap = rp.cap;
        ctx.lineJoin = rp.join;
        ctx.beginPath();
        entry.pts.forEach((p, i) => {
            const x = area.x + p[0] * area.w, y = area.y + p[1] * area.h;
            if (i) ctx.lineTo(x, y); else ctx.moveTo(x, y);
        });
        ctx.stroke();
    });
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
}
// אחרי שמירה (קו, טקסט, שורה ברשימה) הדף הקטן של הדף הפתוח מתעדכן במקום, בלי לבנות את כל הפס מחדש
function nbRefreshThumb(pageId) {
    const page = notebookPagesCache.find(p => p.id === pageId);
    const canvas = page && document.querySelector(`#nb-strip .nb-thumb[data-page-id="${pageId}"] .nb-thumb-ink`);
    if (canvas) nbDrawThumb(canvas, page);
}
function nbScrollStripToCurrent() {
    const strip = document.getElementById('nb-strip');
    const cur = strip && strip.querySelector('.nb-thumb.is-current');
    if (!cur || strip.scrollWidth <= strip.clientWidth) return;
    const s = strip.getBoundingClientRect(), c = cur.getBoundingClientRect();
    strip.scrollBy({ left: (c.left + c.width / 2) - (s.left + s.width / 2), behavior: nbReducedMotion() ? 'auto' : 'smooth' });
}
// מעבר לדף מסוים (מפס הדפים או מתוך תוכן העניינים) - מתהפך קדימה או אחורה לפי המיקום שלו
function nbGoToPage(pageId) {
    const from = notebookPagesCache.findIndex(p => p.id === currentOpenPageId);
    const to = notebookPagesCache.findIndex(p => p.id === pageId);
    if (to === -1 || to === from) return;
    playNotebookPageTurn(to > from ? 'next' : 'prev', () => openNotebookPage(pageId));
}

// היפוך דף: "רוח רפאים" (העתק של הדף הנוכחי, כולל הציור שעל הקנבס) מתהפך סביב הכריכה - קדימה הדף
// הישן מתקפל ומגלה את החדש שמתחתיו; אחורה הדף הקודם חוזר ומתהפך מעל הנוכחי. הכריכה בצד ה-start
// (ימין בעברית, שמאל באנגלית), בדיוק כמו במחברת אמיתית בכל שפה. בלי אנימציה למי שביקש/ה פחות תנועה
function nbReducedMotion() {
    return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}
function playNotebookPageTurn(dir, swap) {
    const sheet = document.getElementById('nb-sheet');
    const book = document.getElementById('nb-book');
    if (!sheet || !book || nbReducedMotion()) { swap(); return; }
    book.querySelectorAll('.nb-sheet-ghost').forEach(g => g.remove());
    sheet.classList.remove('nb-turn-in');
    const ghost = sheet.cloneNode(true);
    ghost.removeAttribute('id');
    ghost.querySelectorAll('[id]').forEach(el => el.removeAttribute('id'));
    ghost.setAttribute('aria-hidden', 'true');
    ghost.classList.add('nb-sheet-ghost');
    const srcCanvas = sheet.querySelector('canvas'), dstCanvas = ghost.querySelector('canvas');
    if (srcCanvas && dstCanvas && srcCanvas.width > 1) {
        dstCanvas.width = srcCanvas.width;
        dstCanvas.height = srcCanvas.height;
        try { dstCanvas.getContext('2d').drawImage(srcCanvas, 0, 0); } catch (e) { /* קנבס ריק - לא נורא */ }
    }
    const srcText = sheet.querySelector('textarea'), dstText = ghost.querySelector('textarea');
    if (srcText && dstText) dstText.value = srcText.value;
    const srcBody = sheet.querySelector('.nb-page-body');
    const scrollTop = srcBody ? srcBody.scrollTop : 0;
    swap();
    if (dir === 'next') {
        ghost.classList.add('nb-turn-out');
        book.appendChild(ghost);
    } else {
        ghost.classList.add('nb-turn-under');
        book.insertBefore(ghost, sheet);
        void sheet.offsetWidth;
        sheet.classList.add('nb-turn-in');
    }
    const ghostBody = ghost.querySelector('.nb-page-body');
    if (ghostBody) ghostBody.scrollTop = scrollTop;
    setTimeout(() => { ghost.remove(); sheet.classList.remove('nb-turn-in'); }, NB_TURN_MS + 80);
}

function goToPrevPage() {
    const idx = notebookPagesCache.findIndex(p => p.id === currentOpenPageId);
    if (idx > 0) {
        const id = notebookPagesCache[idx - 1].id;
        playNotebookPageTurn('prev', () => openNotebookPage(id));
    }
}
function goToNextPage() {
    const idx = notebookPagesCache.findIndex(p => p.id === currentOpenPageId);
    if (idx !== -1 && idx < notebookPagesCache.length - 1) {
        const id = notebookPagesCache[idx + 1].id;
        playNotebookPageTurn('next', () => openNotebookPage(id));
    }
}

// החלקה הצידה על הדף מעבירה דף - לכיוון הכריכה = קדימה (ימינה בעברית, שמאלה באנגלית). לא על
// הקנבס (שם מציירים), לא בשדות קלט ולא בטקסט בזמן כתיבה (שם גוררים כדי לסמן טקסט)
function initNotebookSwipe() {
    const book = document.getElementById('nb-book');
    if (!book || book.dataset.swipeBound) return;
    book.dataset.swipeBound = '1';
    let startX = 0, startY = 0, startTime = 0, tracking = false;
    book.addEventListener('pointerdown', (e) => {
        tracking = false;
        if (nbViewMode !== 'notebook') return;
        const target = e.target;
        if (target.closest('canvas, .notebook-emoji-item, input, .nb-tools')) return;
        const ta = target.closest('textarea');
        if (ta && document.activeElement === ta) return;
        startX = e.clientX; startY = e.clientY; startTime = Date.now(); tracking = true;
    });
    book.addEventListener('pointerup', (e) => {
        if (!tracking) return;
        tracking = false;
        const dx = e.clientX - startX, dy = e.clientY - startY;
        if (Date.now() - startTime > 700 || Math.abs(dx) < 55 || Math.abs(dx) < Math.abs(dy) * 1.6) return;
        const forward = document.documentElement.dir === 'rtl' ? dx > 0 : dx < 0;
        if (forward) goToNextPage(); else goToPrevPage();
    });
    book.addEventListener('pointercancel', () => { tracking = false; });
}

// "+" בראש המחברת: קודם בוחרים סוג נייר (ר' modal-notebook-page-type-choice), ואז נוצר דף חדש בסוף
// המחברת והיא מתהפכת אליו מיד (אפשר לשנות שם אחר כך בלחיצה על כותרת הדף)
async function createNotebookPage(pageType) {
    closeModal('modal-notebook-page-type-choice');
    if (!supabaseClient || !currentUserId || !currentOpenNotebookId) return;
    const type = NB_PAGE_TYPES.includes(pageType) ? pageType : 'write';
    const nextOrder = notebookPagesCache.length ? Math.max(...notebookPagesCache.map(p => p.sort_order)) + 1 : 0;
    const { data, error } = await supabaseClient.from('notebook_pages').insert({ notebook_id: currentOpenNotebookId, user_id: currentUserId, username: currentUsername, title: `${t('notebook_page_default_title')} ${notebookPagesCache.length + 1}`, sort_order: nextOrder, canvas_data: [], page_type: type, text_content: type === 'write' ? '' : null }).select().maybeSingle();
    if (error || !data) { if (error) showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    notebookPagesCache.push(data);
    playNotebookPageTurn('next', () => openNotebookPage(data.id));
}

function openRenamePageModal() {
    const page = notebookPagesCache.find(p => p.id === currentOpenPageId);
    if (!page) return;
    editingPageId = page.id;
    document.getElementById('notebook-page-rename-input').value = page.title;
    openModal('modal-rename-notebook-page');
    setTimeout(() => document.getElementById('notebook-page-rename-input').focus(), 150);
}

async function submitRenamePage() {
    const input = document.getElementById('notebook-page-rename-input');
    const title = input.value.trim();
    const pageId = editingPageId;
    closeModal('modal-rename-notebook-page');
    editingPageId = null;
    if (!title || !pageId || !supabaseClient) return;
    await supabaseClient.from('notebook_pages').update({ title }).eq('id', pageId);
    const page = notebookPagesCache.find(p => p.id === pageId);
    if (page) page.title = title;
    renderPageNavHeader();
    renderPageTabsList();
}

// מוחקת דף (מתוך תוכן העניינים); אם היה הדף היחיד - נוצר מיד "דף 1" ריק (מחברת לא נשארת בלי דף),
// ואם היה הדף הפתוח - עוברים לדף הראשון. סימנייה על הדף הזה מתאפסת לבד (on delete set null)
function deleteNotebookPage(pageId) {
    showDangerConfirm(t('notebook_page_delete_title'), t('notebook_page_delete_confirm'), async () => {
        await supabaseClient.from('notebook_pages').delete().eq('id', pageId);
        notebookPagesCache = notebookPagesCache.filter(p => p.id !== pageId);
        notebookAllItemsCache = notebookAllItemsCache.filter(i => i.page_id !== pageId);
        const nb = allNotebooksCache.find(n => n.id === currentOpenNotebookId);
        if (nb && nb.bookmark_page_id === pageId) nb.bookmark_page_id = null;
        if (!notebookPagesCache.length) {
            currentOpenPageId = null;
            await loadNotebookPages(currentOpenNotebookId);
            if (notebookPagesCache.length) openNotebookPage(notebookPagesCache[0].id);
            return;
        }
        if (currentOpenPageId === pageId) {
            currentOpenPageId = null;
            openNotebookPage(notebookPagesCache[0].id);
        } else {
            renderPageNavHeader();
            renderPageTabsList();
        }
    });
}

// --- 🔖 סימנייה: דף אחד בכל מחברת; המחברת נפתחת עליו, ועל הכריכה בארון תלוי סרט ---
function renderNotebookBookmarkState() {
    const nb = allNotebooksCache.find(n => n.id === currentOpenNotebookId);
    const on = !!(nb && currentOpenPageId && nb.bookmark_page_id === currentOpenPageId);
    const ribbon = document.getElementById('nb-page-ribbon');
    if (ribbon) ribbon.classList.toggle('hidden', !on);
    const btn = document.getElementById('nb-bookmark-btn');
    if (btn) {
        btn.classList.toggle('active', on);
        btn.setAttribute('aria-pressed', on ? 'true' : 'false');
        btn.title = t(on ? 'nb_bookmark_remove_title' : 'nb_bookmark_add_title');
        btn.setAttribute('aria-label', btn.title);
    }
    // הסרט הקטן על הדף המסומן בפס הדפים
    nbRenderStrip();
}
async function toggleNotebookBookmark() {
    const nb = allNotebooksCache.find(n => n.id === currentOpenNotebookId);
    if (!nb || !currentOpenPageId || !supabaseClient) return;
    const newValue = nb.bookmark_page_id === currentOpenPageId ? null : currentOpenPageId;
    const { error } = await supabaseClient.from('project_notebooks').update({ bookmark_page_id: newValue }).eq('id', nb.id);
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    nb.bookmark_page_id = newValue;
    renderNotebookBookmarkState();
    renderPageTabsList();
    showAppToast(t(newValue ? 'nb_bookmark_set_toast' : 'nb_bookmark_removed_toast'));
}

// --- ☰ תוכן עניינים: כל הדפים לפי הסדר (מספר, סוג הנייר, שם, 🔖), חיפוש בשמות ובשורות, מעבר בלחיצה ---
function openNotebookContents() {
    notebookPagesSearchFilterIds = null;
    const input = document.getElementById('notebook-pages-search-input');
    if (input) input.value = '';
    renderPageTabsList();
    openModal('modal-nb-contents');
}
function renderPageTabsList() {
    const listEl = document.getElementById('notebook-page-tabs-list');
    if (!listEl) return;
    const nb = allNotebooksCache.find(n => n.id === currentOpenNotebookId);
    const pages = notebookPagesSearchFilterIds ? notebookPagesCache.filter(p => notebookPagesSearchFilterIds.has(p.id)) : notebookPagesCache;
    if (!pages.length) {
        listEl.innerHTML = `<p class="language-no-results">${t('notebook_pages_no_results')}</p>`;
        return;
    }
    listEl.innerHTML = pages.map(page => {
        const type = NB_PAGE_TYPES.includes(page.page_type) ? page.page_type : 'draw';
        const marked = nb && nb.bookmark_page_id === page.id;
        return `
        <li class="notebook-page-tab-item${page.id === currentOpenPageId ? ' active' : ''}">
            <span class="notebook-page-tab-item-main" onclick="selectNotebookPage('${page.id}')"><span class="nb-toc-num">${notebookPagesCache.indexOf(page) + 1}</span><span class="nb-toc-type" aria-hidden="true">${NB_PAGE_TYPE_ICONS[type]}</span><span class="nb-toc-title">${escapeHtmlForReport(page.title)}</span>${marked ? '<span class="nb-toc-mark" aria-hidden="true">🔖</span>' : ''}</span>
            <button type="button" class="btn-delete-item" onclick="deleteNotebookPage('${page.id}')">❌</button>
        </li>`;
    }).join('');
}
function selectNotebookPage(pageId) {
    closeModal('modal-nb-contents');
    nbGoToPage(pageId);
}

// --- ⋯ בראש המחברת: כריכה ופרטים, שינוי שם הדף, ניקוי הציור (רק בדף ציור) ומחיקת הדף ---
function openNotebookActions() {
    const nb = allNotebooksCache.find(n => n.id === currentOpenNotebookId);
    const page = notebookPagesCache.find(p => p.id === currentOpenPageId);
    const grid = document.getElementById('nb-actions-grid');
    if (!nb || !grid) return;
    closeNbPops();
    document.getElementById('nb-actions-title').textContent = `${nb.cover_emoji || '📓'} ${nb.title}`;
    grid.innerHTML = '';
    const isCanvas = !!(page && (page.page_type === 'draw' || page.page_type === 'grid'));
    const options = [{ icon: '🎨', key: 'nb_cover_edit_title', desc: 'nb_action_cover_desc', run: () => openNotebookCoverModal(nb.id) }];
    if (page) options.push({ icon: '✏️', key: 'notebook_page_rename_title', desc: 'nb_action_rename_desc', run: () => openRenamePageModal() });
    if (isCanvas) options.push({ icon: '🧽', key: 'notebook_canvas_clear_title', desc: 'nb_action_clear_desc', run: () => clearCanvas() });
    if (page) options.push({ icon: '🗑️', key: 'nb_action_delete_page', desc: 'nb_action_delete_page_desc', danger: true, run: () => deleteNotebookPage(page.id) });
    options.forEach(o => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'bag-add-option' + (o.danger ? ' is-danger' : '');
        b.innerHTML = `<span class="bag-add-option-icon" aria-hidden="true">${o.icon}</span><span class="bag-add-option-text"><span class="bag-add-option-name">${escapeHtmlForReport(t(o.key))}</span><span class="bag-add-option-desc">${escapeHtmlForReport(t(o.desc))}</span></span>`;
        b.onclick = () => { closeModal('modal-nb-actions'); o.run(); };
        grid.appendChild(b);
    });
    openModal('modal-nb-actions');
}

// --- 🎨 כריכה ופרטים: מחברת חדשה (מה-"+ מחברת" או מה-"+" שעל מדף) או עריכת קיימת ---
function openNotebookCoverModal(notebookId, presetShelfId) {
    if (!isPremiumUser) { openPremiumUpgradeModal(); return; }
    const nb = notebookId ? allNotebooksCache.find(n => n.id === notebookId) : null;
    const defaultShelf = presetShelfId || (projectsCache[0] && projectsCache[0].id) || NB_NEW_SHELF;
    nbCoverDraft = nb
        ? { id: nb.id, project_id: nb.project_id, color: nbCoverColor(nb), pattern: nbCoverPattern(nb), emoji: nb.cover_emoji || '📓' }
        : { id: null, project_id: defaultShelf, color: NB_COVER_COLORS[allNotebooksCache.length % NB_COVER_COLORS.length], pattern: 'plain', emoji: '📓' };
    document.getElementById('nb-cover-modal-title').textContent = t(nb ? 'nb_cover_edit_title' : 'notebooks_add_item_title');
    document.getElementById('btn-save-nb-cover').textContent = t(nb ? 'save_generic' : 'add_btn');
    document.getElementById('nb-cover-name').value = nb ? nb.title : '';
    const newShelfInput = document.getElementById('nb-cover-new-shelf');
    newShelfInput.value = projectsCache.length ? '' : t('nb_default_shelf_name');
    renderNbCoverShelfOptions();
    renderNbCoverPickers();
    document.getElementById('nb-cover-delete-btn').classList.toggle('hidden', !nb);
    openModal('modal-nb-cover');
    if (!nb) setTimeout(() => document.getElementById('nb-cover-name').focus(), 150);
}
function openAddNotebookModal() { openNotebookCoverModal(null, currentOpenProjectId); }
function openEditNotebookModal(id) { openNotebookCoverModal(id); }

function renderNbCoverShelfOptions() {
    const select = document.getElementById('nb-cover-shelf');
    if (!select || !nbCoverDraft) return;
    select.innerHTML = '';
    projectsCache.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p.id;
        opt.textContent = `${p.icon || '📁'} ${p.title}`;
        select.appendChild(opt);
    });
    const other = document.createElement('option');
    other.value = NB_NEW_SHELF;
    other.textContent = t('nb_shelf_new_option');
    select.appendChild(other);
    select.value = nbCoverDraft.project_id;
    updateCustomSelectDisplay('nb-cover-shelf');
    document.getElementById('nb-cover-new-shelf').classList.toggle('hidden', nbCoverDraft.project_id !== NB_NEW_SHELF);
}
function onNbCoverShelfChange() {
    const select = document.getElementById('nb-cover-shelf');
    if (!select || !nbCoverDraft) return;
    nbCoverDraft.project_id = select.value;
    const input = document.getElementById('nb-cover-new-shelf');
    input.classList.toggle('hidden', select.value !== NB_NEW_SHELF);
    if (select.value === NB_NEW_SHELF) setTimeout(() => input.focus(), 120);
}

function renderNbCoverPickers() {
    const d = nbCoverDraft;
    if (!d) return;
    const colors = document.getElementById('nb-cover-colors');
    colors.innerHTML = '';
    NB_COVER_COLORS.forEach(color => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'nb-swatch' + (d.color === color ? ' selected' : '');
        b.style.setProperty('--nb-color', color);
        b.setAttribute('aria-label', color);
        b.setAttribute('aria-pressed', d.color === color ? 'true' : 'false');
        b.onclick = () => { d.color = color; renderNbCoverPickers(); };
        colors.appendChild(b);
    });
    const patterns = document.getElementById('nb-cover-patterns');
    patterns.innerHTML = '';
    NB_COVER_PATTERNS.forEach(pattern => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = `nb-pattern-chip nb-pat-${pattern}` + (d.pattern === pattern ? ' selected' : '');
        b.style.setProperty('--nb-color', d.color);
        b.setAttribute('aria-pressed', d.pattern === pattern ? 'true' : 'false');
        b.innerHTML = `<span class="nb-pattern-name">${escapeHtmlForReport(t('nb_pattern_' + pattern))}</span>`;
        b.onclick = () => { d.pattern = pattern; renderNbCoverPickers(); };
        patterns.appendChild(b);
    });
    const emojis = document.getElementById('nb-cover-emojis');
    emojis.innerHTML = '';
    // מדבקה שהוקלדה ב"אחר" (לא ברשימה) מוצגת ראשונה ומסומנת
    const list = NB_COVER_EMOJIS.includes(d.emoji) ? NB_COVER_EMOJIS : [d.emoji, ...NB_COVER_EMOJIS];
    list.forEach(emoji => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'icon-picker-chip' + (d.emoji === emoji ? ' selected' : '');
        b.textContent = emoji;
        b.onclick = () => { d.emoji = emoji; renderNbCoverPickers(); };
        emojis.appendChild(b);
    });
    renderNbCoverPreview();
}function renderNbCoverPreview() {
    const wrap = document.getElementById('nb-cover-preview');
    if (!wrap || !nbCoverDraft) return;
    const name = document.getElementById('nb-cover-name').value.trim() || t('notebooks_add_item_title');
    wrap.innerHTML = `<span class="nb-cover nb-cover-preview nb-pat-${nbCoverDraft.pattern}" style="--nb-color:${nbCoverDraft.color}">${nbCoverInnerHtml(nbCoverDraft.emoji, name)}</span>`;
}

async function saveNotebookCover() {
    const d = nbCoverDraft;
    if (!d || !supabaseClient || !currentUserId) return;
    const title = document.getElementById('nb-cover-name').value.trim() || t('notebooks_add_item_title');
    let projectId = d.project_id;
    if (projectId === NB_NEW_SHELF || !projectsCache.some(p => p.id === projectId)) {
        const shelfName = document.getElementById('nb-cover-new-shelf').value.trim() || t('nb_default_shelf_name');
        const shelf = await bagCreatePocket(shelfName);
        if (!shelf) return;
        projectId = shelf.id;
    }
    const payload = { title, project_id: projectId, cover_color: d.color, cover_pattern: d.pattern, cover_emoji: d.emoji };
    closeModal('modal-nb-cover');
    nbCoverDraft = null;
    if (d.id) {
        const { error } = await supabaseClient.from('project_notebooks').update(payload).eq('id', d.id);
        if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
        const nb = allNotebooksCache.find(n => n.id === d.id);
        if (nb) Object.assign(nb, payload);
        if (nbViewMode === 'notebook' && currentOpenNotebookId === d.id) renderNotebookViewTitle();
        renderNotebookShelves();
        showAppToast(t('item_updated_success'));
        return;
    }
    const { data, error } = await supabaseClient.from('project_notebooks').insert({ ...payload, user_id: currentUserId, username: currentUsername }).select().maybeSingle();
    if (error || !data) { showAppToast(t('error_adding_item') + (error ? error.message : ''), 'error'); return; }
    // מחברת חדשה מתחילה עם דף שורות אחד, ונפתחת מיד
    await supabaseClient.from('notebook_pages').insert({ notebook_id: data.id, user_id: currentUserId, username: currentUsername, title: `${t('notebook_page_default_title')} 1`, sort_order: 0, canvas_data: [], page_type: 'write', text_content: '' });
    allNotebooksCache.push(data);
    bagPageCounts[data.id] = 1;
    bagPendingPocketId = null;
    renderNotebookShelves();
    showAppToast(t('item_added_success'));
    openNotebookView(data.id);
}

function deleteNotebookFromCover() {
    const id = nbCoverDraft && nbCoverDraft.id;
    if (!id) return;
    closeModal('modal-nb-cover');
    deleteNotebook(id);
}
function deleteNotebook(id) {
    showDangerConfirm(t('notebook_delete_title'), t('notebook_delete_confirm'), async () => {
        await supabaseClient.from('project_notebooks').delete().eq('id', id);
        allNotebooksCache = allNotebooksCache.filter(n => n.id !== id);
        if (nbViewMode === 'notebook' && currentOpenNotebookId === id) {
            setNotebookViewOpen(false);
            nbViewMode = null;
        }
        renderNotebookShelves();
    });
}

// --- כיסים (טבלת projects): שם, אייקון וצבע; עריכה מה-✏️ שבקלסר, ומחיקה מתוך העריכה ---
function renderProjectColorPicker() {
    const container = document.getElementById('project-color-picker');
    if (!container) return;
    container.innerHTML = '';
    BAG_POCKET_COLORS.forEach(color => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'nb-swatch' + (selectedProjectColor === color ? ' selected' : '');
        b.style.setProperty('--nb-color', color);
        b.setAttribute('aria-label', color);
        b.setAttribute('aria-pressed', selectedProjectColor === color ? 'true' : 'false');
        b.onclick = () => { selectedProjectColor = color; renderProjectColorPicker(); };
        container.appendChild(b);
    });
}
function renderProjectIconPicker() {
    const container = document.getElementById('project-icon-picker');
    if (!container) return;
    container.innerHTML = '';
    const icons = PROJECT_ICON_PRESETS.includes(selectedProjectIcon) ? PROJECT_ICON_PRESETS : [selectedProjectIcon, ...PROJECT_ICON_PRESETS];
    icons.forEach(icon => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'icon-picker-chip' + (selectedProjectIcon === icon ? ' selected' : '');
        chip.textContent = icon;
        chip.onclick = () => selectProjectIcon(icon);
        container.appendChild(chip);
    });
}
function selectProjectIcon(icon) {
    selectedProjectIcon = icon;
    renderProjectIconPicker();
}
function openAddShelfModal() {
    if (!isPremiumUser) { openPremiumUpgradeModal(); return; }
    openAddProjectModal();
}
function openAddProjectModal() {
    editingProjectId = null;
    document.getElementById('project-modal-title').textContent = t('nb_shelf_add_title');
    document.getElementById('btn-save-project').textContent = t('add_btn');
    document.getElementById('project-item-input').value = '';
    document.getElementById('project-delete-btn').classList.add('hidden');
    selectedProjectIcon = PROJECT_ICON_PRESETS[0];
    selectedProjectColor = BAG_POCKET_COLORS[projectsCache.length % BAG_POCKET_COLORS.length];
    renderProjectIconPicker();
    renderProjectColorPicker();
    openModal('modal-add-project');
    setTimeout(() => document.getElementById('project-item-input').focus(), 150);
}
function openEditProjectModal(id) {
    const project = projectsCache.find(p => p.id === id);
    if (!project) return;
    editingProjectId = id;
    document.getElementById('project-modal-title').textContent = t('nb_shelf_edit_title');
    document.getElementById('btn-save-project').textContent = t('save_generic');
    document.getElementById('project-item-input').value = project.title;
    document.getElementById('project-delete-btn').classList.remove('hidden');
    selectedProjectIcon = project.icon || PROJECT_ICON_PRESETS[0];
    selectedProjectColor = bagPocketColor(project);
    renderProjectIconPicker();
    renderProjectColorPicker();
    openModal('modal-add-project');
}

async function submitProject() {
    const input = document.getElementById('project-item-input');
    const title = input.value.trim();
    const icon = selectedProjectIcon;
    const color = selectedProjectColor;
    const editId = editingProjectId;
    if (!title) { input.focus(); return; }
    closeModal('modal-add-project');
    editingProjectId = null;
    if (!supabaseClient || !currentUserId) return;
    if (editId) {
        const { error } = await supabaseClient.from('projects').update({ title, icon, color }).eq('id', editId);
        if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
        const project = projectsCache.find(p => p.id === editId);
        if (project) Object.assign(project, { title, icon, color });
        showAppToast(t('item_updated_success'));
        renderNotebookShelves();
        return;
    }
    const { data, error } = await supabaseClient.from('projects').insert({ user_id: currentUserId, username: currentUsername, title, icon, color }).select().maybeSingle();
    if (error || !data) { showAppToast(t('error_adding_item') + (error ? error.message : ''), 'error'); return; }
    projectsCache.push(data);
    showAppToast(t('item_added_success'));
    renderNotebookShelves();
    bagOnPocketCreated(data);
}

// מחיקת כיס מוחקת את כל מה שבתוכו - המחברות (FK cascade) וגם הטבלאות והמשימות שלו. החלון אומר כמה
// מכל סוג, ושאפשר להעביר קודם לכיס אחר את מה שרוצים לשמור
function deleteProject(id) {
    if (!id) return;
    closeModal('modal-add-project');
    const items = bagItemsOf(id);
    const message = t('nb_shelf_delete_confirm')
        .replace('{nb}', items.notebooks.length.toLocaleString(currentLang))
        .replace('{tb}', items.tables.length.toLocaleString(currentLang))
        .replace('{ts}', items.tasks.length.toLocaleString(currentLang));
    showDangerConfirm(t('nb_shelf_delete_title'), message, async () => {
        await supabaseClient.from('custom_tables').delete().eq('project_id', id).eq('user_id', currentUserId);
        await supabaseClient.from('study_tasks').delete().eq('project_id', id).eq('user_id', currentUserId);
        const { error } = await supabaseClient.from('projects').delete().eq('id', id);
        if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
        const goneTables = customTablesCache.filter(x => x.project_id === id).map(x => x.id);
        projectsCache = projectsCache.filter(p => p.id !== id);
        allNotebooksCache = allNotebooksCache.filter(n => n.project_id !== id);
        customTablesCache = customTablesCache.filter(x => x.project_id !== id);
        studyTasksCache = studyTasksCache.filter(x => x.project_id !== id);
        if (nbViewMode === 'notebook' && currentOpenProjectId === id) {
            setNotebookViewOpen(false);
            nbViewMode = null;
        }
        if (currentOpenTableId && goneTables.includes(currentOpenTableId)) closeTableView();
        editingProjectId = null;
        renderNotebookShelves();
    });
}

// מחפשת גם בשמות הדפים וגם בטקסט הפריטים שבתוכם (לא בציור החופשי - אין OCR,
// לפי בקשה מפורשת), אותו דפוס בדיוק כמו renderLanguagePickerList
function searchNotebookPages(filter) {
    const query = (filter || '').trim().toLowerCase();
    if (!query) { notebookPagesSearchFilterIds = null; renderPageTabsList(); return; }
    const ids = new Set();
    notebookPagesCache.forEach(p => { if (p.title.toLowerCase().includes(query)) ids.add(p.id); });
    notebookAllItemsCache.forEach(item => { if (item.title.toLowerCase().includes(query)) ids.add(item.page_id); });
    notebookPagesSearchFilterIds = ids;
    renderPageTabsList();
}

// השורות של דף: לפי סדר הכתיבה (הראשונה למעלה), כמו ברשימה על נייר
async function loadNotebookItems(pageId) {
    if (!supabaseClient || !currentUserId || !pageId) return;
    const { data, error } = await supabaseClient.from('notebook_items').select('*').eq('page_id', pageId).eq('user_id', currentUserId).order('created_at', { ascending: true });
    if (error || pageId !== currentOpenPageId) return;
    notebookItemsCache = data || [];
    // גם החיפוש ופס הדפים רואים מיד ✓ ושורות חדשות של הדף הזה
    notebookAllItemsCache = notebookAllItemsCache.filter(i => i.page_id !== pageId).concat(notebookItemsCache);
    renderNotebookItemsList();
}

// רשימת השורות מוצגת בדף "רשימה" (עם רמז כשהיא ריקה), ובדפים מסוג אחר רק אם יש בהם שורות ישנות
function renderNotebookItemsList() {
    const listEl = document.getElementById('notebook-items-list');
    const emptyEl = document.getElementById('notebook-items-empty');
    if (!listEl) return;
    listEl.innerHTML = '';
    const page = notebookPagesCache.find(p => p.id === currentOpenPageId);
    const isList = !!(page && page.page_type === 'list');
    listEl.classList.toggle('hidden', !isList && !notebookItemsCache.length);
    if (emptyEl) emptyEl.classList.toggle('hidden', !isList || notebookItemsCache.length > 0);
    notebookItemsCache.forEach(item => {
        const li = document.createElement('li');
        li.className = 'study-task-item';
        li.innerHTML = `
            <button type="button" class="btn-complete-item${item.is_completed ? ' checked' : ''}" onclick="toggleNotebookItemStatus('${item.id}', ${item.is_completed})">${item.is_completed ? '✓' : ''}</button>
            <span class="center-list-item-text${item.is_completed ? ' completed' : ''}" onclick="toggleStudyItemExpand(this)">${escapeHtmlForReport(item.title)}</span>
            <button type="button" class="btn-edit-item" onclick="openEditNotebookItemModal('${item.id}')">${EDIT_ICON_SVG}</button>
            <button type="button" class="btn-delete-item" onclick="deleteNotebookItem('${item.id}')">❌</button>
        `;
        listEl.appendChild(li);
    });
    if (currentOpenPageId) nbRefreshThumb(currentOpenPageId);
}

async function toggleNotebookItemStatus(id, currentStatus) {
    if (!supabaseClient) return;
    await supabaseClient.from('notebook_items').update({ is_completed: !currentStatus }).eq('id', id);
    loadNotebookItems(currentOpenPageId);
}

function openAddNotebookItemModal() {
    editingNotebookItemId = null;
    document.getElementById('notebook-item-modal-title').textContent = t('notebook_item_add_title');
    document.getElementById('notebook-item-text-input').value = '';
    openModal('modal-add-notebook-item');
    setTimeout(() => document.getElementById('notebook-item-text-input').focus(), 150);
}

function openEditNotebookItemModal(id) {
    const item = notebookItemsCache.find(x => x.id === id);
    if (!item) return;
    editingNotebookItemId = id;
    document.getElementById('notebook-item-modal-title').textContent = t('edit_item_title');
    document.getElementById('notebook-item-text-input').value = item.title;
    openModal('modal-add-notebook-item');
}

async function submitNotebookItem() {
    const input = document.getElementById('notebook-item-text-input');
    const title = input.value.trim();
    const editId = editingNotebookItemId;
    closeModal('modal-add-notebook-item');
    editingNotebookItemId = null;
    if (!title || !supabaseClient || !currentUserId || !currentOpenPageId) return;
    let error;
    if (editId) {
        ({ error } = await supabaseClient.from('notebook_items').update({ title }).eq('id', editId));
    } else {
        // notebook_id הוא NOT NULL בטבלה - בלי אותו כאן ה-insert נכשל בשקט
        // (לא היה שום בדיקת error!) והתוספת פשוט לא קרתה בכלל, בדיוק מה שדווח
        ({ error } = await supabaseClient.from('notebook_items').insert({ notebook_id: currentOpenNotebookId, page_id: currentOpenPageId, user_id: currentUserId, username: currentUsername, title }));
    }
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    await loadNotebookItems(currentOpenPageId);
    // מרענן גם את מטמון-החיפוש הכולל (כל הפריטים מכל הדפים), כדי שפריט חדש/
    // מעודכן יהיה מיד בר-חיפוש בלי לצאת ולהיכנס שוב למחברת
    const { data: itemsData } = await supabaseClient.from('notebook_items').select('*').eq('user_id', currentUserId).in('page_id', notebookPagesCache.map(p => p.id));
    notebookAllItemsCache = itemsData || [];
    showAppToast(t('item_added_success'));
}

async function deleteNotebookItem(id) {
    if (!supabaseClient) return;
    await supabaseClient.from('notebook_items').delete().eq('id', id);
    loadNotebookItems(currentOpenPageId);
    notebookAllItemsCache = notebookAllItemsCache.filter(i => i.id !== id);
}

// דף "רשימה": שורה חדשה נכתבת ישר בתחתית הדף (Enter או +), בלי חלון נפרד - והשדה נשאר פתוח לשורה הבאה
async function addNotebookListLine() {
    const input = document.getElementById('nb-list-add-input');
    const title = (input && input.value || '').trim();
    if (!title || !supabaseClient || !currentUserId || !currentOpenPageId) return;
    input.value = '';
    const { data, error } = await supabaseClient.from('notebook_items').insert({ notebook_id: currentOpenNotebookId, page_id: currentOpenPageId, user_id: currentUserId, username: currentUsername, title }).select().maybeSingle();
    if (error) { input.value = title; showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    if (data) notebookAllItemsCache.push(data);
    await loadNotebookItems(currentOpenPageId);
    input.focus();
}

// --- שכבת הציור החופשי (קנבס) לכל דף - נבנתה מאפס, אין תקדים בקוד הקיים.
// דפוס אירועי המצביע (pointerdown על הקנבס + מאזיני document ל-pointermove/up
// שמתווספים/מוסרים דינמית) תואם את הסגנון הקיים באפליקציה (ר' גרירת-אווטאר
// במסלול-היעדים) - לא setPointerCapture. touch-action:none על הקנבס (ב-CSS)
// הוא קריטי כדי שציור באצבע/Apple Pencil לא "יגנוב" גלילה של הדף ---
function sizeNotebookCanvasToContainer(canvas) {
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
}

function initNotebookCanvas() {
    const canvas = document.getElementById('notebook-page-canvas');
    if (!canvas) return;
    sizeNotebookCanvasToContainer(canvas);
    if (!notebookCanvasPointerBound) {
        notebookCanvasPointerBound = true;
        canvas.addEventListener('pointerdown', startStroke);
    }
    redrawCanvasFromStrokes();
    renderEmojiOverlay();
    // המדידה הראשונית למעלה עלולה לתפוס רגע-ביניים שבו הפריסה עוד לא
    // התייצבה לגמרי (בעיקר במגירה הרחבה של "הפרוייקטים שלי" בדסקטופ, ר'
    // .notebook-detail-drawer) - הקנבס מקבל אז רוחב/גובה כמעט-0 (מתעגל ל-1
    // פיקסל), וכל שרטוט הלאה נדחס לרצועה בלתי-נראית לגמרי: הכפתורים עדיין
    // מגיבים (סימון "פעיל" עובד), אבל שום דבר לא נראה מצויר בפועל - בדיוק
    // הדיווח בפועל בתוך פרוייקטים. פריים נוסף אחרי הרינדור הראשון בודק שוב
    // ומתקן את עצמו בשקט אם הגודל השתנה משמעותית בינתיים
    // חשוב: משנים את canvas.width/height רק אם הגודל באמת השתנה - כל השמה (גם לאותו ערך) מוחקת
    // את כל מה שצויר, וזה מה שגרם לציור שמור להיעלם פריים אחד אחרי שנפתח הדף
    requestAnimationFrame(() => {
        if (canvas.closest('.hidden')) return;
        const rect = canvas.getBoundingClientRect();
        if (rect.width < 2 || rect.height < 2) return;
        const dpr = window.devicePixelRatio || 1;
        const w = Math.max(1, Math.round(rect.width * dpr));
        const h = Math.max(1, Math.round(rect.height * dpr));
        if (w !== canvas.width || h !== canvas.height) {
            canvas.width = w;
            canvas.height = h;
            redrawCanvasFromStrokes();
            renderEmojiOverlay();
        }
    });
}

// initNotebookCanvas מתאים DPR-מדויק לגודל ה-CSS בזמן הפתיחה בלבד - בלי
// listener, שינוי גודל חלון היה משאיר את הקנבס מטושטש/לא מסונכרן עד שהדף
// נפתח מחדש. פעיל רק כשמחברת פתוחה על דף ציור (בדיקה זולה), מבוזר (debounce)
// כדי לא להריץ redraw מלא על כל פיקסל תזוזה באמצע גרירת-חלון
let notebookResizeDebounceTimer = null;
function handleNotebookViewportResize() {
    if (nbViewMode !== 'notebook' || !isNotebookViewOpen()) return;
    const area = document.getElementById('notebook-canvas-section-body');
    if (!area || area.classList.contains('hidden')) return;
    clearTimeout(notebookResizeDebounceTimer);
    notebookResizeDebounceTimer = setTimeout(() => {
        initNotebookCanvas();
    }, 150);
}
window.addEventListener('resize', handleNotebookViewportResize);
window.addEventListener('orientationchange', handleNotebookViewportResize);

function redrawCanvasFromStrokes() {
    const canvas = document.getElementById('notebook-page-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    canvasStrokes.forEach(entry => drawStrokeEntry(ctx, canvas, entry));
}

// t:'emoji' כבר לא מטופל כאן - עבר לשכבת DOM נפרדת (ר' renderEmojiOverlay)
// כדי שאפשר יהיה לגרור אימוג'ים אחרי ההנחתה, לפי בקשה מפורשת ("שיהיה אפשר
// להזיז את האימוג'י ידנית"). דיו בלבד מכאן ואילך
//
// פרמטרי-רינדור לפי סוג קו שמור (entry.t) - משותף בין drawStrokeEntry (ציור
// מחדש) ל-continueStroke (ציור חי), כדי ששני המסלולים ייראו תמיד זהים:
// 's'=עט (אטום, קצה עגול), 'e'=מחק (destination-out, קיים כבר), 'm'=מרקר
// עגול (שקוף חלקית, קצה עגול - "כמו טוש"), 'q'=מרקר מרובע/שטוח (שקוף חלקית,
// קצה מרובע - "כמו טוש-שטוח", לפי בקשה מפורשת)
function strokeRenderParams(type) {
    if (type === 'e') return { cap: 'round', join: 'round', alpha: 1, composite: 'destination-out' };
    if (type === 'm') return { cap: 'round', join: 'round', alpha: 0.4, composite: 'source-over' };
    if (type === 'q') return { cap: 'square', join: 'bevel', alpha: 0.4, composite: 'source-over' };
    return { cap: 'round', join: 'round', alpha: 1, composite: 'source-over' };
}
function drawStrokeEntry(ctx, canvas, entry) {
    if (!entry.pts || entry.pts.length < 2) return;
    const rp = strokeRenderParams(entry.t);
    ctx.globalCompositeOperation = rp.composite;
    ctx.globalAlpha = rp.alpha;
    ctx.strokeStyle = entry.c || '#000';
    ctx.lineWidth = entry.w || 3;
    ctx.lineCap = rp.cap;
    ctx.lineJoin = rp.join;
    ctx.beginPath();
    // עקומה חלקה דרך נקודות-אמצע (quadratic-curve-through-midpoints) במקום
    // lineTo גס נקודה-לנקודה - "כמו Procreate", לפי בקשה מפורשת. הקטע
    // האחרון נשאר lineTo פשוט (אין עוד נקודה להתאמצע איתה)
    ctx.moveTo(entry.pts[0][0] * canvas.width, entry.pts[0][1] * canvas.height);
    if (entry.pts.length === 2) {
        ctx.lineTo(entry.pts[1][0] * canvas.width, entry.pts[1][1] * canvas.height);
    } else {
        for (let i = 1; i < entry.pts.length - 1; i++) {
            const p = entry.pts[i], pNext = entry.pts[i + 1];
            const midX = (p[0] + pNext[0]) / 2 * canvas.width;
            const midY = (p[1] + pNext[1]) / 2 * canvas.height;
            ctx.quadraticCurveTo(p[0] * canvas.width, p[1] * canvas.height, midX, midY);
        }
        const last = entry.pts[entry.pts.length - 1];
        ctx.lineTo(last[0] * canvas.width, last[1] * canvas.height);
    }
    ctx.stroke();
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
}

function getNotebookCanvasPoint(canvas, e) {
    const rect = canvas.getBoundingClientRect();
    return [(e.clientX - rect.left) / rect.width, (e.clientY - rect.top) / rect.height];
}

const DRAW_TOOL_CODES = { pen: 's', marker: 'm', marker_square: 'q', eraser: 'e' };
const DRAW_TOOL_WIDTHS = { s: () => penWidth, m: () => 14, q: () => 16, e: () => 18 };

function startStroke(e) {
    const canvas = document.getElementById('notebook-page-canvas');
    if (!canvas) return;
    e.preventDefault();
    closeNbPops();
    const toolCode = DRAW_TOOL_CODES[currentDrawTool] || 's';
    currentStroke = { t: toolCode, c: penColor, w: DRAW_TOOL_WIDTHS[toolCode](), pts: [getNotebookCanvasPoint(canvas, e)] };
    document.addEventListener('pointermove', continueStroke);
    document.addEventListener('pointerup', endStroke);
}

// גרסת-חי (per pointermove) של אותה עקומת-אמצעים כמו drawStrokeEntry - כל
// קריאה מציירת רק את קטע-האמצעים המקומי החדש (לא מציירת מחדש את כל השורטוק
// עד כה), כדי שלא יהיה הבהוב/עלות ביצועים. שני קטעים עוקבים תמיד נפגשים
// בדיוק בנקודת-אמצע משותפת, אז זה נותן בדיוק את אותה עקומה כמו redraw מלא
function continueStroke(e) {
    const canvas = document.getElementById('notebook-page-canvas');
    if (!canvas || !currentStroke) return;
    currentStroke.pts.push(getNotebookCanvasPoint(canvas, e));
    const ctx = canvas.getContext('2d');
    const pts = currentStroke.pts;
    const rp = strokeRenderParams(currentStroke.t);
    ctx.globalCompositeOperation = rp.composite;
    ctx.globalAlpha = rp.alpha;
    ctx.strokeStyle = currentStroke.c;
    ctx.lineWidth = currentStroke.w;
    ctx.lineCap = rp.cap;
    ctx.lineJoin = rp.join;
    ctx.beginPath();
    if (pts.length < 3) {
        // קטע ראשון - אין עוד נקודת-אמצע קודמת, קו פשוט
        ctx.moveTo(pts[pts.length - 2][0] * canvas.width, pts[pts.length - 2][1] * canvas.height);
        ctx.lineTo(pts[pts.length - 1][0] * canvas.width, pts[pts.length - 1][1] * canvas.height);
    } else {
        const p0 = pts[pts.length - 3], p1 = pts[pts.length - 2], p2 = pts[pts.length - 1];
        const startMidX = (p0[0] + p1[0]) / 2 * canvas.width, startMidY = (p0[1] + p1[1]) / 2 * canvas.height;
        const endMidX = (p1[0] + p2[0]) / 2 * canvas.width, endMidY = (p1[1] + p2[1]) / 2 * canvas.height;
        ctx.moveTo(startMidX, startMidY);
        ctx.quadraticCurveTo(p1[0] * canvas.width, p1[1] * canvas.height, endMidX, endMidY);
    }
    ctx.stroke();
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
}

function endStroke() {
    document.removeEventListener('pointermove', continueStroke);
    document.removeEventListener('pointerup', endStroke);
    if (!currentStroke) return;
    if (currentStroke.pts.length > 1) canvasStrokes.push(currentStroke);
    currentStroke = null;
    saveCanvasData();
}

function undoLastStroke() {
    canvasStrokes.pop();
    redrawCanvasFromStrokes();
    renderEmojiOverlay();
    saveCanvasData();
}

function clearCanvas() {
    showDangerConfirm(t('notebook_canvas_clear_confirm_title'), t('notebook_canvas_clear_confirm_msg'), () => {
        canvasStrokes = [];
        redrawCanvasFromStrokes();
        renderEmojiOverlay();
        saveCanvasData();
    });
}

// כלי הציור (עט/מרקר-עגול/מרקר-מרובע/מחק) נבחר בנפרד לגמרי מהצבע - בחירת
// צבע לא משנה יותר את הכלי הפעיל (בניגוד להתנהגות הישנה, שבה כל בחירת צבע
// יצאה אוטומטית ממצב מחק), כי עכשיו יש 3 כלי-ציור אמיתיים לבחור מביניהם,
// לא רק "עט מול מחק" בינארי - לפי בקשה מפורשת להוסיף עוד כלים
function setDrawTool(tool) {
    currentDrawTool = tool;
    document.querySelectorAll('.notebook-tool-btn').forEach(btn => {
        const on = btn.getAttribute('data-draw-tool') === tool;
        btn.classList.toggle('active', on);
        btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    closeNbPops();
}

// הצבע שנבחר מופיע גם בעיגול שבגלולה, כך שרואים תמיד באיזה צבע מציירים
function setPenColor(color, btnEl) {
    penColor = color;
    document.querySelectorAll('.notebook-color-swatch').forEach(el => el.classList.remove('active'));
    if (btnEl) btnEl.classList.add('active');
    const dot = document.getElementById('nb-tools-dot');
    if (dot) dot.style.background = color;
}

// --- החלוניות הקטנות מעל גלולת הכלים: צבע ועובי / מדבקות. אחת בכל פעם; נסגרות כשמתחילים לצייר,
// כשבוחרים כלי או כשעוברים דף ---
function toggleNbPop(which) {
    const pops = { color: document.getElementById('nb-pop-color'), emoji: document.getElementById('notebook-emoji-picker') };
    const target = pops[which];
    if (!target) return;
    const opening = target.classList.contains('hidden');
    closeNbPops();
    if (!opening) return;
    if (which === 'emoji' && !target.children.length) renderEmojiPicker();
    target.classList.remove('hidden');
    const btn = document.getElementById(which === 'color' ? 'nb-tools-color' : 'nb-tools-emoji');
    if (btn) btn.setAttribute('aria-expanded', 'true');
}
function closeNbPops() {
    ['nb-pop-color', 'notebook-emoji-picker'].forEach(id => document.getElementById(id)?.classList.add('hidden'));
    ['nb-tools-color', 'nb-tools-emoji'].forEach(id => document.getElementById(id)?.setAttribute('aria-expanded', 'false'));
}

// עובי-קו רלוונטי לעט בלבד (לפי בקשה מפורשת "עוד עטים וסגנונות ציור") - למרקר
// עובי קבוע משלו (ר' DRAW_TOOL_WIDTHS), לא מושפע מהבורר הזה בכוונה
function setPenWidth(width, btnEl) {
    penWidth = width;
    document.querySelectorAll('.notebook-width-btn').forEach(el => el.classList.remove('active'));
    if (btnEl) btnEl.classList.add('active');
}

async function saveCanvasData() {
    if (!supabaseClient || !currentOpenPageId) return;
    const pageId = currentOpenPageId;
    const page = notebookPagesCache.find(p => p.id === pageId);
    if (page) page.canvas_data = canvasStrokes;
    nbRefreshThumb(pageId);
    await supabaseClient.from('notebook_pages').update({ canvas_data: canvasStrokes }).eq('id', pageId);
}

// דף-כתיבה: שמירה מבוזרת (לא בכל הקשת מקש, כמו הציור ששומר רק על פעולות
// בדידות/שלמות) - 800ms אחרי שהמשתמשת הפסיקה להקליד
let notebookTextSaveDebounceTimer = null;
function scheduleNotebookTextSave() {
    clearTimeout(notebookTextSaveDebounceTimer);
    notebookTextSaveDebounceTimer = setTimeout(saveNotebookTextContent, 800);
}
async function saveNotebookTextContent() {
    if (!supabaseClient || !currentOpenPageId) return;
    const pageId = currentOpenPageId;
    const value = document.getElementById('notebook-page-text-content').value;
    const page = notebookPagesCache.find(p => p.id === pageId);
    if (page) page.text_content = value;
    nbRefreshThumb(pageId);
    await supabaseClient.from('notebook_pages').update({ text_content: value }).eq('id', pageId);
}

// --- בוחר אימוג'ים - נוחת כמדבקה על הקנבס (לא נכנס לשדה טקסט), לפי בקשה
// מפורשת ("להוסיף אימוגים בדף... נחת על הדף כמו מדבקה/ציור") ---
function renderEmojiPicker() {
    const container = document.getElementById('notebook-emoji-picker');
    if (!container) return;
    container.innerHTML = '';
    NOTEBOOK_EMOJI_PRESETS.forEach(emoji => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'icon-picker-chip';
        chip.textContent = emoji;
        chip.onclick = () => stampEmojiOnCanvas(emoji);
        container.appendChild(chip);
    });
}

function toggleEmojiPickerPanel() {
    toggleNbPop('emoji');
}

function stampEmojiOnCanvas(emoji) {
    canvasStrokes.push({ t: 'emoji', ch: emoji, x: 0.5, y: 0.4, size: 32 });
    renderEmojiOverlay();
    saveCanvasData();
    closeNbPops();
}

// --- שכבת-DOM נפרדת לאימוג'ים על הקנבס (לא מצוירים לתוך הביטמאפ) - כדי
// שאפשר יהיה לגרור כל אחד למקום אחר אחרי ההנחתה, לפי בקשה מפורשת. תופעת-לוואי
// מקובלת: אימוג'י תמיד יושב מעל כל הדיו (גם דיו שצויר אחריו) - כמו מדבקה
// אמיתית, לא שווה את המורכבות לשמר סדר-כרונולוגי מדויק בין שתי שכבות נפרדות ---
function renderEmojiOverlay() {
    const overlay = document.getElementById('notebook-emoji-overlay');
    if (!overlay) return;
    overlay.innerHTML = '';
    canvasStrokes.forEach((entry, idx) => {
        if (entry.t !== 'emoji') return;
        const span = document.createElement('span');
        span.className = 'notebook-emoji-item';
        span.textContent = entry.ch;
        span.style.left = `${entry.x * 100}%`;
        span.style.top = `${entry.y * 100}%`;
        span.style.fontSize = `${entry.size}px`;
        span.dataset.strokeIndex = idx;
        span.addEventListener('pointerdown', startEmojiDrag);
        span.addEventListener('dblclick', deleteEmojiFromCanvas);
        overlay.appendChild(span);
    });
}

// לחיצה כפולה על אימוג'י על הקנבס מוחקת אותו - לפי בקשה מפורשת, אחרי שהתברר
// שאין דרך למחוק אימוג'י בודד (Undo מסיר רק את הפעולה האחרונה, וניקוי-דף
// מוחק הכל) - אותה תבנית מוכרת כמו מחיקת פריט ברשימות אחרות באפליקציה
function deleteEmojiFromCanvas(e) {
    e.stopPropagation();
    const idx = parseInt(e.currentTarget.dataset.strokeIndex, 10);
    if (Number.isNaN(idx)) return;
    canvasStrokes.splice(idx, 1);
    renderEmojiOverlay();
    saveCanvasData();
}

let draggingEmojiEl = null, draggingEmojiIndex = null;
function startEmojiDrag(e) {
    e.preventDefault();
    e.stopPropagation(); // לא מבעבע לקנבס שמתחת - לא רוצים שזה יתחיל גם שורטוק
    draggingEmojiEl = e.currentTarget;
    draggingEmojiIndex = parseInt(draggingEmojiEl.dataset.strokeIndex, 10);
    draggingEmojiEl.classList.add('dragging');
    document.addEventListener('pointermove', continueEmojiDrag);
    document.addEventListener('pointerup', endEmojiDrag);
}
function continueEmojiDrag(e) {
    if (!draggingEmojiEl) return;
    const overlay = document.getElementById('notebook-emoji-overlay');
    if (!overlay) return;
    const rect = overlay.getBoundingClientRect();
    const x = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
    const y = Math.min(1, Math.max(0, (e.clientY - rect.top) / rect.height));
    if (canvasStrokes[draggingEmojiIndex]) {
        canvasStrokes[draggingEmojiIndex].x = x;
        canvasStrokes[draggingEmojiIndex].y = y;
    }
    draggingEmojiEl.style.left = `${x * 100}%`;
    draggingEmojiEl.style.top = `${y * 100}%`;
}
function endEmojiDrag() {
    document.removeEventListener('pointermove', continueEmojiDrag);
    document.removeEventListener('pointerup', endEmojiDrag);
    if (draggingEmojiEl) draggingEmojiEl.classList.remove('dragging');
    const didDrag = draggingEmojiEl != null;
    draggingEmojiEl = null;
    draggingEmojiIndex = null;
    if (didDrag) saveCanvasData(); // פעם אחת בשחרור - לא בכל pointermove
}

// --- "היעדים שלי" (לשעבר לוח החזון) - מאחד את לוח החזון ואת היעד החודשי, לפי בקשה
// מפורשת ("לחבר את זה עם החזון... שאנשים יבינו"). כל יעד: כרטיס תמונה שמתהפך לצעדים,
// ועכשיו גם "למה זה חשוב לי", עד מתי (ספירה לאחור + בדיקת קצב, בהשראת Strides), פרס 🎁,
// ומדידת התקדמות לפי צעדים / מספר / משקל. יעד אחד בכל חודש יכול להיות 🎯 "יעד החודש"
// (פרימיום, כמו היעד החודשי שהוחלף) - מוצג ראשון, עם מסלול ההליכה, ובהצצה להיום ---
// תוכניות מוכנות - בספריית היעדים (goals-library.js)
let visionLatestWeight = null;
// אתגר ימים: סימוני "עמדתי היום" / משימות יומיות (vision_goal_checkins), וקישורי צעדים לשגרה שלי
let visionCheckinsCache = [];
let visionRoutineLinks = [];
// 👣 צעד קטן יומי שנוסף ל"השגרה שלי" (routine_items.vision_goal_id) - ✓ באחד מסמן גם בשני
let visionGoalRoutineLinks = [];
// הטאבים בשגרה (רק id / שם / ימים) - גם כש"השגרה שלי" עוד לא נפתחה, ר' routineTabAppliesOnDate
let visionRoutineTabsCache = [];

async function loadVisionGoals() {
    if (!supabaseClient || !currentUserId) return;
    const [goalsRes, milestonesRes] = await Promise.all([
        supabaseClient.from('vision_goals').select('*').eq('user_id', currentUserId).order('created_at', { ascending: true }),
        supabaseClient.from('vision_goal_milestones').select('*').eq('user_id', currentUserId).order('sort_order', { ascending: true }),
    ]);
    visionGoalsCache = goalsRes.data || [];
    visionMilestonesCache = milestonesRes.data || [];
    // סימוני "✓ עשיתי היום" / "עמדתי היום" של כל היעדים (אתגרי ימים, צעדים קטנים, 7 הימים האחרונים)
    const checkinGoalIds = visionGoalsCache.map(g => g.id);
    const [checkinsRes, linksRes, stepLinksRes, tabsRes] = await Promise.all([
        checkinGoalIds.length ? supabaseClient.from('vision_goal_checkins').select('*').eq('user_id', currentUserId).in('goal_id', checkinGoalIds) : Promise.resolve({ data: [] }),
        supabaseClient.from('routine_items').select('id, tab_id, time, vision_milestone_id').eq('user_id', currentUserId).not('vision_milestone_id', 'is', null),
        supabaseClient.from('routine_items').select('id, tab_id, time, vision_goal_id').eq('user_id', currentUserId).not('vision_goal_id', 'is', null),
        supabaseClient.from('routine_tabs').select('id, name, weekdays').eq('user_id', currentUserId),
        loadVisionStepEvents(),
    ]);
    visionCheckinsCache = checkinsRes.data || [];
    visionRoutineLinks = (linksRes.data || []).filter(r => r.vision_milestone_id);
    visionGoalRoutineLinks = (stepLinksRes.data || []).filter(r => r.vision_goal_id);
    visionRoutineTabsCache = tabsRes.data || [];
    if (visionGoalsCache.some(g => g.track_type === 'weight' && !g.is_achieved)) await refreshVisionLatestWeight();
    renderVisionGoalsList();
    renderPeekFocusGoal();
    // משימות היעדים (אתגר ימים, תזכורות) מוצגות בהצצה להיום - מתעדכנות כשהיעדים נטענים
    if (document.getElementById('today-tasks-list')) loadTodayTasks();
    // 🎯 תאריכי יעד בלוח החודשי
    refreshCalendarDeadlineMarks();
    // משקל שנרשם במקום אחר (מדדים / New Me) יכול להשלים יעד משקל
    checkWeightGoalsAchieved();
}

// --- 📅 צעדים מתוזמנים ביומן: משימות calendar_events שמקושרות לצעד (vision_milestone_id)
// מהיום והלאה - בשביל התווית ליד הצעד ("📅 5.10" / "🔁 כל ראשון") ---
let visionStepEventsCache = [];
async function loadVisionStepEvents() {
    if (!supabaseClient || !currentUserId) return;
    const { data } = await supabaseClient.from('calendar_events').select('id, event_date, recurrence_group_id, vision_milestone_id, is_completed')
        .eq('user_id', currentUserId).not('vision_milestone_id', 'is', null).gte('event_date', getLocalDateString()).order('event_date', { ascending: true });
    visionStepEventsCache = data || [];
}
// המופע הקרוב שעוד לא סומן + האם זו תזכורת שבועית
function visionStepScheduleFor(milestoneId) {
    const events = visionStepEventsCache.filter(e => e.vision_milestone_id === milestoneId && !e.is_completed);
    if (!events.length) return null;
    return { next: events[0].event_date, weekly: events.some(e => e.recurrence_group_id) };
}
function visionStepScheduleLabel(schedule) {
    const [y, m, d] = schedule.next.split('-').map(Number);
    const date = new Date(y, m - 1, d);
    if (schedule.weekly) return t('vision_step_schedule_weekly_on').replace('{day}', date.toLocaleDateString(currentLang, { weekday: 'long' }));
    return date.toLocaleDateString(currentLang, { day: 'numeric', month: 'numeric' });
}

async function refreshVisionLatestWeight() {
    const { data } = await supabaseClient.from('weight_tracker').select('weight_value').eq('user_id', currentUserId).order('weight_date', { ascending: false }).limit(1).maybeSingle();
    visionLatestWeight = data && data.weight_value != null ? Number(data.weight_value) : null;
}

function visionEsc(s) { return escapeHtmlForReport(s == null ? '' : String(s)); }
function visionFmt(n) { return (Math.round(Number(n) * 10) / 10).toLocaleString(currentLang); }
function visionIsFocus(goal) { return !goal.is_achieved && goal.focus_month === currentMonthKey(); }
function visionLastDayOfMonth() {
    const now = new Date();
    const d = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
// ליעד החודש בלי תאריך - סוף החודש הוא תאריך היעד
function visionEffectiveDeadline(goal) { return goal.target_date || (visionIsFocus(goal) ? visionLastDayOfMonth() : null); }
function visionDaysLeft(deadline) {
    if (!deadline) return null;
    const [y, m, d] = deadline.split('-').map(Number);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return Math.round((new Date(y, m - 1, d) - today) / 86400000);
}
function visionDaysLeftText(days) {
    if (days === null) return '';
    if (days > 1) return t('vision_days_left').replace('{n}', days);
    if (days === 1) return t('vision_day_left_one');
    if (days === 0) return t('vision_due_today');
    return t('vision_overdue');
}

// בידוד LTR (U+2066...U+2069): בעברית "7 / 12" הוצג הפוך כ-"12 / 7" - בלי תווים נסתרים בקוד
const visionLtr = s => String.fromCharCode(0x2066) + s + String.fromCharCode(0x2069);

// התקדמות לפי סוג המדידה: צעדים (תחנות שסומנו), מספר (למשל 7/12 ספרים) או משקל
// (לפי השקילה האחרונה, מנקודת ההתחלה אל היעד - ירידה או עלייה)
function visionGoalProgress(goal) {
    const type = goal.track_type || 'steps';
    if (type === 'days') {
        const target = Math.max(1, Number(goal.target_value) || 1);
        const done = visionDoneDays(goal).length;
        return { pct: Math.min(100, Math.round((done / target) * 100)), label: t('vision_days_progress').replace('{done}', Math.min(done, target)).replace('{total}', target), reached: done >= target };
    }
    if (type === 'number') {
        const target = Number(goal.target_value) || 0;
        const cur = Number(goal.current_value) || 0;
        const pct = target > 0 ? Math.min(100, Math.max(0, Math.round((cur / target) * 100))) : 0;
        return { pct, label: visionLtr(`${visionFmt(cur)} / ${visionFmt(target)}`) + (goal.unit ? ' ' + goal.unit : ''), reached: target > 0 && cur >= target };
    }
    if (type === 'weight') {
        const kg = t('monthly_goal_kg_unit');
        const target = goal.target_value != null ? Number(goal.target_value) : null;
        const cur = visionLatestWeight;
        if (cur === null || target === null) return { pct: 0, label: `— ${document.documentElement.dir === 'rtl' ? '←' : '→'} ${target === null ? '—' : visionFmt(target)} ${kg}`, reached: false };
        const start = goal.start_value != null ? Number(goal.start_value) : cur;
        const losing = start >= target;
        const reached = losing ? cur <= target : cur >= target;
        const pct = start === target ? (reached ? 100 : 0) : Math.min(100, Math.max(0, Math.round(((start - cur) / (start - target)) * 100)));
        const arrow = document.documentElement.dir === 'rtl' ? '←' : '→';
        return { pct, label: `${visionFmt(cur)} ${arrow} ${visionFmt(target)} ${kg}`, reached };
    }
    const milestones = visionMilestonesCache.filter(m => m.goal_id === goal.id);
    const total = milestones.length;
    const done = milestones.filter(m => m.is_done).length;
    return { pct: total ? Math.round((done / total) * 100) : 0, label: total ? visionLtr(`${done} / ${total}`) : '', reached: total > 0 && done === total };
}

// אתגר ימים: יום נחשב "עמדתי בו" כשכל המשימות היומיות סומנו באותו תאריך
// (או, אם אין משימות, כשסומן "עמדתי היום")
function visionDoneDays(goal) {
    const tasks = visionMilestonesCache.filter(m => m.goal_id === goal.id);
    const byDate = new Map();
    visionCheckinsCache.filter(ch => ch.goal_id === goal.id).forEach(ch => {
        if (!byDate.has(ch.checkin_date)) byDate.set(ch.checkin_date, new Set());
        byDate.get(ch.checkin_date).add(ch.milestone_id || 'day');
    });
    const dates = [];
    byDate.forEach((set, date) => { if (tasks.length ? tasks.every(tk => set.has(tk.id)) : set.has('day')) dates.push(date); });
    return dates.sort();
}
// רצף: ימים רצופים עד היום (אם היום עוד לא הושלם - עד אתמול)
function visionStreak(goal) {
    const done = new Set(visionGoalDayDates(goal));
    const key = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    if (!done.has(key(d))) d.setDate(d.getDate() - 1);
    let n = 0;
    while (done.has(key(d))) { n++; d.setDate(d.getDate() - 1); }
    return n;
}
function visionCheckedToday(goalId, milestoneId) {
    const today = getLocalDateString();
    return visionCheckinsCache.some(ch => ch.goal_id === goalId && (ch.milestone_id || null) === (milestoneId || null) && ch.checkin_date === today);
}
function visionRoutineLinkFor(milestoneId) { return visionRoutineLinks.find(r => r.vision_milestone_id === milestoneId) || null; }
function visionGoalRoutineLinkFor(goalId) { return visionGoalRoutineLinks.find(r => r.vision_goal_id === goalId) || null; }

// קצב (כמו "pace line" ב-Strides): משווים את אחוז ההתקדמות לאחוז הזמן שעבר עד התאריך
function visionPace(goal, pct, deadline) {
    if (!deadline || pct >= 100) return null;
    const [y, m, d] = deadline.split('-').map(Number);
    const end = new Date(y, m - 1, d, 23, 59, 59).getTime();
    let start = new Date(goal.created_at).getTime();
    if (!goal.target_date && visionIsFocus(goal)) {
        const now = new Date();
        start = Math.max(start, new Date(now.getFullYear(), now.getMonth(), 1).getTime());
    }
    const now = Date.now();
    if (now >= end || end <= start) return null;
    const expected = ((now - start) / (end - start)) * 100;
    if (expected < 10) return null;
    if (pct >= expected + 10) return 'ahead';
    if (pct >= expected - 10) return 'on_track';
    return 'behind';
}

// תגיות מתחת לשם היעד: 🎯 יעד החודש, כמה ימים נשארו, קצב (🚀 / ✅ / ⚠️) ורצף 🔥
function visionTagsHtml(goal, prog) {
    const tags = [];
    if (visionIsFocus(goal)) tags.push(`<span class="gv-tag is-focus">${visionEsc(t('vision_focus_ribbon'))}</span>`);
    if (!goal.is_achieved) {
        const deadline = visionEffectiveDeadline(goal);
        const days = visionDaysLeft(deadline);
        if (days !== null) {
            const cls = days < 0 ? ' is-overdue' : (days <= 3 ? ' is-soon' : '');
            tags.push(`<span class="gv-tag${cls}">📅 ${visionEsc(visionDaysLeftText(days))}</span>`);
        }
        const pace = visionPace(goal, prog.pct, deadline);
        const paceMap = { ahead: ['🚀', 'vision_pace_ahead', 'is-ahead'], on_track: ['✅', 'vision_pace_on_track', 'is-on-track'], behind: ['⚠️', 'vision_pace_behind', 'is-behind'] };
        if (pace) tags.push(`<span class="gv-tag ${paceMap[pace][2]}">${paceMap[pace][0]} ${visionEsc(t(paceMap[pace][1]))}</span>`);
        const streak = visionStreak(goal);
        if (streak >= 2) tags.push(`<span class="gv-tag is-streak">${visionEsc(t('vision_days_streak').replace('{n}', streak))}</span>`);
    }
    return tags.length ? `<div class="gv-tags">${tags.join('')}</div>` : '';
}

// --- 🎯 מסך "היעדים שלי" (עיצוב "מסע של צעדים", לפי בחירה מפורשת): פתק "לא 10" קבוע, הצעדים
// הקטנים של היום מכל היעדים, צ'יפ לכל יעד ושביל אבנים של היעד שנבחר - תחנות שעברו ✓, האבן של
// היום שזוהרת, מה שבהמשך והדגל. מתחת לשביל: "✓ עשיתי היום" עם 7 הימים האחרונים, התוכנית
// (תחנות / מונה / שקילה), למה, פרס ופעולות ---
let visionSelectedGoalId = null;
let visionAnimatePath = false;
let visionPathSeq = 0;
const VISION_SELECTED_KEY = 'weekwise_goals_selected';
const VISION_CHECK_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"></path></svg>';

function visionGoalIcon(goal) {
    if (goal && goal.icon) return goal.icon;
    const preset = goal ? VISION_GOAL_CATEGORY_PRESETS.find(c => c.key === goal.category) : null;
    return preset && preset.key !== 'other' ? preset.icon : '🎯';
}
// ימים שבהם עשו משהו ליעד: באתגר ימים - ימים שהושלמו; בשאר - סימוני "✓ עשיתי היום" (בלי תחנה)
function visionGoalDayDates(goal) {
    if (goal.track_type === 'days') return visionDoneDays(goal);
    return [...new Set(visionCheckinsCache.filter(ch => ch.goal_id === goal.id && !ch.milestone_id).map(ch => ch.checkin_date))].sort();
}
function visionJourneyDay(goal) {
    const start = new Date(goal.created_at);
    start.setHours(0, 0, 0, 0);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return Math.max(1, Math.round((today - start) / 86400000) + 1);
}
function visionSmallStepText(goal) { return (goal.reminder_text || '').trim() || null; }
function visionSmallStepFreqText(goal) {
    if (goal.reminder_freq === 'daily') return t('vision_reminder_daily');
    if (goal.reminder_freq === 'weekly') return t('vision_step_schedule_weekly_on').replace('{day}', new Date(2026, 9, 4 + (Number(goal.reminder_weekday) || 0)).toLocaleDateString(currentLang, { weekday: 'long' }));
    return '';
}
function visionSortedMilestones(goalId) {
    return visionMilestonesCache.filter(m => m.goal_id === goalId).sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
}
// יעד החודש ראשון, אחריו יעדים עם תאריך (הקרוב ביותר ראשון), ואז לפי סדר יצירה
function visionSortedActiveGoals() {
    return visionGoalsCache.filter(g => !g.is_achieved).sort((a, b) => {
        const fa = visionIsFocus(a), fb = visionIsFocus(b);
        if (fa !== fb) return fa ? -1 : 1;
        const da = visionEffectiveDeadline(a), db = visionEffectiveDeadline(b);
        if (da && db && da !== db) return da.localeCompare(db);
        if (da && !db) return -1;
        if (db && !da) return 1;
        return new Date(a.created_at) - new Date(b.created_at);
    });
}
function resolveSelectedVisionGoal() {
    let goal = visionGoalsCache.find(g => g.id === visionSelectedGoalId) || null;
    if (!goal) {
        let saved = null;
        try { saved = localStorage.getItem(VISION_SELECTED_KEY); } catch {}
        const active = visionSortedActiveGoals();
        goal = active.find(g => g.id === saved) || active[0] || null;
        visionSelectedGoalId = goal ? goal.id : null;
    }
    return goal;
}
function selectVisionGoal(goalId, scrollToPath) {
    visionSelectedGoalId = goalId;
    visionAnimatePath = true;
    const goal = visionGoalsCache.find(g => g.id === goalId);
    if (goal && !goal.is_achieved) { try { localStorage.setItem(VISION_SELECTED_KEY, goalId); } catch {} }
    renderVisionGoalsList();
    if (scrollToPath) {
        const scroll = document.getElementById('goals-view-scroll');
        const panel = document.getElementById('gv-goal');
        if (scroll && panel) scroll.scrollTo({ top: Math.max(0, panel.offsetTop - 12), behavior: 'smooth' });
    }
}

function renderVisionGoalsList() {
    const view = document.getElementById('vision-drawer-overlay');
    if (!view) return;
    const active = visionSortedActiveGoals();
    const achieved = visionGoalsCache.filter(g => g.is_achieved).sort((a, b) => new Date(b.achieved_at) - new Date(a.achieved_at));
    const empty = document.getElementById('vision-goals-empty');
    if (empty) empty.classList.toggle('hidden', active.length > 0);
    if (!active.length) renderVisionTemplates();
    renderGoalsTodayStrip(active);
    const selected = resolveSelectedVisionGoal();
    renderGoalsChips(active, selected);
    renderGoalPanel(selected);
    // "יעדים שכבשתי" - הסקשן מוצג רק כשיש לפחות הישג אחד
    const achievedSection = document.getElementById('vision-goals-achieved-section');
    const achievedList = document.getElementById('vision-goals-achieved-list');
    if (achievedSection) achievedSection.classList.toggle('hidden', !achieved.length);
    if (achievedList) {
        achievedList.innerHTML = '';
        achieved.forEach(goal => {
            const card = document.createElement('button');
            card.type = 'button';
            card.className = 'gv-achieved-card' + (selected && selected.id === goal.id ? ' selected' : '');
            const date = goal.achieved_at ? new Date(goal.achieved_at).toLocaleDateString(currentLang, { day: 'numeric', month: 'short', year: 'numeric' }) : '';
            card.innerHTML = `<span class="gv-achieved-trophy" aria-hidden="true">🏆</span><span class="gv-achieved-icon" aria-hidden="true">${visionEsc(visionGoalIcon(goal))}</span><span class="gv-achieved-name">${visionEsc(goal.title)}</span>${date ? `<span class="gv-achieved-date">${visionEsc(date)}</span>` : ''}`;
            card.onclick = () => selectVisionGoal(goal.id, true);
            achievedList.appendChild(card);
        });
    }
}

// --- הצעדים הקטנים של היום (אותם פריטים בדיוק כמו בהצצה להיום, ר' getPeekGoalTaskItems) - כרטיס
// לכל צעד עם ✓ מהיר; לחיצה על הטקסט פותחת את השביל של היעד ---
function renderGoalsTodayStrip(activeGoals) {
    const section = document.getElementById('gv-today');
    const list = document.getElementById('gv-today-list');
    const count = document.getElementById('gv-today-count');
    if (!section || !list) return;
    section.classList.toggle('hidden', !activeGoals.length);
    list.innerHTML = '';
    if (count) count.textContent = '';
    if (!activeGoals.length) return;
    const items = getPeekGoalTaskItems();
    if (!items.length) {
        const hint = document.createElement('div');
        hint.className = 'gv-today-empty';
        hint.textContent = t('gv_today_empty');
        list.appendChild(hint);
        return;
    }
    const doneCount = items.filter(it => it.done).length;
    if (count) count.textContent = doneCount === items.length ? t('gv_today_all_done') : visionLtr(`${doneCount} / ${items.length}`);
    items.forEach(item => list.appendChild(buildGoalsTodayCard(item)));
}
function buildGoalsTodayCard(item) {
    const card = document.createElement('div');
    card.className = 'gv-today-card' + (item.done ? ' is-done' : '');
    const check = document.createElement('button');
    check.type = 'button';
    check.className = 'gv-check';
    check.setAttribute('aria-pressed', item.done ? 'true' : 'false');
    check.setAttribute('aria-label', item.text);
    check.innerHTML = VISION_CHECK_SVG;
    check.onclick = (e) => {
        e.stopPropagation();
        // משוב מיידי - הרינדור המלא מגיע אחרי השמירה
        const next = !card.classList.contains('is-done');
        card.classList.toggle('is-done', next);
        check.setAttribute('aria-pressed', next ? 'true' : 'false');
        item.toggle(next);
    };
    const body = document.createElement('button');
    body.type = 'button';
    body.className = 'gv-today-body';
    body.innerHTML = `<span class="gv-today-text">${visionEsc(item.icon)} ${visionEsc(item.text)}</span>${item.tag ? `<span class="gv-today-tag">${visionEsc(item.tag)}</span>` : ''}`;
    body.onclick = () => { if (item.goalId) selectVisionGoal(item.goalId, true); };
    card.appendChild(check);
    card.appendChild(body);
    return card;
}

// צ'יפ לכל יעד פעיל (רק כשיש יותר מיעד אחד) - בוחרים איזה שביל לראות
function renderGoalsChips(activeGoals, selected) {
    const wrap = document.getElementById('gv-chips');
    if (!wrap) return;
    wrap.innerHTML = '';
    wrap.classList.toggle('hidden', activeGoals.length < 2);
    if (activeGoals.length < 2) return;
    activeGoals.forEach(goal => {
        const chip = document.createElement('button');
        chip.type = 'button';
        const isSel = !!(selected && selected.id === goal.id);
        chip.className = 'gv-chip-goal' + (isSel ? ' selected' : '');
        chip.setAttribute('aria-pressed', isSel ? 'true' : 'false');
        chip.innerHTML = `<span aria-hidden="true">${visionEsc(visionGoalIcon(goal))}</span><span class="gv-chip-name">${visionEsc(goal.title)}</span>${visionIsFocus(goal) ? '<span class="gv-chip-focus" aria-hidden="true">🎯</span>' : ''}`;
        chip.onclick = () => selectVisionGoal(goal.id);
        wrap.appendChild(chip);
    });
    const sel = wrap.querySelector('.gv-chip-goal.selected');
    if (sel) {
        const target = sel.offsetLeft - (wrap.clientWidth - sel.offsetWidth) / 2;
        wrap.scrollLeft = target;
    }
}

// מצב ריק: אריחי הנושאים של ספריית היעדים (goals-library.js) - לחיצה פותחת את הנושא בספרייה
function renderVisionTemplates() {
    const wrap = document.getElementById('vision-templates');
    if (!wrap || typeof GLIB_TOPICS === 'undefined') return;
    wrap.innerHTML = '';
    GLIB_TOPICS.forEach(tp => wrap.appendChild(glibBuildTopicTile(tp, () => openGoalsLibrary(tp.id))));
}

// 🎯 יעד החודש גם ב"הצצה להיום" - שורה קטנה עם התקדמות, לחיצה פותחת את היעדים
function renderPeekFocusGoal() {
    const el = document.getElementById('peek-focus-goal');
    if (!el) return;
    const goal = visionGoalsCache.find(visionIsFocus);
    if (!goal) { el.classList.add('hidden'); el.innerHTML = ''; return; }
    const prog = visionGoalProgress(goal);
    const daysText = visionDaysLeftText(visionDaysLeft(visionEffectiveDeadline(goal)));
    el.innerHTML = `
        <span class="peek-focus-goal-top"><span class="peek-focus-goal-label">${visionEsc(t('vision_focus_ribbon'))}</span>${daysText ? `<span class="peek-focus-goal-days">📅 ${visionEsc(daysText)}</span>` : ''}</span>
        <span class="peek-focus-goal-title">${visionEsc(goal.title)}</span>
        <span class="peek-focus-goal-bar"><span style="width:${prog.pct}%"></span></span>
        <span class="peek-focus-goal-meta"><span>${visionEsc(prog.label)}</span><span>${prog.pct}%</span></span>`;
    // נפתח ישר על השביל של יעד החודש
    el.onclick = () => { closeTodayPeekPanel(); openGoalsVisionDrawer(goal.id); };
    el.classList.remove('hidden');
}

// שורת תחנת-ביניים בודדת (גב הכרטיס) - פונקציה משותפת לבנייה הראשונית ולהוספה
// חיה מגב הכרטיס (addMilestoneToGoalFromCardBack), כדי לא לשכפל את אותה
// לוגיקה פעמיים. נבנה ב-createElement+closures (לא onclick="..." עם טקסט
// המשתמשת משורשר) כדי שכותרות עם גרש/מירכאות לא ישברו את ה-HTML
function buildVisionMilestoneRow(goalId, goalTitle, milestone) {
    const row = document.createElement('div');
    row.className = 'vision-milestone-row';

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = !!milestone.is_done;

    const span = document.createElement('span');
    span.textContent = milestone.title;
    if (milestone.is_done) span.classList.add('completed');

    checkbox.onchange = () => {
        span.classList.toggle('completed', checkbox.checked);
        toggleVisionMilestoneDone(milestone.id, goalId, checkbox.checked);
    };

    // 📅 תזמון הצעד ביומן (תאריך / כל שבוע עד שמסיימים) - אם כבר מתוזמן, מוצג מתי
    const schedule = milestone.is_done ? null : visionStepScheduleFor(milestone.id);
    const scheduleBtn = document.createElement('button');
    scheduleBtn.type = 'button';
    scheduleBtn.className = 'vision-milestone-add-today-btn' + (schedule ? ' is-scheduled' : '');
    scheduleBtn.title = t('vision_step_schedule_btn_title');
    scheduleBtn.setAttribute('aria-label', scheduleBtn.title);
    scheduleBtn.textContent = schedule ? `${schedule.weekly ? '🔁' : '📅'} ${visionStepScheduleLabel(schedule)}` : '📅';
    // צעד שכבר הושלם - אין מה לתזמן
    scheduleBtn.disabled = !!milestone.is_done;
    scheduleBtn.onclick = (e) => { e.stopPropagation(); openGoalStepSchedule(goalId, milestone.id); };

    row.appendChild(checkbox);
    row.appendChild(span);
    row.appendChild(buildVisionRoutineButton(milestone));
    row.appendChild(scheduleBtn);
    return row;
}

// 🔁 הוספת צעד/משימה יומית ל"השגרה שלי" - ואם כבר מקושר, מוצגת השעה שלו בשגרה
function buildVisionRoutineButton(milestone) {
    const link = visionRoutineLinkFor(milestone.id);
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'vision-routine-btn' + (link ? ' is-linked' : '');
    btn.textContent = link ? `🔁 ${(link.time || '').slice(0, 5)}` : '🔁';
    btn.title = t(link ? 'vision_routine_linked_title' : 'vision_routine_btn_title');
    btn.setAttribute('aria-label', btn.title);
    btn.onclick = (e) => { e.stopPropagation(); if (!link) openGoalRoutinePicker(milestone.id); };
    return btn;
}

// שורת משימה יומית באתגר ימים: ✓ להיום בלבד (מחר מתחיל מחדש) + 🔁 לשגרה
function buildVisionDayTaskRow(goal, milestone) {
    const row = document.createElement('div');
    row.className = 'vision-milestone-row';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = visionCheckedToday(goal.id, milestone.id);
    checkbox.disabled = !!goal.is_achieved;
    const span = document.createElement('span');
    span.textContent = milestone.title;
    if (checkbox.checked) span.classList.add('completed');
    checkbox.onchange = () => {
        span.classList.toggle('completed', checkbox.checked);
        toggleVisionDayCheck(goal.id, milestone.id, checkbox.checked);
    };
    row.appendChild(checkbox);
    row.appendChild(span);
    row.appendChild(buildVisionRoutineButton(milestone));
    return row;
}

// --- הפאנל של היעד שנבחר: כותרת (באנר כשיש תמונה), השביל, כרטיס "עשיתי היום", התוכנית, למה,
// פרס ופעולות. יעד שהושג מוצג עם השביל כולו עד הגביע 🏆 ---
function renderGoalPanel(goal) {
    const panel = document.getElementById('gv-goal');
    if (!panel) return;
    panel.innerHTML = '';
    panel.classList.toggle('hidden', !goal);
    if (!goal) { visionAnimatePath = false; return; }
    const prog = visionGoalProgress(goal);
    const track = goal.track_type || 'steps';
    const milestones = visionSortedMilestones(goal.id);

    const head = document.createElement('div');
    head.className = 'gv-goal-head' + (goal.image_url ? ' has-image' : '');
    if (goal.image_url) head.style.setProperty('--gv-goal-image', `url("${String(goal.image_url).replace(/"/g, '%22')}")`);
    let meta1;
    if (goal.is_achieved) {
        const date = goal.achieved_at ? new Date(goal.achieved_at).toLocaleDateString(currentLang, { day: 'numeric', month: 'long', year: 'numeric' }) : '';
        meta1 = `🏆 ${t('gv_achieved_on').replace('{date}', date)}`;
    } else {
        meta1 = t('gv_journey_day').replace('{n}', visionJourneyDay(goal));
    }
    let meta2 = prog.label;
    if (track === 'steps') meta2 = milestones.length ? t('gv_stations_progress').replace('{done}', milestones.filter(m => m.is_done).length).replace('{total}', milestones.length) : '';
    head.innerHTML = `
        <div class="gv-goal-title-row"><span class="gv-goal-icon" aria-hidden="true">${visionEsc(visionGoalIcon(goal))}</span><h3 class="gv-goal-title">${visionEsc(goal.title)}</h3></div>
        <div class="gv-meta"><span>${visionEsc(meta1)}</span>${meta2 ? `<span>${visionEsc(meta2)}</span>` : ''}</div>
        ${visionTagsHtml(goal, prog)}`;
    panel.appendChild(head);

    panel.appendChild(buildGoalPath(goal, milestones, prog, { animate: visionAnimatePath }));
    visionAnimatePath = false;
    if (!goal.is_achieved) panel.appendChild(buildGoalActionCard(goal, milestones));
    const plan = buildGoalPlan(goal, milestones, prog);
    if (plan) panel.appendChild(plan);
    if (goal.why) panel.appendChild(buildGoalNoteRow('gv-why', '💭', t('vision_why_label'), goal.why));
    if (goal.reward) panel.appendChild(buildGoalNoteRow('gv-reward', '🎁', t('gv_reward_label'), goal.reward));
    panel.appendChild(buildGoalActions(goal));
}

function buildGoalNoteRow(cls, icon, label, text) {
    const row = document.createElement('div');
    row.className = `gv-note-row ${cls}`;
    row.innerHTML = `<span class="gv-note-row-icon" aria-hidden="true">${icon}</span><span><span class="gv-note-row-label">${visionEsc(label)}</span>${visionEsc(text)}</span>`;
    return row;
}

// מודל השביל: אבן לכל תחנה (תחנות) / יום (אתגר ימים) / יחידה או שמינית מהיעד (ספירה) / שמינית
// מהדרך (משקל). current = האבן הראשונה שעוד לא הושלמה (-1 כשהכול הושלם)
function visionPathModel(goal, milestones, prog) {
    const track = goal.track_type || 'steps';
    let stones = [];
    let flag = goal.title;
    if (track === 'steps') {
        stones = milestones.map((m, i) => ({ num: i + 1, title: m.title, done: !!m.is_done, milestoneId: m.id }));
    } else if (track === 'days') {
        const target = Math.max(1, Math.min(365, Number(goal.target_value) || 1));
        const done = Math.min(visionDoneDays(goal).length, target);
        stones = Array.from({ length: target }, (_, i) => ({ num: i + 1, done: i < done }));
        flag = t('gv_flag_days').replace('{n}', target);
    } else if (track === 'number') {
        const target = Number(goal.target_value) || 0;
        const cur = Number(goal.current_value) || 0;
        if (target > 0 && Number.isInteger(target) && target <= 40) {
            stones = Array.from({ length: target }, (_, i) => ({ num: i + 1, done: cur >= i + 1 }));
        } else if (target > 0) {
            // יעד גדול (למשל 100 ק״מ) - 6 אבנים, כל אחת שישית מהדרך, כך שכל השביל נראה בלי קיצור
            stones = Array.from({ length: 6 }, (_, i) => {
                const v = (target * (i + 1)) / 6;
                return { num: Math.round(v * 10) / 10, done: cur >= v - 1e-9 };
            });
        }
        flag = `${visionFmt(target)}${goal.unit ? ' ' + goal.unit : ''}`;
    } else if (track === 'weight') {
        stones = Array.from({ length: 6 }, (_, i) => ({ num: null, done: prog.pct >= ((i + 1) / 6) * 100 - 0.01 }));
        if (goal.target_value != null) flag = `${visionFmt(goal.target_value)} ${t('monthly_goal_kg_unit')}`;
    }
    if (goal.is_achieved) stones.forEach(s => { s.done = true; });
    return { stones, current: stones.findIndex(s => !s.done), flag, track };
}

// הבועה ליד האבן של היום: מה עושים עכשיו (הצעד הקטן / התחנה הבאה / היום באתגר) + פעולה מהירה
function visionPathBubble(goal, model, milestones, isStart) {
    const step = visionSmallStepText(goal);
    if (isStart) {
        return {
            label: step ? t('gv_step_today') : '', text: step || t('gv_add_first_station'),
            action: { text: t('gv_add_station_btn'), run: () => { const input = document.querySelector('#gv-goal .gv-plan .gv-add-row input'); if (input) { input.scrollIntoView({ block: 'center', behavior: 'smooth' }); input.focus({ preventScroll: true }); } } },
        };
    }
    if (model.track === 'steps') {
        const st = model.stones[model.current];
        if (!st) return null;
        return { label: t('gv_next_station'), text: st.title, sub: step ? `👣 ${step}` : '', action: { text: t('gv_station_done_btn'), run: () => toggleVisionMilestoneDone(st.milestoneId, goal.id, true) } };
    }
    if (model.track === 'days') {
        const n = model.current + 1;
        if (visionDoneDays(goal).includes(getLocalDateString())) return { label: t('gv_day_n').replace('{n}', n), text: t('gv_tomorrow_continue') };
        return { label: t('gv_today_day_n').replace('{n}', n), text: milestones.length ? milestones.map(m => m.title).join(' · ') : goal.title };
    }
    if (model.track === 'number') {
        const label = visionGoalProgress(goal).label;
        return { label: step ? t('gv_step_today') : t('gv_progress_title'), text: step || label, sub: step ? label : '', action: { text: '+1', aria: t('vision_quick_add_title'), run: () => adjustVisionGoalNumber(goal.id, 1) } };
    }
    const now = visionLatestWeight != null ? t('gv_weight_now').replace('{w}', visionFmt(visionLatestWeight)) : t('vision_weight_no_data');
    return step ? { label: t('gv_step_today'), text: step, sub: now } : { label: t('gv_progress_title'), text: now };
}

// השביל עצמו: SVG מתפתל (מסלול דהוי + החלק שכבר עברו בגרדיאנט) ואבנים מעליו. ארוך מדי? רואים
// חלון סביב היום, עם "✓ N" למה שמאחור ו-"+N" למה שנשאר. compact = הדוגמה בסיור
function buildGoalPath(goal, milestones, prog, opts = {}) {
    const model = visionPathModel(goal, milestones, prog);
    const L = model.stones.length;
    const cur = model.current;
    const MAX = 6;
    let start = 0;
    let end = L - 1;
    if (L > MAX) {
        const c = cur === -1 ? L - 1 : cur;
        start = Math.max(0, c - 2);
        end = Math.min(L - 1, start + MAX - 1);
        start = Math.max(0, end - MAX + 1);
    }
    const nodes = [];
    if (!L) nodes.push({ kind: goal.is_achieved ? 'done' : 'start', stone: { title: '' } });
    if (L && start > 0) nodes.push({ kind: 'sum-done', n: start });
    for (let i = start; L && i <= end; i++) {
        const s = model.stones[i];
        nodes.push({ kind: i === cur ? 'current' : (s.done ? 'done' : 'future'), stone: s });
    }
    if (L && end < L - 1) nodes.push({ kind: 'sum-future', n: L - 1 - end });
    nodes.push({ kind: 'flag' });

    const compact = !!opts.compact;
    const k = compact ? 0.8 : 1;
    const GAP = compact ? 54 : 70;
    const PAD_T = compact ? 34 : 46;
    const PAD_B = compact ? 30 : 40;
    const rtl = document.documentElement.dir === 'rtl';
    // האבן של היום תמיד בצד (שם יש מקום לבועה), והשביל מתפתל ממנה בגל
    let focusIdx = nodes.findIndex(n => n.kind === 'current' || n.kind === 'start');
    const hasBubble = focusIdx !== -1 && !goal.is_achieved && !opts.noBubble;
    const walkedTo = focusIdx === -1 ? nodes.length - 1 : focusIdx;
    if (focusIdx === -1) focusIdx = nodes.length - 1;
    // מרווח נוסף מעל ומתחת לאבן של היום - שהבועה לא תעלה על האבנים השכנות
    const EXTRA = hasBubble ? (compact ? 14 : 24) : 0;
    const gapAfter = i => GAP + (i === focusIdx || i + 1 === focusIdx ? EXTRA : 0);
    let H = PAD_T + PAD_B;
    for (let i = 0; i < nodes.length - 1; i++) H += gapAfter(i);
    let yCursor = H - PAD_B;
    const pts = nodes.map((n, i) => {
        let x = n.kind === 'flag' ? 50 : 50 + 24 * Math.sin((i - focusIdx + 1) * Math.PI / 2);
        if (rtl) x = 100 - x;
        const y = yCursor;
        yCursor -= gapAfter(i);
        return { x: Math.round(x * 10) / 10, y };
    });
    const f = v => Math.round(v * 10) / 10;
    const segs = [];
    for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || pts[i + 1];
        segs.push(`C ${f(p1.x + (p2.x - p0.x) / 6)} ${f(p1.y + (p2.y - p0.y) / 6)}, ${f(p2.x - (p3.x - p1.x) / 6)} ${f(p2.y - (p3.y - p1.y) / 6)}, ${f(p2.x)} ${f(p2.y)}`);
    }
    // "זנב" קצר מתחתית המסגרת אל האבן הראשונה - המסע התחיל עוד קודם
    const head = `M ${f(pts[0].x)} ${H - 8} L ${f(pts[0].x)} ${f(pts[0].y)}`;
    const full = `${head} ${segs.join(' ')}`;
    const firstDone = nodes[0].kind === 'done' || nodes[0].kind === 'sum-done';
    const walked = walkedTo > 0 ? `${head} ${segs.slice(0, walkedTo).join(' ')}` : (firstDone ? head : '');
    const gid = `gvWalk${++visionPathSeq}`;

    const wrap = document.createElement('div');
    wrap.className = 'gv-path' + (compact ? ' is-compact' : '') + (opts.animate ? ' draw-in' : '') + (goal.is_achieved ? ' is-achieved' : '');
    wrap.style.height = `${H}px`;
    wrap.innerHTML = `<svg class="gv-path-svg" viewBox="0 0 100 ${H}" preserveAspectRatio="none" aria-hidden="true" focusable="false"><path class="gv-path-track" d="${full}" vector-effect="non-scaling-stroke"></path></svg>`
        + (walked ? `<svg class="gv-path-svg gv-path-walked" viewBox="0 0 100 ${H}" preserveAspectRatio="none" aria-hidden="true" focusable="false"><defs><linearGradient id="${gid}" x1="0" y1="${H}" x2="0" y2="${f(pts[walkedTo].y)}" gradientUnits="userSpaceOnUse"><stop offset="0" style="stop-color: var(--accent-purple)"></stop><stop offset="1" style="stop-color: var(--accent-pink)"></stop></linearGradient></defs><path class="gv-path-walk" d="${walked}" stroke="url(#${gid})" vector-effect="non-scaling-stroke"></path></svg>` : '');

    // צד התווית/הבועה: הרחק מהמרכז, ובאבן שבמרכז - הרחק מהשכנה
    const sideOf = i => {
        const x = pts[i].x;
        if (Math.abs(x - 50) > 1) return x > 50 ? 'left' : 'right';
        const nb = pts[i + 1] || pts[i - 1];
        return nb && nb.x > 50 ? 'left' : 'right';
    };
    const placeBeside = (el, i, r, cap) => {
        const p = pts[i];
        const side = sideOf(i);
        el.classList.add(`is-${side}`);
        el.style.top = `${p.y}px`;
        const room = side === 'right' ? `calc(${f(100 - p.x)}% - ${r + 14}px)` : `calc(${f(p.x)}% - ${r + 14}px)`;
        if (side === 'right') el.style.left = `calc(${f(p.x)}% + ${r + 10}px)`;
        else el.style.right = `calc(${f(100 - p.x)}% + ${r + 10}px)`;
        el.style.maxWidth = cap ? `min(${room}, ${cap}px)` : room;
    };
    const radius = { done: 21, future: 19, current: 30, start: 30, flag: 27 };
    const lastIdx = Math.max(1, nodes.length - 1);
    nodes.forEach((n, i) => {
        const p = pts[i];
        const node = document.createElement('span');
        node.className = 'gv-node';
        node.style.left = `${p.x}%`;
        node.style.top = `${p.y}px`;
        node.style.setProperty('--k', i);
        let label = '';
        if (n.kind === 'done') {
            node.innerHTML = `<span class="gv-stone is-done" style="--mix: ${Math.round((i / lastIdx) * 100)}%">${VISION_CHECK_SVG}</span>`;
            label = n.stone.title || '';
        } else if (n.kind === 'future') {
            const num = n.stone.num == null ? '' : (model.track === 'number' ? visionFmt(n.stone.num) : String(n.stone.num));
            node.innerHTML = `<span class="gv-stone is-future">${visionEsc(num)}</span>`;
            label = n.stone.title || '';
        } else if (n.kind === 'sum-done') {
            node.innerHTML = `<span class="gv-stone is-sum is-done" style="--mix: 0%">✓ ${visionLtr(String(n.n))}</span>`;
        } else if (n.kind === 'sum-future') {
            node.innerHTML = `<span class="gv-stone is-sum is-future">${visionLtr('+' + n.n)}</span>`;
        } else if (n.kind === 'current' || n.kind === 'start') {
            node.innerHTML = `<span class="gv-stone is-current">${visionEsc(visionGoalIcon(goal))}</span>`;
        } else {
            node.innerHTML = `<span class="gv-flag${goal.is_achieved ? ' is-reached' : ''}">🏆</span>`;
            label = model.flag;
        }
        wrap.appendChild(node);
        if (label) {
            const lab = document.createElement('span');
            lab.className = 'gv-label' + (n.kind === 'flag' ? ' is-flag' : '') + (n.kind === 'done' ? ' is-done' : '');
            lab.textContent = label;
            placeBeside(lab, i, Math.round((radius[n.kind] || 20) * k), 0);
            wrap.appendChild(lab);
        }
        if ((n.kind === 'current' || n.kind === 'start') && !goal.is_achieved && !opts.noBubble) {
            const b = visionPathBubble(goal, model, milestones, n.kind === 'start');
            if (!b) return;
            const bubble = document.createElement('div');
            bubble.className = 'gv-bubble';
            if (b.label) bubble.insertAdjacentHTML('beforeend', `<span class="gv-bubble-label">${visionEsc(b.label)}</span>`);
            bubble.insertAdjacentHTML('beforeend', `<span class="gv-bubble-text">${visionEsc(b.text)}</span>`);
            if (b.sub) bubble.insertAdjacentHTML('beforeend', `<span class="gv-bubble-sub">${visionEsc(b.sub)}</span>`);
            if (b.action && !opts.demo) {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'gv-bubble-btn';
                btn.textContent = b.action.text;
                if (b.action.aria) btn.setAttribute('aria-label', b.action.aria);
                btn.onclick = (e) => { e.stopPropagation(); b.action.run(); };
                bubble.appendChild(btn);
            }
            placeBeside(bubble, i, Math.round(30 * k), compact ? 190 : 240);
            wrap.appendChild(bubble);
        }
    });
    return wrap;
}

// --- כרטיס "היום": באתגר ימים - המשימות של היום (או ✓ אחד); בשאר - הצעד הקטן ו-"✓ עשיתי היום".
// מתחת - 7 הימים האחרונים ---
function buildGoalActionCard(goal, milestones) {
    const card = document.createElement('div');
    card.className = 'gv-action-card';
    const track = goal.track_type || 'steps';
    const head = document.createElement('div');
    head.className = 'gv-step-head';
    if (track === 'days') {
        head.innerHTML = `<span>${visionEsc(t(milestones.length ? 'vision_days_today_title' : 'gv_step_today'))}</span>`;
        card.appendChild(head);
        if (milestones.length) {
            const list = document.createElement('div');
            list.className = 'gv-day-tasks';
            milestones.forEach(m => list.appendChild(buildVisionDayTaskRow(goal, m)));
            card.appendChild(list);
        } else {
            const doneToday = visionDoneDays(goal).includes(getLocalDateString());
            card.appendChild(buildGoalDidButton(doneToday, t(doneToday ? 'vision_days_today_done' : 'vision_days_today_btn'), () => toggleVisionDayCheck(goal.id, null, !doneToday)));
        }
        card.appendChild(buildGoalAddRow(t('vision_days_task_placeholder'), input => addMilestoneToGoalFromCardBack(goal.id, input)));
    } else {
        const step = visionSmallStepText(goal);
        const freq = goal.reminder_freq ? visionSmallStepFreqText(goal) : '';
        head.innerHTML = `<span>👣 ${visionEsc(t('gv_small_step_label'))}</span>${freq ? `<span class="gv-step-freq">${visionEsc(freq)}</span>` : ''}`;
        card.appendChild(head);
        if (step) {
            card.insertAdjacentHTML('beforeend', `<div class="gv-step-text">${visionEsc(step)}</div><div class="gv-step-hint">${visionEsc(t('gv_small_ok'))}</div>`);
        } else {
            const setBtn = document.createElement('button');
            setBtn.type = 'button';
            setBtn.className = 'gv-set-step-btn';
            setBtn.textContent = t('gv_add_small_step');
            setBtn.onclick = () => openVisionGoalModal(goal.id, null, { focusSmallStep: true });
            card.appendChild(setBtn);
        }
        // 🔁 הצעד הקטן היומי ב"השגרה שלי" - ואם כבר שם, השעה שלו (✓ באחד מסמן גם בשני)
        const routineLink = visionGoalRoutineLinkFor(goal.id);
        if (routineLink) {
            card.insertAdjacentHTML('beforeend', `<span class="gv-step-routine is-linked">🔁 ${visionEsc(t('vision_routine_linked_title'))} · ${visionEsc((routineLink.time || '').slice(0, 5))}</span>`);
        } else if (step && goal.reminder_freq === 'daily') {
            const routineBtn = document.createElement('button');
            routineBtn.type = 'button';
            routineBtn.className = 'gv-step-routine';
            routineBtn.textContent = `🔁 ${t('vision_routine_btn_title')}`;
            routineBtn.onclick = () => openGoalRoutinePicker(null, goal.id);
            card.appendChild(routineBtn);
        }
        const doneToday = visionCheckedToday(goal.id, null);
        card.appendChild(buildGoalDidButton(doneToday, t(doneToday ? 'gv_did_today_done' : 'gv_did_today_btn'), () => toggleGoalReminderCheck(goal.id, !doneToday)));
    }
    card.appendChild(buildGoalWeek(goal));
    return card;
}

function buildGoalDidButton(done, label, onToggle) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'gv-did-btn' + (done ? ' is-done' : '');
    btn.setAttribute('aria-pressed', done ? 'true' : 'false');
    btn.textContent = label;
    btn.onclick = () => {
        // ניצוצות קטנים רק כשמסמנים (לא כשמבטלים) - על המסך עצמו, כי הכרטיס מצטייר מחדש
        const view = document.getElementById('vision-drawer-overlay');
        if (!done && view && typeof spawnGentleConfettiBurst === 'function') {
            const vr = view.getBoundingClientRect();
            const br = btn.getBoundingClientRect();
            spawnGentleConfettiBurst(view, 18, br.left - vr.left + br.width / 2, br.top - vr.top + br.height / 2);
        }
        onToggle();
    };
    return btn;
}

// 7 הימים האחרונים - נקודה מלאה בכל יום שעשו משהו ליעד (בלי "רצף נשבר": לא צריך 10)
function buildGoalWeek(goal) {
    const done = new Set(visionGoalDayDates(goal));
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    d.setDate(d.getDate() - 6);
    let count = 0;
    const days = [];
    for (let i = 0; i < 7; i++) {
        const key = getLocalDateString(d);
        const isDone = done.has(key);
        if (isDone) count++;
        days.push(`<span class="gv-week-day${isDone ? ' is-done' : ''}${i === 6 ? ' is-today' : ''}"><span class="gv-week-dot"></span>${visionEsc(d.toLocaleDateString(currentLang, { weekday: 'narrow' }))}</span>`);
        d.setDate(d.getDate() + 1);
    }
    const row = document.createElement('div');
    row.className = 'gv-week';
    row.setAttribute('role', 'img');
    row.setAttribute('aria-label', `${t('gv_week_label')}: ${count} / 7`);
    row.innerHTML = `<span class="gv-week-label" aria-hidden="true">${visionEsc(t('gv_week_label'))}</span><span class="gv-week-days" aria-hidden="true">${days.join('')}</span>`;
    return row;
}

function buildGoalAddRow(placeholder, onAdd) {
    const row = document.createElement('div');
    row.className = 'gv-add-row';
    const input = document.createElement('input');
    input.type = 'text';
    input.maxLength = 120;
    input.placeholder = placeholder;
    input.setAttribute('aria-label', placeholder);
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn-secondary';
    btn.textContent = t('vision_goal_milestone_add_btn');
    btn.onclick = () => onAdd(input);
    input.onkeydown = (e) => { if (e.key === 'Enter') { e.preventDefault(); onAdd(input); } };
    row.appendChild(input);
    row.appendChild(btn);
    return row;
}

// התוכנית: תחנות (עם 🔁 לשגרה ו-📅 ליומן) / מונה −/+ / משקל עם שקילה מהירה
function buildGoalPlan(goal, milestones, prog) {
    const track = goal.track_type || 'steps';
    if (track === 'days') return null;
    const wrap = document.createElement('div');
    wrap.className = 'gv-plan';
    const title = document.createElement('h4');
    title.className = 'gv-plan-title';
    wrap.appendChild(title);
    if (track === 'steps') {
        title.textContent = t('gv_plan_title');
        if (milestones.length) milestones.forEach(m => wrap.appendChild(buildVisionMilestoneRow(goal.id, goal.title, m)));
        else wrap.insertAdjacentHTML('beforeend', `<p class="gv-plan-empty">${visionEsc(t('vision_goal_no_milestones_hint'))}</p>`);
        if (!goal.is_achieved) wrap.appendChild(buildGoalAddRow(t('vision_goal_milestone_input_placeholder'), input => addMilestoneToGoalFromCardBack(goal.id, input)));
    } else if (track === 'number') {
        title.textContent = t('gv_progress_title');
        const row = document.createElement('div');
        row.className = 'gv-counter';
        const minus = document.createElement('button');
        minus.type = 'button';
        minus.className = 'gv-counter-btn';
        minus.textContent = '−';
        minus.setAttribute('aria-label', '−1');
        minus.disabled = goal.is_achieved || (Number(goal.current_value) || 0) <= 0;
        minus.onclick = () => adjustVisionGoalNumber(goal.id, -1);
        const value = document.createElement('span');
        value.className = 'gv-counter-value';
        value.textContent = prog.label;
        const plus = document.createElement('button');
        plus.type = 'button';
        plus.className = 'gv-counter-btn is-plus';
        plus.textContent = '+';
        plus.setAttribute('aria-label', t('vision_quick_add_title'));
        plus.disabled = !!goal.is_achieved;
        plus.onclick = () => adjustVisionGoalNumber(goal.id, 1);
        row.appendChild(minus);
        row.appendChild(value);
        row.appendChild(plus);
        wrap.appendChild(row);
    } else if (track === 'weight') {
        title.textContent = t('gv_progress_title');
        wrap.insertAdjacentHTML('beforeend', `<div class="gv-weigh-info">⚖️ ${visionEsc(prog.label)}</div><p class="vision-goal-field-hint">${visionEsc(t(visionLatestWeight === null ? 'vision_weight_no_data' : 'vision_weight_hint'))}</p>`);
        if (!goal.is_achieved) {
            const row = document.createElement('div');
            row.className = 'gv-add-row';
            const input = document.createElement('input');
            input.type = 'number';
            input.inputMode = 'decimal';
            input.step = '0.1';
            input.min = '0';
            input.placeholder = t('gv_weigh_ph');
            input.setAttribute('aria-label', input.placeholder);
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'btn-secondary';
            btn.textContent = t('vision_goal_save_btn');
            btn.onclick = async () => {
                const v = parseFloat(input.value);
                if (!(v > 0)) { input.focus(); return; }
                btn.disabled = true;
                const res = await insertWeightRecord(v, getLocalDateString(), '');
                btn.disabled = false;
                if (res && res.error) { showAppToast(t('error_adding_item') + res.error.message, 'error'); return; }
                showAppToast(t('gv_weigh_saved'));
            };
            row.appendChild(input);
            row.appendChild(btn);
            wrap.appendChild(row);
        }
    }
    return wrap;
}

// פעולות: עריכה, 🎯 יעד החודש, סימון כהושג, מחיקה
function buildGoalActions(goal) {
    const row = document.createElement('div');
    row.className = 'gv-goal-actions';
    const add = (cls, html, onClick, aria) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = `gv-action-btn ${cls}`;
        b.innerHTML = html;
        if (aria) { b.setAttribute('aria-label', aria); b.title = aria; }
        b.onclick = onClick;
        row.appendChild(b);
    };
    add('is-edit', `${EDIT_ICON_SVG}<span>${visionEsc(t('edit_btn'))}</span>`, () => openVisionGoalModal(goal.id));
    if (!goal.is_achieved) {
        const focus = visionIsFocus(goal);
        add(focus ? 'is-focus-on' : 'is-focus', `<span aria-hidden="true">🎯</span><span>${visionEsc(t(focus ? 'vision_focus_unpin_title' : 'vision_focus_pin_title'))}${!focus && !isPremiumUser ? ' ⭐' : ''}</span>`, () => toggleVisionFocus(goal.id));
        add('is-achieve', visionEsc(t('vision_mark_achieved_btn')), () => setVisionGoalAchieved(goal.id));
    }
    add('is-delete', '<span aria-hidden="true">🗑️</span>', () => deleteVisionGoal(goal.id), t('vision_goal_delete_btn_title'));
    return row;
}

// ההתקדמות משפיעה על כמה מקומות במסך (השביל, התגיות, הצעדים של היום) - מרנדרים מחדש
function updateVisionCardProgressDisplay() {
    renderVisionGoalsList();
    renderPeekFocusGoal();
}

async function toggleVisionMilestoneDone(milestoneId, goalId, checked) {
    if (!supabaseClient || !currentUserId) return;
    await supabaseClient.from('vision_goal_milestones').update({ is_done: checked }).eq('id', milestoneId);
    const m = visionMilestonesCache.find(x => x.id === milestoneId);
    if (m) m.is_done = checked;
    updateVisionCardProgressDisplay(goalId);
    // סנכרון הפוך: ✓ ביעד מסמן גם את המשימות ביומן שמקושרות לצעד (ובתזכורת שבועית - מוחק את השבועות הבאים)
    await syncStepEventsDone(milestoneId, checked);
    await syncRoutineChecksForMilestone(milestoneId, checked, getLocalDateString());
    await checkAndMarkGoalAchieved(goalId);
}

// ✓ על משימה יומית מקושרת → התחנה בלוח החזון מסומנת/מבוטלת בהתאם
async function setVisionMilestoneDoneFromTask(milestoneId, checked) {
    const { data: m } = await supabaseClient.from('vision_goal_milestones').update({ is_done: checked }).eq('id', milestoneId).select('goal_id').maybeSingle();
    const cached = visionMilestonesCache.find(x => x.id === milestoneId);
    if (cached) cached.is_done = checked;
    // שאר המשימות של הצעד (מופעים קודמים / השבועות הבאים בתזכורת שבועית) מתיישרות לפי ה-✓
    await syncStepEventsDone(milestoneId, checked);
    if (m && m.goal_id) {
        renderVisionGoalsList();
        await checkAndMarkGoalAchieved(m.goal_id);
    }
}

// מחיקת תחנה מלוח החזון (כשמוחקים את המשימה היומית שלה). ה-FK עם ON DELETE CASCADE
// מוחק גם את כל המשימות האחרות שמקושרות אליה
async function deleteVisionMilestoneEverywhere(milestoneId) {
    const cached = visionMilestonesCache.find(x => x.id === milestoneId);
    await supabaseClient.from('vision_goal_milestones').delete().eq('id', milestoneId).eq('user_id', currentUserId);
    visionMilestonesCache = visionMilestonesCache.filter(x => x.id !== milestoneId);
    renderVisionGoalsList();
    if (cached && cached.goal_id) updateVisionCardProgressDisplay(cached.goal_id);
}

// היעד מסומן "הושג" לצמיתות כשמגיעים אליו: כל הצעדים סומנו (צעדים), המספר הגיע ליעד
// (מספר) או השקילה האחרונה הגיעה למשקל היעד (משקל). לא מתאפס אם תחנה מבוטלת אחר כך
// (לפי בקשה מפורשת, "תמיד שם"). נקראת גם מסימון משימת "לימודים" מקושרת
async function checkAndMarkGoalAchieved(goalId) {
    if (!supabaseClient || !goalId) return;
    let goal = visionGoalsCache.find(g => g.id === goalId);
    if (!goal) {
        const { data } = await supabaseClient.from('vision_goals').select('*').eq('id', goalId).maybeSingle();
        if (!data) return;
        goal = data;
        visionGoalsCache.push(goal);
    }
    if (goal.is_achieved) return;
    if ((goal.track_type || 'steps') === 'steps') {
        const { data: milestones } = await supabaseClient.from('vision_goal_milestones').select('id, is_done').eq('goal_id', goalId);
        if (!milestones || !milestones.length || !milestones.every(m => m.is_done)) return;
    } else if (!visionGoalProgress(goal).reached) {
        return;
    }
    await setVisionGoalAchieved(goalId);
}

async function setVisionGoalAchieved(goalId) {
    const goal = visionGoalsCache.find(g => g.id === goalId);
    if (!goal || goal.is_achieved) return;
    const achievedAt = new Date().toISOString();
    const { error } = await supabaseClient.from('vision_goals').update({ is_achieved: true, achieved_at: achievedAt }).eq('id', goalId);
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    goal.is_achieved = true;
    goal.achieved_at = achievedAt;
    renderVisionGoalsList();
    renderPeekFocusGoal();
    celebrateGoalAchieved(goal);
}

async function adjustVisionGoalNumber(goalId, delta) {
    const goal = visionGoalsCache.find(g => g.id === goalId);
    if (!goal || goal.is_achieved) return;
    const next = Math.max(0, Math.round(((Number(goal.current_value) || 0) + delta) * 10) / 10);
    goal.current_value = next;
    renderVisionGoalsList();
    renderPeekFocusGoal();
    await supabaseClient.from('vision_goals').update({ current_value: next }).eq('id', goalId);
    if (delta > 0) autoCheckGoalReminder(goal);
    await checkAndMarkGoalAchieved(goalId);
}

// 🎯 יעד החודש (פרימיום) - רק יעד אחד בכל חודש; בחירה ביעד אחר מחליפה אותו
async function toggleVisionFocus(goalId) {
    if (!isPremiumUser) { openPremiumUpgradeModal(); return; }
    const goal = visionGoalsCache.find(g => g.id === goalId);
    if (!goal || !supabaseClient) return;
    const month = currentMonthKey();
    const makeFocus = goal.focus_month !== month;
    if (makeFocus) {
        const others = visionGoalsCache.filter(g => g.id !== goalId && g.focus_month === month);
        if (others.length) await supabaseClient.from('vision_goals').update({ focus_month: null }).in('id', others.map(g => g.id));
        others.forEach(g => { g.focus_month = null; });
    }
    const { error } = await supabaseClient.from('vision_goals').update({ focus_month: makeFocus ? month : null }).eq('id', goalId);
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    goal.focus_month = makeFocus ? month : null;
    if (makeFocus) showAppToast(t('vision_focus_set_toast'));
    renderVisionGoalsList();
    renderPeekFocusGoal();
}

// שקילה חדשה (מדדים / New Me) מעדכנת יעדי משקל ויכולה להשלים אותם
async function onWeightLoggedForGoals() {
    if (!visionGoalsCache.some(g => g.track_type === 'weight' && !g.is_achieved)) return;
    await refreshVisionLatestWeight();
    renderVisionGoalsList();
    renderPeekFocusGoal();
    visionGoalsCache.filter(g => g.track_type === 'weight').forEach(autoCheckGoalReminder);
    checkWeightGoalsAchieved();
}
function checkWeightGoalsAchieved() {
    visionGoalsCache.filter(g => g.track_type === 'weight' && !g.is_achieved && visionGoalProgress(g).reached).forEach(g => setVisionGoalAchieved(g.id));
}

// אתגר ימים: ✓ על משימה יומית (או "עמדתי היום" כשאין משימות) - לתאריך של היום בלבד.
// מסנכרן גם את הפריטים המקושרים ב"השגרה שלי" (✓ כאן = ✓ שם)
async function toggleVisionDayCheck(goalId, milestoneId, checked) {
    if (!supabaseClient || !currentUserId) return;
    const today = getLocalDateString();
    if (checked) {
        if (!visionCheckedToday(goalId, milestoneId)) {
            const { data, error } = await supabaseClient.from('vision_goal_checkins').insert({ goal_id: goalId, milestone_id: milestoneId || null, user_id: currentUserId, checkin_date: today }).select().single();
            if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); renderVisionGoalsList(); return; }
            visionCheckinsCache.push(data);
        }
    } else {
        let del = supabaseClient.from('vision_goal_checkins').delete().eq('goal_id', goalId).eq('checkin_date', today);
        del = milestoneId ? del.eq('milestone_id', milestoneId) : del.is('milestone_id', null);
        await del;
        visionCheckinsCache = visionCheckinsCache.filter(ch => !(ch.goal_id === goalId && (ch.milestone_id || null) === (milestoneId || null) && ch.checkin_date === today));
    }
    if (milestoneId) await syncRoutineChecksForMilestone(milestoneId, checked, today);
    else await syncRoutineChecksForGoal(goalId, checked, today);
    renderVisionGoalsList();
    renderPeekFocusGoal();
    const goal = visionGoalsCache.find(g => g.id === goalId);
    if (checked && goal && visionDoneDays(goal).includes(today)) showAppToast(t('vision_days_day_done_toast'));
    await checkAndMarkGoalAchieved(goalId);
    // ✓ ביעד מתעדכן גם בהצצה להיום (ולהפך - הסימון שם קורא לפונקציה הזו)
    loadTodayTasks();
}

// --- משימות היעדים בהצצה להיום (לפי בקשה מפורשת: "המשימות של היום צריכות להסתנכרן ישירות
// עם הצצה יומית"): המשימות היומיות של אתגר ימים פעיל, ותזכורות של יעדי ספירה/משקל ביום
// שלהן. לא נשמרות כמשימות ביומן - נבנות מהיעדים עצמם, כך שתמיד מסונכרנות (✓ שם = ✓ כאן).
// צעדים מתוזמנים (📅) כבר מופיעים בהצצה כמשימות יומן רגילות ---
// כל פריט: { icon, text, tag (שם היעד/הספר, או null), done, toggle(checked) } - אותה שורה
// משמשת גם למשימת הקריאה היומית של "הספרים שלי" (ר' getPeekBookTaskItems ב-books.js)
function getPeekGoalTaskItems() {
    const weekday = new Date().getDay();
    const items = [];
    // אותו סדר כמו הצ'יפים במסך היעדים (יעד החודש ראשון)
    visionSortedActiveGoals().forEach(goal => {
        const icon = visionGoalIcon(goal);
        if (goal.track_type === 'days') {
            const tasks = visionSortedMilestones(goal.id);
            if (tasks.length) {
                tasks.forEach(m => items.push({ goalId: goal.id, icon, text: m.title, tag: goal.title, done: visionCheckedToday(goal.id, m.id), toggle: checked => toggleVisionDayCheck(goal.id, m.id, checked) }));
            } else {
                items.push({ goalId: goal.id, icon, text: goal.title, tag: null, done: visionCheckedToday(goal.id, null), toggle: checked => toggleVisionDayCheck(goal.id, null, checked) });
            }
        } else if (goal.reminder_freq) {
            // 👣 הצעד הקטן של כל יעד אחר (תחנות / ספירה / משקל) - כל יום, או בשבוע ביום שנבחר
            if (goal.reminder_freq === 'weekly' && Number(goal.reminder_weekday) !== weekday) return;
            const text = visionSmallStepText(goal) || goal.title;
            items.push({ goalId: goal.id, icon, text, tag: text === goal.title ? null : goal.title, done: visionCheckedToday(goal.id, null), toggle: checked => toggleGoalReminderCheck(goal.id, checked) });
        }
    });
    return items;
}

function buildPeekGoalTaskRow(item) {
    const row = document.createElement('div');
    row.className = 'today-tasks-row today-goal-task-row';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'day-detail-checkbox';
    checkbox.checked = item.done;
    checkbox.onchange = () => item.toggle(checkbox.checked);
    const text = document.createElement('span');
    text.className = 'today-tasks-text' + (item.done ? ' completed' : '');
    text.textContent = `${item.icon} ${item.text}`;
    row.appendChild(checkbox);
    row.appendChild(text);
    if (item.tag) {
        const tag = document.createElement('span');
        tag.className = 'today-goal-task-tag';
        tag.textContent = item.tag;
        row.appendChild(tag);
    }
    // ⓘ קטן (אתגרי New Me): "מה בדיוק נחשב?" נפתח בלי לצאת מההצצה
    if (item.info) {
        const info = document.createElement('button');
        info.type = 'button';
        info.className = 'today-goal-task-info';
        info.textContent = 'ⓘ';
        info.title = item.infoLabel || '';
        info.setAttribute('aria-label', item.infoLabel || 'ⓘ');
        info.onclick = e => { e.stopPropagation(); item.info(); };
        row.appendChild(info);
    }
    return row;
}

// ✓ על הצעד הקטן / "✓ עשיתי היום" של יעד (לא אתגר ימים) - להיום בלבד (סימון בלי milestone
// ב-vision_goal_checkins). מתעדכן גם בהצצה להיום וגם במסך היעדים
async function toggleGoalReminderCheck(goalId, checked) {
    if (!supabaseClient || !currentUserId) return;
    const today = getLocalDateString();
    if (checked) {
        if (!visionCheckedToday(goalId, null)) {
            const { data, error } = await supabaseClient.from('vision_goal_checkins').insert({ goal_id: goalId, milestone_id: null, user_id: currentUserId, checkin_date: today }).select().single();
            if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); loadTodayTasks(); renderVisionGoalsList(); return; }
            visionCheckinsCache.push(data);
        }
    } else {
        await supabaseClient.from('vision_goal_checkins').delete().eq('goal_id', goalId).eq('checkin_date', today).is('milestone_id', null);
        visionCheckinsCache = visionCheckinsCache.filter(ch => !(ch.goal_id === goalId && !ch.milestone_id && ch.checkin_date === today));
    }
    await syncRoutineChecksForGoal(goalId, checked, today);
    renderVisionGoalsList();
    loadTodayTasks();
}

// +1 שנרשם היום מסמן לבד את הצעד הקטן של היום; ביעד משקל - רק כשהצעד הקטן הוא השקילה עצמה
function autoCheckGoalReminder(goal) {
    if (!goal || goal.is_achieved || !goal.reminder_freq) return;
    if (goal.reminder_freq === 'weekly' && Number(goal.reminder_weekday) !== new Date().getDay()) return;
    if (goal.track_type === 'weight' && (visionSmallStepText(goal) || '') !== t('vision_reminder_weigh_default')) return;
    if (!visionCheckedToday(goal.id, null)) toggleGoalReminderCheck(goal.id, true);
}

// ✓ ביעד → ✓ לאותו יום בפריטים המקושרים ב"השגרה שלי"
async function syncRoutineChecksForMilestone(milestoneId, checked, dateStr) {
    await syncRoutineCheckinsForLinks(visionRoutineLinks.filter(r => r.vision_milestone_id === milestoneId), checked, dateStr);
}
// 👣 ✓ על הצעד הקטן (או "עמדתי היום" באתגר בלי משימות) → ✓ בפריט המקושר בשגרה
async function syncRoutineChecksForGoal(goalId, checked, dateStr) {
    await syncRoutineCheckinsForLinks(visionGoalRoutineLinks.filter(r => r.vision_goal_id === goalId), checked, dateStr);
}
// טאב של ימים מסוימים (ראשון / שני...) מסומן רק ביום שלו - כדי שהלוח החודשי שלו לא יראה ✓ ביום אחר
function routineTabAppliesOnDate(tabId, dateStr) {
    const tab = dailyBoardTabs.find(tb => tb.id === tabId) || visionRoutineTabsCache.find(tb => tb.id === tabId);
    if (!tab) return true;
    const days = routineTabWeekdays(tab);
    if (!days.length) return true;
    const [y, m, d] = dateStr.split('-').map(Number);
    return days.includes(new Date(y, m - 1, d).getDay());
}
async function syncRoutineCheckinsForLinks(links, checked, dateStr) {
    const items = links.filter(r => routineTabAppliesOnDate(r.tab_id, dateStr));
    if (!items.length) return;
    for (const it of items) {
        if (checked) {
            const { data: existing } = await supabaseClient.from('routine_item_checkins').select('item_id').eq('item_id', it.id).eq('checkin_date', dateStr).limit(1);
            if (!existing || !existing.length) await supabaseClient.from('routine_item_checkins').insert({ item_id: it.id, user_id: currentUserId, checkin_date: dateStr });
        } else {
            await supabaseClient.from('routine_item_checkins').delete().eq('item_id', it.id).eq('checkin_date', dateStr);
        }
    }
    const board = document.getElementById('modal-daily-board');
    if (board && board.classList.contains('open')) renderDailyBoard();
}

// ✓ ב"השגרה שלי" על פריט מקושר → ביעד: באתגר ימים - סימון היום; בצעדים - הצעד מסומן כבוצע
async function syncGoalFromRoutineCheck(milestoneId, dateStr, checked) {
    const { data: m } = await supabaseClient.from('vision_goal_milestones').select('id, goal_id').eq('id', milestoneId).maybeSingle();
    if (!m) return;
    const { data: goal } = await supabaseClient.from('vision_goals').select('id, track_type, is_achieved').eq('id', m.goal_id).maybeSingle();
    if (!goal || goal.is_achieved) return;
    if (goal.track_type === 'days') {
        if (checked) {
            const { data: existing } = await supabaseClient.from('vision_goal_checkins').select('id').eq('goal_id', goal.id).eq('milestone_id', milestoneId).eq('checkin_date', dateStr).limit(1);
            if (!existing || !existing.length) await supabaseClient.from('vision_goal_checkins').insert({ goal_id: goal.id, milestone_id: milestoneId, user_id: currentUserId, checkin_date: dateStr });
        } else {
            await supabaseClient.from('vision_goal_checkins').delete().eq('goal_id', goal.id).eq('milestone_id', milestoneId).eq('checkin_date', dateStr);
        }
    } else {
        await supabaseClient.from('vision_goal_milestones').update({ is_done: checked }).eq('id', milestoneId);
    }
    await loadVisionGoals();
    await checkAndMarkGoalAchieved(goal.id);
}

// ✓ ב"השגרה שלי" על הצעד הקטן של יעד → "✓ עשיתי היום" ביעד (סימון בלי milestone לאותו יום)
async function syncGoalSmallStepFromRoutine(goalId, dateStr, checked) {
    const { data: goal } = await supabaseClient.from('vision_goals').select('id, is_achieved').eq('id', goalId).maybeSingle();
    if (!goal || goal.is_achieved) return;
    if (checked) {
        const { data: existing } = await supabaseClient.from('vision_goal_checkins').select('id').eq('goal_id', goalId).is('milestone_id', null).eq('checkin_date', dateStr).limit(1);
        if (!existing || !existing.length) await supabaseClient.from('vision_goal_checkins').insert({ goal_id: goalId, milestone_id: null, user_id: currentUserId, checkin_date: dateStr });
    } else {
        await supabaseClient.from('vision_goal_checkins').delete().eq('goal_id', goalId).is('milestone_id', null).eq('checkin_date', dateStr);
    }
    await loadVisionGoals();
    await checkAndMarkGoalAchieved(goalId);
}

// --- 🔁 הוספה ל"השגרה שלי": בוחרים טאב ושעה פנויה - נוצר פריט בשגרה שמקושר לצעד/למשימה,
// וסימון ✓ באחד המקומות מסמן גם בשני (לפי בקשה מפורשת: "לחבר יעדים לשגרה שלי") ---
// smallStepGoalId (בלי milestoneId) - הצעד הקטן היומי של היעד (routine_items.vision_goal_id)
let goalRoutinePickerState = null;
async function openGoalRoutinePicker(milestoneId, smallStepGoalId = null) {
    if (!supabaseClient || !currentUserId) return;
    const milestone = milestoneId ? visionMilestonesCache.find(x => x.id === milestoneId) : null;
    const goal = visionGoalsCache.find(g => g.id === (milestone ? milestone.goal_id : smallStepGoalId));
    if (!milestone && !goal) return;
    if (!dailyBoardTabs.length) await loadRoutineTabs();
    goalRoutinePickerState = { milestone, goal, tabId: activeDailyBoardTabId || (dailyBoardTabs[0] ? dailyBoardTabs[0].id : null), hour: null, usedTimes: new Set() };
    const what = milestone ? milestone.title : `👣 ${visionSmallStepText(goal) || goal.title}`;
    document.getElementById('goal-routine-picker-task').textContent = `🎯 ${goal ? goal.title + ' · ' : ''}${what}`;
    await refreshGoalRoutinePicker();
    openModal('modal-goal-routine-picker');
}

async function refreshGoalRoutinePicker() {
    const st = goalRoutinePickerState;
    if (!st) return;
    const tabWrap = document.getElementById('goal-routine-tab-chips');
    const hourWrap = document.getElementById('goal-routine-hour-chips');
    const noHours = document.getElementById('goal-routine-no-hours');
    const addBtn = document.getElementById('btn-goal-routine-add');
    if (st.tabId) {
        const { data } = await supabaseClient.from('routine_items').select('time').eq('tab_id', st.tabId).eq('user_id', currentUserId).eq('kind', 'scheduled');
        st.usedTimes = new Set((data || []).map(r => (r.time || '').slice(0, 5)));
    }
    tabWrap.innerHTML = '';
    dailyBoardTabs.forEach(tab => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'vision-goal-category-chip' + (tab.id === st.tabId ? ' selected' : '');
        chip.textContent = tab.name;
        chip.onclick = () => { st.tabId = tab.id; st.hour = null; refreshGoalRoutinePicker(); };
        tabWrap.appendChild(chip);
    });
    const hoursByBucket = getDailyBoardCustomHours(st.tabId);
    const hours = [...new Set([...hoursByBucket.morning, ...hoursByBucket.noon, ...hoursByBucket.afternoon, ...hoursByBucket.evening])].sort((a, b) => a - b);
    hourWrap.innerHTML = '';
    let freeCount = 0;
    hours.forEach(hour => {
        const time = `${String(hour).padStart(2, '0')}:00`;
        const taken = st.usedTimes.has(time);
        if (!taken) freeCount++;
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'vision-goal-category-chip vision-hour-chip' + (st.hour === hour ? ' selected' : '') + (taken ? ' is-taken' : '');
        chip.textContent = time;
        chip.disabled = taken;
        if (taken) chip.title = t('vision_routine_hour_taken');
        chip.onclick = () => { st.hour = hour; refreshGoalRoutinePickerSelection(); };
        hourWrap.appendChild(chip);
    });
    noHours.classList.toggle('hidden', freeCount > 0);
    addBtn.disabled = st.hour === null;
}
function refreshGoalRoutinePickerSelection() {
    const st = goalRoutinePickerState;
    if (!st) return;
    document.querySelectorAll('#goal-routine-hour-chips .vision-hour-chip').forEach(chip => {
        chip.classList.toggle('selected', chip.textContent === `${String(st.hour).padStart(2, '0')}:00`);
    });
    document.getElementById('btn-goal-routine-add').disabled = st.hour === null;
}

async function confirmGoalRoutineLink() {
    const st = goalRoutinePickerState;
    if (!st || st.hour === null || !st.tabId) return;
    const time = `${String(st.hour).padStart(2, '0')}:00`;
    const goal = st.goal;
    if (!st.milestone) {
        // 👣 הצעד הקטן היומי - ואם כבר סומן היום ביעד, מסומן גם בשגרה
        const { data, error } = await supabaseClient.from('routine_items')
            .insert({ tab_id: st.tabId, user_id: currentUserId, title: `🎯 ${visionSmallStepText(goal) || goal.title}`, time, kind: 'scheduled', vision_goal_id: goal.id })
            .select('id, tab_id, time, vision_goal_id').single();
        if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
        visionGoalRoutineLinks.push(data);
        if (visionCheckedToday(goal.id, null)) await syncRoutineChecksForGoal(goal.id, true, getLocalDateString());
        closeModal('modal-goal-routine-picker');
        goalRoutinePickerState = null;
        showAppToast(t('vision_routine_added_toast'));
        renderVisionGoalsList();
        return;
    }
    const { data, error } = await supabaseClient.from('routine_items')
        .insert({ tab_id: st.tabId, user_id: currentUserId, title: `🎯 ${st.milestone.title}`, time, kind: 'scheduled', vision_milestone_id: st.milestone.id })
        .select('id, tab_id, time, vision_milestone_id').single();
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    visionRoutineLinks.push(data);
    // אם כבר סומן היום ביעד - מסומן גם בשגרה
    const doneAlready = goal && goal.track_type === 'days' ? visionCheckedToday(goal.id, st.milestone.id) : !!st.milestone.is_done;
    if (doneAlready) await syncRoutineChecksForMilestone(st.milestone.id, true, getLocalDateString());
    closeModal('modal-goal-routine-picker');
    goalRoutinePickerState = null;
    showAppToast(t('vision_routine_added_toast'));
    renderVisionGoalsList();
}

// מזריקה תחנת-ביניים בודדת ליומן כאירוע חד-פעמי להיום - בדיוק כמו "מבט
// ליומן" רגיל (source:'calendar', לא daily board/לו"ז שבועי), לפי בקשה
// מפורשת של המשתמשת. שם היעד מוצג כקידומת לתחנה כדי שברשימה שטוחה (מבט
// ליומן) יהיה ברור מתוך איזה יעד זה הגיע, בלי לפתוח את המגירה
// vision_milestone_id מקשר את המשימה היומית לתחנה - כך שהכול מסונכרן (לפי בקשה מפורשת):
// מחיקה מההצצה מוחקת גם את התחנה בלוח החזון, ו-✓ בכל אחד מהם מסמן גם בשני
// --- 📅 תזמון צעד ביומן (לפי בקשה מפורשת: "שזה ירשום מתי יהיה הצעד ... ובאיזה תאריך ... ואם
// הם רוצים כל שבוע"): נוצרת משימה ב-calendar_events שמקושרת לצעד - מופיעה בהצצה להיום,
// ב"השבוע שלי", בלוח החודשי וב-Google Calendar אם מחובר, ו-✓ עליה מסמן את הצעד (ולהפך).
// "כל שבוע עד שמסיימים" = סדרה שבועית (עד תאריך היעד, או 3 חודשים) שהמופעים העתידיים
// שלה נמחקים ברגע שהצעד מסומן ✓ (ר' syncStepEventsDone) ---
let goalStepScheduleState = null;
function openGoalStepSchedule(goalId, milestoneId) {
    const milestone = visionMilestonesCache.find(m => m.id === milestoneId);
    if (!milestone) return;
    const goal = visionGoalsCache.find(g => g.id === goalId) || null;
    goalStepScheduleState = { goal, milestone };
    document.getElementById('goal-step-schedule-task').textContent = `🎯 ${goal ? goal.title + ' · ' : ''}${milestone.title}`;
    const schedule = visionStepScheduleFor(milestoneId);
    document.getElementById('goal-step-schedule-date').value = schedule ? schedule.next : getLocalDateString();
    const display = document.getElementById('goal-step-schedule-date-display');
    if (display) display.setAttribute('data-placeholder', t('vision_step_schedule_date_label'));
    updateDateFieldDisplay('goal-step-schedule-date');
    document.getElementById('goal-step-schedule-weekly').checked = !!(schedule && schedule.weekly);
    const current = document.getElementById('goal-step-schedule-current');
    current.textContent = schedule ? t('vision_step_schedule_current').replace('{when}', visionStepScheduleLabel(schedule)) : '';
    current.classList.toggle('hidden', !schedule);
    document.getElementById('btn-goal-step-unschedule').classList.toggle('hidden', !schedule);
    openModal('modal-goal-step-schedule');
}

// תזמון חדש מחליף את הקודם: נמחקות רק המשימות הפתוחות של הצעד מהיום והלאה (עבר ומה שסומן נשארים)
async function deleteUpcomingStepEvents(milestoneId) {
    await supabaseClient.from('calendar_events').delete().eq('user_id', currentUserId).eq('vision_milestone_id', milestoneId)
        .gte('event_date', getLocalDateString()).eq('is_completed', false);
}

async function confirmGoalStepSchedule() {
    const st = goalStepScheduleState;
    if (!st || !supabaseClient || !currentUserId) return;
    const date = document.getElementById('goal-step-schedule-date').value;
    if (!date) { showAppToast(t('vision_step_schedule_date_required'), 'error'); return; }
    const weekly = document.getElementById('goal-step-schedule-weekly').checked;
    await deleteUpcomingStepEvents(st.milestone.id);
    let dates = [date];
    let groupId = null;
    if (weekly) {
        groupId = crypto.randomUUID();
        dates = generateRecurringDates(date, 'weeks', 1, 3);
        // יעד עם תאריך - התזכורת לא ממשיכה אחריו
        const deadline = st.goal && st.goal.target_date;
        if (deadline && deadline >= date) dates = dates.filter(d => d <= deadline);
    }
    const title = `🎯 ${st.goal ? st.goal.title + ': ' : ''}${st.milestone.title}`;
    const rows = dates.map(d => ({
        username: currentUsername, user_id: currentUserId,
        event_title: title, event_date: d, source: 'calendar',
        recurrence_group_id: groupId, recurrence_original_date: groupId ? d : null,
        vision_milestone_id: st.milestone.id, is_completed: false,
    }));
    const { error } = await supabaseClient.from('calendar_events').insert(rows);
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    closeModal('modal-goal-step-schedule');
    goalStepScheduleState = null;
    showAppToast(t('vision_step_scheduled_toast'));
    await refreshAfterStepScheduleChange();
}

async function removeGoalStepSchedule() {
    const st = goalStepScheduleState;
    if (!st || !supabaseClient) return;
    await deleteUpcomingStepEvents(st.milestone.id);
    closeModal('modal-goal-step-schedule');
    goalStepScheduleState = null;
    showAppToast(t('vision_step_unscheduled_toast'));
    await refreshAfterStepScheduleChange();
}

async function refreshAfterStepScheduleChange() {
    await loadVisionStepEvents();
    renderVisionGoalsList();
    loadTodayTasks();
    loadCalendarEvents();
    loadMonthlyCalendarGrid();
}

// ✓ על צעד (מהיעד או מהמשימה ביומן) → כל המשימות המקושרות מסומנות בהתאם. בתזכורת שבועית
// ("כל שבוע עד שמסיימים") המופעים העתידיים כבר לא נחוצים - נמחקים
async function syncStepEventsDone(milestoneId, checked) {
    if (checked) {
        await supabaseClient.from('calendar_events').delete().eq('user_id', currentUserId).eq('vision_milestone_id', milestoneId)
            .gt('event_date', getLocalDateString()).not('recurrence_group_id', 'is', null);
    }
    const { data } = await supabaseClient.from('calendar_events').update({ is_completed: checked }).eq('user_id', currentUserId).eq('vision_milestone_id', milestoneId).select('id');
    await loadVisionStepEvents();
    // התווית ליד הצעד (📅 / 🔁) מתעדכנת - כרטיסים הפוכים נשארים הפוכים
    renderVisionGoalsList();
    if (checked || (data && data.length)) { loadTodayTasks(); loadCalendarEvents(); loadMonthlyCalendarGrid(); }
}

// מחיקת משימה שמקושרת לצעד: משימה חד-פעמית מוחקת גם את הצעד (כמו שתועד בשאלות הנפוצות);
// מופע של תזכורת שבועית - רק אותו שבוע נמחק, הצעד נשאר
async function handleLinkedStepTaskDelete(eventId) {
    const { data: linked } = await supabaseClient.from('calendar_events').select('vision_milestone_id, recurrence_group_id').eq('id', eventId).maybeSingle();
    if (linked && linked.vision_milestone_id && !linked.recurrence_group_id) await deleteVisionMilestoneEverywhere(linked.vision_milestone_id);
    return !!(linked && linked.vision_milestone_id);
}

async function addMilestoneToGoalFromCardBack(goalId, inputEl) {
    const title = inputEl.value.trim();
    if (!title || !supabaseClient || !currentUserId) return;
    const existing = visionMilestonesCache.filter(m => m.goal_id === goalId);
    const maxOrder = existing.reduce((max, m) => Math.max(max, m.sort_order || 0), 0);
    const goal = visionGoalsCache.find(g => g.id === goalId);
    const { data, error } = await supabaseClient.from('vision_goal_milestones')
        .insert({ goal_id: goalId, user_id: currentUserId, title, is_done: false, sort_order: maxOrder + 10 })
        .select().single();
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    visionMilestonesCache.push(data);
    inputEl.value = '';
    updateVisionCardProgressDisplay(goalId);
    // ממשיכים להוסיף בלי ללחוץ שוב על השדה (השדה החדש אחרי הרינדור)
    if (goal) {
        const next = document.querySelector('#gv-goal .gv-add-row input[type="text"]');
        if (next) next.focus({ preventScroll: true });
    }
}

// --- הוספה/עריכה של יעד: מודל רגיל (apple-modal), עם רשימת תחנות-ביניים
// שנבנית בזיכרון (pendingVisionMilestones) ונשמרת כולה בלחיצה על "שמירה".
// במצב עריכה שומרים גם את ה-id וה-is_done של כל תחנה קיימת (לא רק הטקסט),
// כדי שסימוני "בוצע" לא יימחקו סתם כי המשתמשת רק שינתה את שם היעד.
// template = תוכנית מספריית היעדים ("לערוך קודם", ר' glibTemplateGoal ב-goals-library.js) ---
let editingVisionGoalId = null;
let pendingVisionMilestones = [];
let originalVisionMilestoneIds = [];
let selectedVisionGoalCategory = null;
let selectedVisionTrackType = 'steps';
// מאיזו תוכנית בספרייה נוצר היעד (vision_goals.template_key), ומה להוסיף ל"השגרה שלי" אחרי השמירה
let selectedVisionTemplateKey = null;
let visionPendingLibRoutine = null;

// סמלים לבחירה ליעד (בלי "אחר" - בורר סמלים, ר' הכלל על תפריטים)
const VISION_GOAL_ICON_OPTIONS = ['🎯', '🏃', '💪', '🧘', '🥗', '💧', '😴', '⚖️', '📚', '🗣️', '🎸', '🎹', '🎨', '✍️', '💼', '💰', '🏠', '🧹', '✈️', '❤️', '👨‍👩‍👧', '🌱', '🛒', '⭐'];
let selectedVisionGoalIcon = '🎯';
let visionGoalIconTouched = false;
function renderVisionGoalIconPicker() {
    const wrap = document.getElementById('vision-goal-icon-picker');
    if (!wrap) return;
    wrap.innerHTML = '';
    const options = VISION_GOAL_ICON_OPTIONS.includes(selectedVisionGoalIcon) ? VISION_GOAL_ICON_OPTIONS : [selectedVisionGoalIcon, ...VISION_GOAL_ICON_OPTIONS];
    options.forEach(icon => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'vision-goal-icon-opt' + (icon === selectedVisionGoalIcon ? ' selected' : '');
        btn.setAttribute('aria-pressed', icon === selectedVisionGoalIcon ? 'true' : 'false');
        btn.textContent = icon;
        btn.onclick = () => { selectedVisionGoalIcon = icon; visionGoalIconTouched = true; renderVisionGoalIconPicker(); };
        wrap.appendChild(btn);
    });
}

function openVisionGoalModal(goalId = null, template = null, opts = {}) {
    editingVisionGoalId = goalId;
    const titleEl = document.getElementById('vision-goal-modal-title');
    const deleteBtn = document.getElementById('btn-delete-vision-goal');
    const goal = goalId ? visionGoalsCache.find(g => g.id === goalId) : null;
    if (goalId && !goal) return;
    const dateDisplay = document.getElementById('vision-goal-date-input-display');
    if (dateDisplay) dateDisplay.setAttribute('data-placeholder', t('vision_date_placeholder'));
    if (goal) {
        if (titleEl) titleEl.textContent = t('vision_goal_modal_title_edit');
        document.getElementById('vision-goal-title-input').value = goal.title || '';
        selectedVisionGoalCategory = goal.category || null;
        setVisionGoalImagePreview(goal.image_url || '');
        const existing = visionMilestonesCache.filter(m => m.goal_id === goalId).sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
        pendingVisionMilestones = existing.map(m => ({ id: m.id, title: m.title, is_done: m.is_done }));
        originalVisionMilestoneIds = existing.map(m => m.id);
        if (deleteBtn) {
            deleteBtn.classList.remove('hidden');
            deleteBtn.onclick = () => { closeModal('modal-add-vision-goal'); deleteVisionGoal(goalId); };
        }
    } else {
        if (titleEl) titleEl.textContent = t('vision_goal_modal_title_add');
        document.getElementById('vision-goal-title-input').value = template ? template.title : '';
        selectedVisionGoalCategory = template ? template.category : null;
        setVisionGoalImagePreview('');
        pendingVisionMilestones = template && template.milestoneTitles
            ? template.milestoneTitles.map(title => ({ id: null, title, is_done: false }))
            : [];
        originalVisionMilestoneIds = [];
        if (deleteBtn) deleteBtn.classList.add('hidden');
    }
    selectedVisionTemplateKey = !goal && template ? template.libId : null;
    visionPendingLibRoutine = !goal && template ? (template.routine || null) : null;
    // תוכנית תחנות מהספרייה - תאריך היעד לפי משך התוכנית (אפשר לשנות)
    let templateDate = '';
    if (!goal && template && template.weeks) { const d = new Date(); d.setDate(d.getDate() + template.weeks * 7); templateDate = getLocalDateString(d); }
    document.getElementById('vision-goal-why-input').value = goal ? (goal.why || '') : '';
    document.getElementById('vision-goal-reward-input').value = goal ? (goal.reward || '') : '';
    document.getElementById('vision-goal-date-input').value = goal ? (goal.target_date || '') : templateDate;
    updateDateFieldDisplay('vision-goal-date-input');
    onVisionGoalDateChange();
    let track = goal ? (goal.track_type || 'steps') : (template ? template.track : 'steps');
    // מספר / משקל הם חלק מפרימיום (כמו היעד החודשי הישן) - דוגמה כזו נפתחת בצעדים
    if ((track === 'number' || track === 'weight') && !isPremiumUser && !goal) track = 'steps';
    document.getElementById('vision-goal-days-input').value = goal && track === 'days' ? (goal.target_value ?? '') : (!goal && template && template.track === 'days' ? template.target : '');
    selectedVisionTrackType = track;
    const isNumber = track === 'number';
    document.getElementById('vision-goal-target-input').value = goal && isNumber ? (goal.target_value ?? '') : (!goal && template && template.track === 'number' ? template.target : '');
    document.getElementById('vision-goal-current-input').value = goal && isNumber ? (goal.current_value ?? '') : '';
    document.getElementById('vision-goal-unit-input').value = goal && isNumber ? (goal.unit || '') : (!goal && template && template.unit ? template.unit : '');
    document.getElementById('vision-goal-weight-target-input').value = goal && track === 'weight' ? (goal.target_value ?? '') : '';
    document.getElementById('vision-goal-focus-toggle').checked = !!(goal && goal.focus_month === currentMonthKey() && !goal.is_achieved);
    // 👣 הצעד הקטן: ביעד חדש - כל יום כברירת מחדל ("רק קצת כל יום"), או מה שבתוכנית; בעריכה - מה שנשמר
    selectedVisionReminderFreq = goal ? (goal.reminder_freq || null) : ((template && template.freq) || 'daily');
    if (goal && opts.focusSmallStep && !selectedVisionReminderFreq) selectedVisionReminderFreq = 'daily';
    selectedVisionReminderWeekday = goal && goal.reminder_weekday != null ? Number(goal.reminder_weekday) : new Date().getDay();
    document.getElementById('vision-goal-reminder-text').value = goal ? (goal.reminder_text || '') : ((template && template.daily) || '');
    const categoryPreset = VISION_GOAL_CATEGORY_PRESETS.find(c => c.key === selectedVisionGoalCategory && c.key !== 'other');
    selectedVisionGoalIcon = (goal && goal.icon) || (template && template.icon) || (categoryPreset ? categoryPreset.icon : '🎯');
    visionGoalIconTouched = !!((goal && goal.icon) || template);
    renderVisionGoalIconPicker();
    renderVisionGoalCategoryChips();
    renderVisionTrackChips();
    renderPendingVisionMilestones();
    openModal('modal-add-vision-goal');
    // מ"＋ להגדיר צעד קטן" שמתחת לשביל - ישר לשדה של הצעד הקטן
    if (opts.focusSmallStep) {
        setTimeout(() => {
            const input = document.getElementById('vision-goal-reminder-text');
            if (input && !input.closest('.hidden')) { input.scrollIntoView({ block: 'center' }); input.focus({ preventScroll: true }); }
        }, 260);
    }
}

function resetVisionGoalModal() {
    editingVisionGoalId = null;
    pendingVisionMilestones = [];
    originalVisionMilestoneIds = [];
    selectedVisionGoalCategory = null;
    selectedVisionTrackType = 'steps';
    selectedVisionReminderFreq = null;
    selectedVisionReminderWeekday = new Date().getDay();
    selectedVisionTemplateKey = null;
    visionPendingLibRoutine = null;
    ['vision-goal-title-input', 'vision-goal-milestone-input', 'vision-goal-why-input', 'vision-goal-reward-input', 'vision-goal-date-input',
        'vision-goal-target-input', 'vision-goal-current-input', 'vision-goal-unit-input', 'vision-goal-weight-target-input', 'vision-goal-days-input',
        'vision-goal-reminder-text'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });
    const focusToggle = document.getElementById('vision-goal-focus-toggle');
    if (focusToggle) focusToggle.checked = false;
    setVisionGoalImagePreview('');
    selectedVisionGoalIcon = '🎯';
    visionGoalIconTouched = false;
}

// איך מודדים התקדמות: צעדים (ברירת מחדל) / מספר / משקל. מספר ומשקל - פרימיום
// כל אפשרות עם שורת הסבר קצרה - לפי בקשה מפורשת ("מה זה אומר לפי מספר? ... שיהיה יותר מובן")
const VISION_TRACK_OPTIONS = [
    { type: 'steps', key: 'vision_track_steps', desc: 'vision_track_steps_desc' },
    { type: 'days', key: 'vision_track_days', desc: 'vision_track_days_desc' },
    { type: 'number', key: 'vision_track_number', desc: 'vision_track_number_desc', premium: true },
    { type: 'weight', key: 'vision_track_weight', desc: 'vision_track_weight_desc', premium: true },
];
function renderVisionTrackChips() {
    const wrap = document.getElementById('vision-goal-track-chips');
    if (!wrap) return;
    wrap.innerHTML = '';
    VISION_TRACK_OPTIONS.forEach(opt => {
        const card = document.createElement('button');
        card.type = 'button';
        card.className = 'vision-track-option' + (selectedVisionTrackType === opt.type ? ' selected' : '');
        card.innerHTML = `<span class="vision-track-option-title">${visionEsc(t(opt.key))}${opt.premium && !isPremiumUser ? ' ⭐' : ''}</span><span class="vision-track-option-desc">${visionEsc(t(opt.desc))}</span>`;
        card.onclick = () => selectVisionTrackType(opt.type);
        wrap.appendChild(card);
    });
    document.getElementById('vision-goal-number-fields').classList.toggle('hidden', selectedVisionTrackType !== 'number');
    document.getElementById('vision-goal-weight-fields').classList.toggle('hidden', selectedVisionTrackType !== 'weight');
    document.getElementById('vision-goal-days-fields').classList.toggle('hidden', selectedVisionTrackType !== 'days');
    // באתגר ימים הרשימה היא "מה עושים כל יום" ולא צעדים חד-פעמיים
    const isDays = selectedVisionTrackType === 'days';
    const stepsLabel = document.getElementById('vision-goal-steps-label');
    if (stepsLabel) stepsLabel.textContent = t(isDays ? 'vision_days_tasks_title' : 'vision_goal_milestones_section_title');
    const stepsInput = document.getElementById('vision-goal-milestone-input');
    if (stepsInput) stepsInput.placeholder = t(isDays ? 'vision_days_task_placeholder' : 'vision_goal_milestone_input_placeholder');
    renderVisionReminderFields();
}

// 👣 הצעד הקטן (לשעבר "תזכורת בהצצה להיום" של יעדי ספירה/משקל) - לכל יעד שאינו אתגר ימים:
// בלי / כל יום / כל שבוע ביום שנבחר, והטקסט של הצעד. נשמר בשדות reminder_* של היעד
let selectedVisionReminderFreq = null;
let selectedVisionReminderWeekday = new Date().getDay();
const VISION_REMINDER_OPTIONS = [
    { freq: null, key: 'vision_reminder_off' },
    { freq: 'daily', key: 'vision_reminder_daily' },
    { freq: 'weekly', key: 'vision_reminder_weekly' },
];
function renderVisionReminderFields() {
    const wrap = document.getElementById('vision-goal-reminder-fields');
    if (!wrap) return;
    // באתגר ימים יש "מה עושים כל יום" במקום צעד קטן
    const applies = selectedVisionTrackType !== 'days';
    wrap.classList.toggle('hidden', !applies);
    if (!applies) return;
    const chips = document.getElementById('vision-goal-reminder-chips');
    chips.innerHTML = '';
    VISION_REMINDER_OPTIONS.forEach(opt => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'vision-goal-category-chip' + (selectedVisionReminderFreq === opt.freq ? ' selected' : '');
        chip.textContent = t(opt.key);
        chip.onclick = () => selectVisionReminderFreq(opt.freq);
        chips.appendChild(chip);
    });
    const days = document.getElementById('vision-goal-reminder-weekdays');
    days.classList.toggle('hidden', selectedVisionReminderFreq !== 'weekly');
    days.innerHTML = '';
    if (selectedVisionReminderFreq === 'weekly') {
        // שמות הימים בשפה הנוכחית - 4.10.2026 היה יום ראשון, כך ש-i תואם ל-getDay()
        for (let i = 0; i < 7; i++) {
            const chip = document.createElement('button');
            chip.type = 'button';
            chip.className = 'vision-goal-category-chip' + (selectedVisionReminderWeekday === i ? ' selected' : '');
            chip.textContent = new Date(2026, 9, 4 + i).toLocaleDateString(currentLang, { weekday: 'short' });
            chip.onclick = () => { selectedVisionReminderWeekday = i; renderVisionReminderFields(); };
            days.appendChild(chip);
        }
    }
    document.getElementById('vision-goal-reminder-text-wrap').classList.toggle('hidden', !selectedVisionReminderFreq);
}
function selectVisionReminderFreq(freq) {
    selectedVisionReminderFreq = freq;
    renderVisionReminderFields();
    // הטקסט נשאר ריק (עם דוגמה בשדה) - הצעד הקטן הוא משהו שכל אחד/ת כותב/ת לעצמו
    const textInput = document.getElementById('vision-goal-reminder-text');
    if (freq && textInput && !textInput.value.trim()) textInput.focus({ preventScroll: true });
}
function selectVisionTrackType(type) {
    // לא פותחים כאן את חלון השדרוג - הוא היה סוגר את חלון היעד ומאבד את מה שהוקלד
    if ((type === 'number' || type === 'weight') && !isPremiumUser) { showAppToast(t('vision_track_premium_hint')); return; }
    selectedVisionTrackType = type;
    renderVisionTrackChips();
}
function onVisionFocusToggleChange(input) {
    if (input.checked && !isPremiumUser) { input.checked = false; showAppToast(t('vision_focus_premium_hint')); }
}
function onVisionGoalDateChange() {
    const input = document.getElementById('vision-goal-date-input');
    const clearBtn = document.getElementById('vision-goal-date-clear');
    if (clearBtn) clearBtn.classList.toggle('hidden', !(input && input.value));
}
function clearVisionGoalDate() {
    const input = document.getElementById('vision-goal-date-input');
    if (input) input.value = '';
    updateDateFieldDisplay('vision-goal-date-input');
    onVisionGoalDateChange();
}

function renderVisionGoalCategoryChips() {
    const container = document.getElementById('vision-goal-category-chips');
    if (!container) return;
    container.innerHTML = '';
    VISION_GOAL_CATEGORY_PRESETS.forEach(preset => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'vision-goal-category-chip' + (visionGoalCategoryChipKey() === preset.key ? ' selected' : '');
        chip.textContent = `${preset.icon} ${t('vision_goal_category_' + preset.key)}`;
        chip.onclick = () => selectVisionGoalCategory(preset.key);
        container.appendChild(chip);
    });
    // "אחר" = הקלדה ידנית של קטגוריה שלא ברשימה; הטקסט עצמו נשמר ב-category
    const customInput = document.getElementById('vision-goal-category-custom');
    if (customInput) {
        const isOther = visionGoalCategoryChipKey() === 'other';
        customInput.classList.toggle('hidden', !isOther);
        if (!isOther) customInput.value = '';
        else if (selectedVisionGoalCategory !== 'other' && document.activeElement !== customInput) customInput.value = selectedVisionGoalCategory;
    }
}
// קטגוריה ששמורה כטקסט חופשי מסומנת בצ'יפ "אחר"
function visionGoalCategoryChipKey() {
    if (!selectedVisionGoalCategory) return null;
    return VISION_GOAL_CATEGORY_PRESETS.some(c => c.key === selectedVisionGoalCategory) ? selectedVisionGoalCategory : 'other';
}
function selectVisionGoalCategory(key) {
    selectedVisionGoalCategory = visionGoalCategoryChipKey() === key ? null : key;
    // כל עוד לא בחרו סמל בעצמם - הסמל הולך אחרי הקטגוריה
    if (!visionGoalIconTouched) {
        const preset = VISION_GOAL_CATEGORY_PRESETS.find(c => c.key === selectedVisionGoalCategory && c.key !== 'other');
        selectedVisionGoalIcon = preset ? preset.icon : '🎯';
        renderVisionGoalIconPicker();
    }
    renderVisionGoalCategoryChips();
    if (key === 'other' && selectedVisionGoalCategory) {
        const customInput = document.getElementById('vision-goal-category-custom');
        if (customInput) customInput.focus();
    }
}

// מעלה את קובץ תמונת-החזון עצמה ל-Supabase Storage (bucket "goal-vision-photos") -
// אותו דפוס בדיוק כמו uploadRecipeImage, נכשלת בשקט (מחזירה null) אם ה-
// bucket עדיין לא קיים - זו תוספת אופציונלית, לא חוסמת יצירת יעד בלי תמונה
async function handleVisionGoalImageSelected(event) {
    const input = event.target;
    const file = input.files && input.files[0];
    input.value = '';
    if (!file) return;
    const url = await uploadVisionGoalImage(file);
    if (url) setVisionGoalImagePreview(url);
}

async function uploadVisionGoalImage(file) {
    if (!supabaseClient || !currentUserId || !file.type.startsWith('image/')) return null;
    try {
        const ext = (file.name && file.name.includes('.')) ? file.name.split('.').pop().toLowerCase() : 'jpg';
        const path = `${currentUserId}/${Date.now()}.${ext}`;
        const { error } = await supabaseClient.storage.from('goal-vision-photos').upload(path, file, { upsert: false, contentType: file.type });
        if (error) return null;
        const { data } = supabaseClient.storage.from('goal-vision-photos').getPublicUrl(path);
        return data ? data.publicUrl : null;
    } catch {
        return null;
    }
}

function setVisionGoalImagePreview(url) {
    const input = document.getElementById('vision-goal-image-url-input');
    const preview = document.getElementById('vision-goal-image-preview');
    if (input) input.value = url || '';
    if (preview) {
        if (url) { preview.src = url; preview.classList.remove('hidden'); }
        else { preview.src = ''; preview.classList.add('hidden'); }
    }
}

function addPendingVisionMilestoneRow() {
    const input = document.getElementById('vision-goal-milestone-input');
    const title = input.value.trim();
    if (!title) return;
    pendingVisionMilestones.push({ id: null, title, is_done: false });
    input.value = '';
    renderPendingVisionMilestones();
}
function removePendingVisionMilestoneRow(index) {
    pendingVisionMilestones.splice(index, 1);
    renderPendingVisionMilestones();
}
function renderPendingVisionMilestones() {
    const list = document.getElementById('vision-goal-pending-milestones-list');
    if (!list) return;
    list.innerHTML = '';
    pendingVisionMilestones.forEach((m, index) => {
        const row = document.createElement('div');
        row.className = 'vision-goal-pending-milestone-row';
        const span = document.createElement('span');
        span.textContent = m.title;
        const removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'vision-goal-pending-milestone-remove';
        removeBtn.title = t('vision_goal_milestone_remove_title');
        removeBtn.textContent = '✕';
        removeBtn.onclick = () => removePendingVisionMilestoneRow(index);
        row.appendChild(span);
        row.appendChild(removeBtn);
        list.appendChild(row);
    });
}

async function saveVisionGoal() {
    if (!supabaseClient || !currentUserId) { showAppToast(t('error_not_connected'), 'error'); return; }
    const title = document.getElementById('vision-goal-title-input').value.trim();
    if (!title) { showAppToast(t('calendar_event_missing_fields'), 'error'); return; }
    const imageUrl = document.getElementById('vision-goal-image-url-input').value || null;
    const customCategoryInput = document.getElementById('vision-goal-category-custom');
    const customCategory = customCategoryInput ? customCategoryInput.value.trim().slice(0, 40) : '';
    const category = visionGoalCategoryChipKey() === 'other' && customCategory ? customCategory : (visionGoalCategoryChipKey() === 'other' ? 'other' : selectedVisionGoalCategory);
    const track = selectedVisionTrackType;
    const existingGoal = editingVisionGoalId ? visionGoalsCache.find(g => g.id === editingVisionGoalId) : null;
    const payload = {
        title, category, image_url: imageUrl, icon: selectedVisionGoalIcon || null,
        why: document.getElementById('vision-goal-why-input').value.trim() || null,
        reward: document.getElementById('vision-goal-reward-input').value.trim() || null,
        target_date: document.getElementById('vision-goal-date-input').value || null,
        track_type: track, target_value: null, current_value: null, unit: null,
    };
    if (track === 'number') {
        const target = parseFloat(document.getElementById('vision-goal-target-input').value);
        if (!(target > 0)) { showAppToast(t('vision_number_target_required'), 'error'); return; }
        payload.target_value = target;
        payload.current_value = Math.max(0, parseFloat(document.getElementById('vision-goal-current-input').value) || 0);
        payload.unit = document.getElementById('vision-goal-unit-input').value.trim() || null;
    } else if (track === 'days') {
        const days = parseInt(document.getElementById('vision-goal-days-input').value, 10);
        if (!(days >= 1)) { showAppToast(t('vision_days_target_required'), 'error'); return; }
        payload.target_value = Math.min(365, days);
    } else if (track === 'weight') {
        const target = parseFloat(document.getElementById('vision-goal-weight-target-input').value);
        if (!(target > 0)) { showAppToast(t('vision_weight_target_required'), 'error'); return; }
        payload.target_value = target;
        // נקודת ההתחלה = השקילה האחרונה ברגע שהיעד הפך ליעד משקל
        if (!existingGoal || existingGoal.track_type !== 'weight' || existingGoal.start_value == null) {
            await refreshVisionLatestWeight();
            payload.start_value = visionLatestWeight;
        }
    }
    // 👣 הצעד הקטן - לכל יעד שאינו אתגר ימים
    const reminderFreq = track !== 'days' ? selectedVisionReminderFreq : null;
    payload.reminder_freq = reminderFreq;
    payload.reminder_weekday = reminderFreq === 'weekly' ? selectedVisionReminderWeekday : null;
    payload.reminder_text = reminderFreq ? (document.getElementById('vision-goal-reminder-text').value.trim().slice(0, 60) || null) : null;
    const month = currentMonthKey();
    const wantsFocus = document.getElementById('vision-goal-focus-toggle').checked && isPremiumUser;
    if (wantsFocus) payload.focus_month = month;
    else if (existingGoal && existingGoal.focus_month === month) payload.focus_month = null;

    let goalId = editingVisionGoalId;
    if (wantsFocus) {
        // רק יעד אחד בחודש - מורידים את הסימון מכל יעד אחר של החודש הזה
        let clear = supabaseClient.from('vision_goals').update({ focus_month: null }).eq('user_id', currentUserId).eq('focus_month', month);
        if (goalId) clear = clear.neq('id', goalId);
        await clear;
    }
    if (goalId) {
        const { error } = await supabaseClient.from('vision_goals').update(payload).eq('id', goalId);
        if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
        const keptIds = pendingVisionMilestones.filter(m => m.id).map(m => m.id);
        const toDelete = originalVisionMilestoneIds.filter(id => !keptIds.includes(id));
        if (toDelete.length) await supabaseClient.from('vision_goal_milestones').delete().in('id', toDelete);
        for (let i = 0; i < pendingVisionMilestones.length; i++) {
            const m = pendingVisionMilestones[i];
            if (m.id) {
                await supabaseClient.from('vision_goal_milestones').update({ title: m.title, sort_order: (i + 1) * 10 }).eq('id', m.id);
            } else {
                await supabaseClient.from('vision_goal_milestones').insert({ goal_id: goalId, user_id: currentUserId, title: m.title, is_done: false, sort_order: (i + 1) * 10 });
            }
        }
    } else {
        if (selectedVisionTemplateKey) payload.template_key = selectedVisionTemplateKey;
        const { data, error } = await supabaseClient.from('vision_goals').insert({ ...payload, user_id: currentUserId }).select().single();
        if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
        goalId = data.id;
        let milestones = [];
        if (pendingVisionMilestones.length) {
            const rows = pendingVisionMilestones.map((m, i) => ({ goal_id: goalId, user_id: currentUserId, title: m.title, is_done: false, sort_order: (i + 1) * 10 }));
            const { data: inserted } = await supabaseClient.from('vision_goal_milestones').insert(rows).select();
            milestones = (inserted || []).sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
        }
        // תוכנית מהספרייה עם "להוסיף לשגרה שלי" דלוק - גם אחרי עריכה
        if (visionPendingLibRoutine && typeof glibApplyRoutinePlan === 'function') await glibApplyRoutinePlan(data, milestones, visionPendingLibRoutine);
    }
    closeModal('modal-add-vision-goal');
    resetVisionGoalModal();
    showAppToast(t('item_added_success'));
    // היעד שנשמר הוא זה שרואים את השביל שלו
    visionSelectedGoalId = goalId;
    visionAnimatePath = true;
    try { localStorage.setItem(VISION_SELECTED_KEY, goalId); } catch {}
    await loadVisionGoals();
    // יעד מספר/משקל יכול להיות מושג כבר מהרגע הראשון
    if (track === 'number' || track === 'weight') await checkAndMarkGoalAchieved(goalId);
}

// הפריטים של היעד ב"השגרה שלי" (צעד קטן / תחנות / משימות יומיות) נמחקים איתו - וכתוב את זה באישור
function deleteVisionGoal(goalId) {
    const milestoneIds = new Set(visionMilestonesCache.filter(m => m.goal_id === goalId).map(m => m.id));
    const routineIds = [...visionGoalRoutineLinks.filter(r => r.vision_goal_id === goalId), ...visionRoutineLinks.filter(r => milestoneIds.has(r.vision_milestone_id))].map(r => r.id);
    const text = t('vision_goal_delete_confirm') + (routineIds.length ? ` ${t('vision_goal_delete_routine_note')}` : '');
    showDangerConfirm(t('vision_goal_delete_title'), text, async () => {
        if (routineIds.length) await supabaseClient.from('routine_items').delete().eq('user_id', currentUserId).in('id', routineIds);
        await supabaseClient.from('vision_goals').delete().eq('id', goalId);
        loadVisionGoals();
        const board = document.getElementById('modal-daily-board');
        if (routineIds.length && board && board.classList.contains('open')) renderDailyBoard();
    });
}


async function deleteActiveRoutineTab() {
    if (dailyBoardTabs.length <= 1) return;
    const tabId = activeDailyBoardTabId;
    showDangerConfirm(t('daily_board_delete_tab_title'), t('daily_board_delete_tab_confirm'), async () => {
        await supabaseClient.from('routine_tabs').delete().eq('id', tabId);
        dailyBoardTabs = dailyBoardTabs.filter(tb => tb.id !== tabId);
        activeDailyBoardTabId = dailyBoardTabs[0] ? dailyBoardTabs[0].id : null;
        renderRoutineTabsBar();
        await renderDailyBoard();
        refreshRoutineNudge();
    });
}

async function renderDailyBoard() {
    const body = document.getElementById('daily-board-body');
    if (!body) return;
    if (!activeDailyBoardTabId) { body.innerHTML = ''; return; }
    const { data: items } = await supabaseClient.from('routine_items').select('*').eq('tab_id', activeDailyBoardTabId).eq('user_id', currentUserId).eq('kind', 'scheduled');
    dailyBoardActiveItemCount = (items || []).length;
    const itemsByTime = {};
    (items || []).forEach(it => { itemsByTime[(it.time || '').slice(0, 5)] = it; });
    routineItemGoalLinks = new Map((items || []).filter(it => it.vision_milestone_id).map(it => [it.id, it.vision_milestone_id]));
    routineItemSmallStepLinks = new Map((items || []).filter(it => it.vision_goal_id).map(it => [it.id, it.vision_goal_id]));
    // מה כבר סומן היום (וי) - רק כשהמעקב דלוק, אחרת אין טעם בשאילתה
    const checksOn = isRoutineGoalsOn();
    let doneTodayIds = new Set();
    if (checksOn && items && items.length) {
        const { data: todayChecks } = await supabaseClient.from('routine_item_checkins').select('item_id').in('item_id', items.map(it => it.id)).eq('checkin_date', getLocalDateString());
        doneTodayIds = new Set((todayChecks || []).map(c => c.item_id));
    }
    const bucketOrder = ['morning', 'noon', 'afternoon', 'evening'];
    const bucketLabelKeys = { morning: 'daily_board_bucket_morning', noon: 'daily_board_bucket_noon', afternoon: 'daily_board_bucket_afternoon', evening: 'daily_board_bucket_evening' };
    const customHours = getDailyBoardCustomHours(activeDailyBoardTabId);
    body.innerHTML = '';
    bucketOrder.forEach(key => {
        const bucketHours = customHours[key] || [];
        if (!bucketHours.length) return;
        const section = document.createElement('div');
        section.className = `daily-board-bucket-section daily-board-bucket-${key}`;
        const header = document.createElement('div');
        header.className = 'daily-board-bucket-header';
        header.textContent = t(bucketLabelKeys[key]);
        section.appendChild(header);
        bucketHours.forEach(hour => {
            const timeStr = `${String(hour).padStart(2, '0')}:00`;
            const item = itemsByTime[timeStr];
            const row = document.createElement('div');
            row.className = 'daily-board-item-row' + (item ? '' : ' daily-board-item-row-empty');
            const timeSpan = document.createElement('span');
            timeSpan.className = 'daily-board-item-time';
            timeSpan.textContent = timeStr;
            const titleBtn = document.createElement('button');
            titleBtn.type = 'button';
            titleBtn.className = 'daily-board-item-title';
            titleBtn.textContent = item ? item.title : t('daily_board_item_add_placeholder');
            titleBtn.onclick = () => item ? openEditRoutineItemModal(item) : openAddRoutineItemModal(timeStr);
            if (checksOn && item) {
                const done = doneTodayIds.has(item.id);
                const checkBtn = document.createElement('button');
                checkBtn.type = 'button';
                checkBtn.className = 'btn-complete-item daily-board-item-check' + (done ? ' checked' : '');
                checkBtn.textContent = done ? '✓' : '';
                checkBtn.onclick = () => toggleRoutineItemCheckin(item.id, checkBtn);
                row.appendChild(checkBtn);
            } else if (checksOn) {
                // שורה ריקה בלי וי - מרווח באותו רוחב כדי שעמודת השעות תישאר מיושרת
                const spacer = document.createElement('span');
                spacer.className = 'daily-board-item-check-spacer';
                row.appendChild(spacer);
            }
            row.appendChild(timeSpan);
            row.appendChild(titleBtn);
            section.appendChild(row);
        });
        body.appendChild(section);
    });
}

function openAddRoutineItemModal(time) {
    if (!activeDailyBoardTabId) return;
    editingRoutineItemId = null;
    routineNudgeEditing = null;
    pendingRoutineItemTime = time;
    document.getElementById('routine-item-modal-title').textContent = t('daily_board_add_item_title');
    document.getElementById('routine-item-time-label').textContent = time;
    document.getElementById('routine-item-title-input').value = '';
    document.getElementById('routine-item-delete-btn').classList.add('hidden');
    openModalOverDailyBoard('modal-add-routine-item');
    setTimeout(() => document.getElementById('routine-item-title-input').focus(), 50);
}

// opts.fromNudge: נפתח מכרטיס ה-🌱 (✏️ לשנות) - אחרי שמירה הכרטיס לא שואל שוב 3 ימים
function openEditRoutineItemModal(item, opts = {}) {
    editingRoutineItemId = item.id;
    routineNudgeEditing = opts.fromNudge ? routineNudge : null;
    pendingRoutineItemTime = (item.time || '').slice(0, 5);
    document.getElementById('routine-item-modal-title').textContent = t('daily_board_edit_item_title');
    document.getElementById('routine-item-time-label').textContent = pendingRoutineItemTime;
    document.getElementById('routine-item-title-input').value = item.title;
    document.getElementById('routine-item-delete-btn').classList.remove('hidden');
    openModalOverDailyBoard('modal-add-routine-item');
}

async function saveRoutineItem() {
    const title = document.getElementById('routine-item-title-input').value.trim();
    if (!title) { showAppToast(t('daily_board_item_missing_fields'), 'error'); return; }
    const payload = { title, time: pendingRoutineItemTime };
    if (editingRoutineItemId) {
        await supabaseClient.from('routine_items').update(payload).eq('id', editingRoutineItemId);
    } else {
        await supabaseClient.from('routine_items').insert({ ...payload, tab_id: activeDailyBoardTabId, user_id: currentUserId });
    }
    closeModal('modal-add-routine-item');
    await renderDailyBoard();
    if (routineNudgeEditing) {
        const nudged = routineNudgeEditing;
        routineNudgeEditing = null;
        routineNudge = null;
        renderRoutineNudge();
        await snoozeRoutineNudgeItems(nudged.itemIds, 3);
        refreshRoutineNudge();
    }
}

async function deleteRoutineItemFromModal() {
    if (!editingRoutineItemId) return;
    await supabaseClient.from('routine_items').delete().eq('id', editingRoutineItemId);
    closeModal('modal-add-routine-item');
    routineNudgeEditing = null;
    await renderDailyBoard();
    refreshRoutineNudge();
}

async function addProgressTarget() {
    if (!supabaseClient) return;
    const nameInput = document.getElementById('progress-name-input');
    const targetInput = document.getElementById('progress-target-input');
    const name = nameInput.value.trim();
    const target = parseInt(targetInput.value) || 0;
    if (!name || target <= 0) return;
    await supabaseClient.from('weekly_progress_targets').insert({ username: currentUsername, user_id: currentUserId, target_name: name, target_val: target, current_val: 0 });
    nameInput.value = '';
    targetInput.value = '';
    loadProgressTargets();
}

// --- מד התקדמות שבועי: וי אמיתי לכל יום (לא רק מונה +/-), עם תאריך אמיתי
// מאחורי כל סימון (progress_checkins) - כדי שאפשר יהיה לחזור אחורה ולראות
// בדיוק אילו ימים סומנו בשבועות קודמים, אותו דפוס ניווט בדיוק כמו יעד חודשי ---
let viewedProgressWeekStart = null;

function getWeekStart(dateStr) {
    const [y, m, d] = dateStr.split('-').map(Number);
    const date = new Date(y, m - 1, d);
    date.setDate(date.getDate() - date.getDay()); // getDay(): 0=ראשון
    return getLocalDateString(date);
}

function currentWeekStart() { return getWeekStart(getLocalDateString()); }

function addDaysToDateStr(dateStr, days) {
    const [y, m, d] = dateStr.split('-').map(Number);
    return getLocalDateString(new Date(y, m - 1, d + days));
}

function formatWeekRangeLabel(weekStartStr) {
    const [y, m, d] = weekStartStr.split('-').map(Number);
    const start = new Date(y, m - 1, d);
    const end = new Date(y, m - 1, d + 6);
    const opts = { day: 'numeric', month: 'short' };
    return `${start.toLocaleDateString(currentLang, opts)} - ${end.toLocaleDateString(currentLang, opts)}`;
}

function navigateProgressWeek(delta) {
    const base = viewedProgressWeekStart || currentWeekStart();
    const target = addDaysToDateStr(base, delta * 7);
    if (target > currentWeekStart()) return; // בלי לנווט לשבועות עתידיים
    viewedProgressWeekStart = target;
    loadProgressTargets();
}

async function loadProgressTargets() {
    if (!supabaseClient || !currentUserId) return;
    if (!viewedProgressWeekStart) viewedProgressWeekStart = currentWeekStart();
    const label = document.getElementById('progress-week-label');
    if (label) label.textContent = formatWeekRangeLabel(viewedProgressWeekStart);
    const isCurrentWeek = viewedProgressWeekStart === currentWeekStart();
    const nextBtn = document.getElementById('progress-week-next-btn');
    if (nextBtn) nextBtn.disabled = isCurrentWeek;

    const { data: targets } = await supabaseClient.from('weekly_progress_targets').select('*').eq('user_id', currentUserId).order('created_at', { ascending: true });
    const container = document.getElementById('progress-container');
    if (!targets || !container) return;

    const weekEndExclusive = addDaysToDateStr(viewedProgressWeekStart, 7);
    const { data: checkins } = await supabaseClient.from('progress_checkins').select('target_id, check_date').eq('user_id', currentUserId).gte('check_date', viewedProgressWeekStart).lt('check_date', weekEndExclusive);
    const checkinsByTarget = {};
    (checkins || []).forEach(c => {
        if (!checkinsByTarget[c.target_id]) checkinsByTarget[c.target_id] = new Set();
        checkinsByTarget[c.target_id].add(c.check_date);
    });

    container.innerHTML = '';
    targets.forEach(item => {
        const checkedDates = checkinsByTarget[item.id] || new Set();
        const checkedCount = checkedDates.size;
        const pct = item.target_val > 0 ? Math.min(100, Math.round((checkedCount / item.target_val) * 100)) : 0;
        let daysHtml = '';
        for (let i = 0; i < 7; i++) {
            const dayDateStr = addDaysToDateStr(viewedProgressWeekStart, i);
            const isChecked = checkedDates.has(dayDateStr);
            const [dy, dm, dd] = dayDateStr.split('-').map(Number);
            const dayLabel = new Date(dy, dm - 1, dd).toLocaleDateString(currentLang, { weekday: 'narrow' });
            daysHtml += `<button type="button" class="progress-day-check${isChecked ? ' checked' : ''}" onclick="toggleProgressCheckin('${item.id}', '${dayDateStr}', ${!isChecked})" title="${dayDateStr}">${isChecked ? '✓' : dayLabel}</button>`;
        }
        const row = document.createElement('div');
        row.className = 'progress-row';
        row.innerHTML = `
            <div class="progress-info">
                <span>${item.target_name}</span>
                <div class="progress-counter">
                    <span>${checkedCount} / ${item.target_val}</span>
                    <button class="btn-delete-item" onclick="deleteProgressTarget('${item.id}')">❌</button>
                </div>
            </div>
            <div class="progress-days-row">${daysHtml}</div>
            <div class="progress-bar-bg"><div class="progress-bar-fill ${pct >= 100 ? 'completed' : ''}" style="width: ${pct}%;"></div></div>
        `;
        container.appendChild(row);
    });
}

async function toggleProgressCheckin(targetId, dateStr, shouldCheck) {
    if (!supabaseClient || !currentUserId) return;
    if (shouldCheck) {
        await supabaseClient.from('progress_checkins').insert({ user_id: currentUserId, username: currentUsername, target_id: targetId, check_date: dateStr });
    } else {
        await supabaseClient.from('progress_checkins').delete().eq('target_id', targetId).eq('check_date', dateStr).eq('user_id', currentUserId);
    }
    loadProgressTargets();
}

async function deleteProgressTarget(id) { await supabaseClient.from('weekly_progress_targets').delete().eq('id', id); loadProgressTargets(); }
// משותף למסך המשקל ול-New Me - שני המסכים כותבים לאותה טבלה בדיוק
async function insertWeightRecord(value, date, note) {
    const res = await supabaseClient.from('weight_tracker').insert({ username: currentUsername, user_id: currentUserId, weight_date: date, weight_value: value, note: note || null });
    // שקילה חדשה מעדכנת יעדי משקל ב"היעדים שלי" (ויכולה להשלים אותם)
    if (!res.error && typeof onWeightLoggedForGoals === 'function') onWeightLoggedForGoals();
    // הערכת השריפה באימונים הבאים לפי המשקל החדש
    if (!res.error) burnWeightKg = null;
    return res;
}
async function saveNewWeightRecord() { const w = document.getElementById('new-weight-val').value, d = document.getElementById('new-weight-date').value; const noteInput = document.getElementById('new-weight-note'); const note = noteInput ? noteInput.value.trim() : ''; await insertWeightRecord(w, d, note); if (noteInput) noteInput.value = ''; loadWeightHistory(); }
// note מוצג בצבע ההדגשה של ערכת הנושא (--accent-purple-text, אותו משתנה
// שכל הדגשה טקסטואלית אחרת באפליקציה משתמשת בו) - לפי בקשה מפורשת
async function loadWeightHistory() { const { data } = await supabaseClient.from('weight_tracker').select('*').eq('user_id', currentUserId).order('weight_date', { ascending: false }); const list = document.getElementById('weight-history-list'); if (!data) return; list.innerHTML = ''; data.forEach(item => list.innerHTML += `<li>${item.weight_value} ק״ג (${item.weight_date})${item.note ? ` <span class="weight-note-text">${escapeHtmlForReport(item.note)}</span>` : ''} <button onclick="deleteWeightRecord('${item.id}')">❌</button></li>`); }
async function deleteWeightRecord(id) { await supabaseClient.from('weight_tracker').delete().eq('id', id); loadWeightHistory(); }

// --- מד צעדים יומי: תצוגה בלבד, מקור הנתונים יהיה סנכרון אוטומטי עתידי ---
// (Google Fit / Apple Health) דרך אפליקציה נייטיבית - אין קלט ידני יותר.
async function loadDailySteps(date) {
    if (!supabaseClient || !currentUserId) return;
    document.getElementById('steps-today').innerText = '0';
    const { data, error } = await supabaseClient.from('step_tracker').select('*').eq('user_id', currentUserId).eq('step_date', date).maybeSingle();
    if (error) { showAppToast(t('error_loading_steps') + error.message, 'error'); return; }
    if (data) {
        document.getElementById('steps-today').innerText = data.step_count;
    }
    loadStepStats();
}

function connectHealthData() {
    showAppToast(t('steps_connect_toast'), 'error');
}

async function loadStepStats() {
    if (!supabaseClient || !currentUserId) return;
    const { data } = await supabaseClient.from('step_tracker').select('step_date, step_count').eq('user_id', currentUserId);
    if (!data) return;
    const now = new Date();
    const sunday = new Date(now); sunday.setDate(now.getDate() - now.getDay());
    const weekStartStr = getLocalDateString(sunday);
    const saturday = new Date(sunday); saturday.setDate(sunday.getDate() + 6);
    const weekEndStr = getLocalDateString(saturday);
    let weekly = 0;
    data.forEach(item => {
        if (item.step_date >= weekStartStr && item.step_date <= weekEndStr) weekly += Number(item.step_count) || 0;
    });
    document.getElementById('steps-weekly').innerText = weekly;
}

// --- מעקב מים: הוספה מהירה (כוס/בקבוק/כמות מותאמת), סך יומי+שבועי, יעד
// יומי (מקומי בלבד - localStorage, כמו שעות ברירת מחדל ללוח הזמנים) עם
// פס התקדמות, והיסטוריית היום עם מחיקה - אותו דפוס בדיוק כמו ספורט/משקל ---
function waterDailyGoalKey() {
    return `weekwise_water_goal_${currentUserId}`;
}

function getWaterDailyGoal() {
    return parseInt(localStorage.getItem(waterDailyGoalKey())) || 2000;
}

function saveWaterDailyGoal() {
    const val = parseInt(document.getElementById('water-daily-goal-input').value) || 2000;
    localStorage.setItem(waterDailyGoalKey(), String(val));
    loadWaterData();
}

async function addWaterLog(amountMl) {
    if (!supabaseClient || !currentUserId) return;
    const today = getLocalDateString();
    const { error } = await supabaseClient.from('water_logs').insert({ username: currentUsername, user_id: currentUserId, amount_ml: amountMl, log_date: today });
    if (error) { showAppToast(t('error_adding_item') + error.message, 'error'); return; }
    showAppToast(t('water_add_success'));
    loadWaterData();
}

function addCustomWaterLog() {
    const input = document.getElementById('water-custom-amount-input');
    const amount = parseInt(input.value) || 0;
    if (amount <= 0) { showAppToast(t('water_missing_amount'), 'error'); return; }
    input.value = '';
    addWaterLog(amount);
}

// אותו רעיון בדיוק כמו addCustomWaterLog, רק מהחלון הקטן של הכפתור הצף
// (שדה קלט נפרד) - כדי שגם מהבועה יהיה אפשר לרשום כמות מדויקת, לא רק
// כוס/בקבוק קבועים מראש
function addCustomWaterLogFromFab() {
    const input = document.getElementById('water-quick-add-custom-input');
    const amount = parseInt(input.value) || 0;
    if (amount <= 0) { showAppToast(t('water_missing_amount'), 'error'); return; }
    input.value = '';
    closeModal('modal-water-quick-add');
    addWaterLog(amount);
}

async function deleteWaterLog(id) {
    await supabaseClient.from('water_logs').delete().eq('id', id);
    loadWaterData();
}

function toggleWaterHistory() {
    const list = document.getElementById('water-history-list');
    const chevron = document.getElementById('water-history-chevron');
    if (!list) return;
    const isHidden = list.classList.toggle('hidden');
    if (chevron) chevron.textContent = isHidden ? '▶' : '▼';
}

// קונפטי חד-פעמי ביום שמגיעים ליעד - מסומן ב-localStorage (לא DB, זו רק
// אינדיקציה UI חולפת) כדי שלא יופיע שוב ושוב בכל הוספה נוספת של מים אחרי
// שכבר חצו את היעד היום
function celebrateWaterGoalIfNeeded(todayTotal, goal, today) {
    if (goal <= 0 || todayTotal < goal) return;
    const key = `weekwise_water_celebrated_${today}`;
    if (localStorage.getItem(key) === 'true') return;
    localStorage.setItem(key, 'true');
    const container = document.getElementById('water-confetti-container');
    if (!container) return;
    container.classList.remove('hidden');
    setTimeout(() => container.classList.add('hidden'), 2500);
    showAppToast(t('water_goal_reached'));
}

async function loadWaterData() {
    if (!supabaseClient || !currentUserId) return;
    const goal = getWaterDailyGoal();
    const goalInput = document.getElementById('water-daily-goal-input');
    if (goalInput) goalInput.value = goal;

    const now = new Date();
    const sunday = new Date(now); sunday.setDate(now.getDate() - now.getDay());
    const weekStartStr = getLocalDateString(sunday);
    const today = getLocalDateString();

    const { data } = await supabaseClient.from('water_logs').select('*').eq('user_id', currentUserId).gte('log_date', weekStartStr).order('created_at', { ascending: false });
    const rows = data || [];

    const todayRows = rows.filter(r => r.log_date === today);
    const todayTotal = todayRows.reduce((sum, r) => sum + (r.amount_ml || 0), 0);
    const weeklyTotal = rows.reduce((sum, r) => sum + (r.amount_ml || 0), 0);

    const todayEl = document.getElementById('water-today-total');
    if (todayEl) todayEl.textContent = todayTotal.toLocaleString();
    const weeklyEl = document.getElementById('water-weekly-total');
    if (weeklyEl) weeklyEl.textContent = weeklyTotal.toLocaleString();

    const fill = document.getElementById('water-goal-progress-fill');
    if (fill) fill.style.width = `${goal > 0 ? Math.min(100, Math.round((todayTotal / goal) * 100)) : 0}%`;

    const list = document.getElementById('water-history-list');
    if (list) {
        list.innerHTML = '';
        if (!todayRows.length) {
            list.innerHTML = `<li class="finance-history-empty">${t('water_history_empty')}</li>`;
        } else {
            todayRows.forEach(row => {
                const li = document.createElement('li');
                li.className = 'finance-history-row';
                li.innerHTML = `
                    <div class="finance-history-main">
                        <span class="finance-history-category">${row.amount_ml} ${t('water_ml_unit')}</span>
                    </div>
                    <button type="button" class="btn-delete-slot" onclick="deleteWaterLog('${row.id}')">❌</button>
                `;
                list.appendChild(li);
            });
        }
    }

    celebrateWaterGoalIfNeeded(todayTotal, goal, today);
}

// --- "AI" חוקי-דטרמיניסטי: מוסיף טקסט חופשי כפתק חדש בלשונית הפתקים בלבד ---
// אין מפתח API/LLM אמיתי - הטקסט מתווסף ישירות לרשימת הפתקים, ללא נגיעה
// בלוח הזמנים השבועי. מוחלף בעתיד ב-AI אמיתי מאחורי פרוקסי בצד שרת.
// דגל נגד הוספה כפולה (לפי בקשה מפורשת: פתק נוסף 5 פעמים כשהמחשב נתקע ו"הוספה" נלחץ שוב ושוב) -
// כל עוד השמירה רצה, לחיצות נוספות / Ctrl+Enter לא עושים כלום, והכפתור מושבת
let quickNoteAddInFlight = false;
async function handleAIQuickAdd() {
    if (quickNoteAddInFlight) return;
    const input = document.getElementById('ai-quick-add-input');
    const text = input.value.trim();
    if (!text) { showAppToast(t('notes_ai_empty'), 'error'); return; }
    quickNoteAddInFlight = true;
    const btn = document.getElementById('btn-ai-quick-add');
    if (btn) btn.disabled = true;
    try {
        const ok = await insertCenterItemDirect(quickNoteDestination, text, null, null, null, true);
        if (!ok) return;
        showAppToast(t(quickNoteDestination === 'general' ? 'notes_ai_added_shopping' : 'notes_ai_added'));
        input.value = '';
        closeModal('modal-ai-quick-add');
    } finally {
        quickNoteAddInFlight = false;
        if (btn) btn.disabled = false;
    }
}
